INSERT INTO Pokemon (pokedex_number, region_id, name, image, species, primary_type_id, secondary_type_id, primary_ability_id, secondary_ability_id, hidden_ability_id, description)
VALUES 
(1, NULL, 'Bulbasaur', '1.png', 'Seed Pokémon', 12, 4, 161, NULL, 27, 'For some time after its birth, it grows by taking nourishment from the seed on its back.'),
(2, NULL, 'Ivysaur', '2.png', 'Seed Pokémon', 12, 4, 161, NULL, 27, 'When the bud on its back starts swelling, a sweet aroma wafts to indicate the flower''s coming bloom.'),
(3, NULL, 'Venusaur', '3.png', 'Seed Pokémon', 12, 4, 161, NULL, 27, 'After a rainy day, the flower on its back smells stronger. The scent attracts other Pokémon.'),
(4, NULL, 'Charmander', '4.png', 'Lizard Pokémon', 10, NULL, 23, NULL, 231, 'The fire on the tip of its tail is a measure of its life. If the Pokémon is healthy, its tail burns intensely.'),
(5, NULL, 'Charmeleon', '5.png', 'Flame Pokémon', 10, NULL, 23, NULL, 231, 'In the rocky mountains where Charmeleon live, their fiery tails shine at night like stars.'),
(6, NULL, 'Charizard', '6.png', 'Flame Pokémon', 10, 3, 23, NULL, 231, 'It is said that Charizard''s fire burns hotter if it has experienced harsh battles.'),
(7, NULL, 'Squirtle', '7.png', 'Tiny Turtle Pokémon', 11, NULL, 274, NULL, 192, 'It hides in its shell to protect itself, then strikes back with spouts of water at every opportunity.'),
(8, NULL, 'Wartortle', '8.png', 'Turtle Pokémon', 11, NULL, 274, NULL, 192, 'It is said to live 10,000 years. Its furry tail is popular as a symbol of longevity.'),
(9, NULL, 'Blastoise', '9.png', 'Shellfish Pokémon', 11, NULL, 274, NULL, 192, 'The jets of water it spouts from the rocket cannons on its shell can punch through thick steel.'),
(10, NULL, 'Caterpie', '10.png', 'Worm Pokémon', 7, NULL, 222, NULL, 204, 'It releases a stench from its red antennae to repel enemies. It grows by molting repeatedly.'),
(11, NULL, 'Metapod', '11.png', 'Cocoon Pokémon', 7, NULL, 219, NULL, NULL, 'A steel-hard shell protects its tender body. The Pokémon quietly endures hardships while awaiting evolution.'),
(12, NULL, 'Butterfree', '12.png', 'Butterfly Pokémon', 7, 3, 34, NULL, 273, 'It loves the nectar of flowers and can locate flower patches that have even tiny amounts of pollen.'),
(13, NULL, 'Weedle', '13.png', 'Hairy Bug Pokémon', 7, 4, 222, NULL, 204, 'It eats its weight in leaves every day. It fends off attackers with the needle on its head.'),
(14, NULL, 'Kakuna', '14.png', 'Cocoon Pokémon', 7, 4, 219, NULL, NULL, 'While awaiting evolution, it hides from predators under leaves and in nooks of branches.'),
(15, NULL, 'Beedrill', '15.png', 'Poison Bee Pokémon', 7, 4, 256, NULL, 228, 'Its best attack involves flying around at high speed, striking with poison needles, then flying off.'),
(16, NULL, 'Pidgey', '16.png', 'Tiny Bird Pokémon', 1, 3, 119, 263, 22, 'It is docile and prefers to avoid conflict. If disturbed, however, it can ferociously strike back.'),
(17, NULL, 'Pidgeotto', '17.png', 'Bird Pokémon', 1, 3, 119, 263, 22, 'It flies over its wide territory in search of prey, downing it with its highly developed claws.'),
(18, NULL, 'Pidgeot', '18.png', 'Bird Pokémon', 1, 3, 119, 263, 22, 'By flapping its wings with all its might, Pidgeot can make a gust of wind capable of bending tall trees.'),
(19, NULL, 'Rattata', '19.png', 'Mouse Pokémon', 1, NULL, 204, 90, 100, 'It''s cautious in the extreme, and its hardy vitality lets it live in any kind of environment.'),
(19, 1, 'Rattata', '19-alolalola.png', 'Mouse Pokémon', 17, 1, 81, 100, 272, 'Its whiskers provide it with a keen sense of smell, enabling it to pick up the scent of hidden food and locate it instantly.'),
(20, NULL, 'Raticate', '20.png', 'Mouse Pokémon', 1, NULL, 204, 90, 100, 'It whittles down its constantly growing fangs by gnawing on hard things. It can chew apart cinder block walls.'),
(20, 1, 'Raticate', '20-alola.png', 'Mouse Pokémon', 17, 1, 81, 100, 272, 'It makes its Rattata underlings gather food for it, dining solely on the most nutritious and delicious fare.'),
(21, NULL, 'Spearow', '21.png', 'Tiny Bird Pokémon', 1, 3, 119, NULL, 228, 'It flaps its small wings busily to fly. Using its beak, it searches in grass for prey.'),
(22, NULL, 'Fearow', '22.png', 'Beak Pokémon', 1, 3, 119, NULL, 228, 'It has the stamina to fly all day on its broad wings. It fights by using its sharp beak.'),
(23, NULL, 'Ekans', '23.png', 'Snake Pokémon', 4, NULL, 114, 219, 286, 'It sneaks through grass without making a sound and strikes unsuspecting prey from behind.'),
(24, NULL, 'Arbok', '24.png', 'Cobra Pokémon', 4, NULL, 114, 219, 286, 'The pattern on its belly is for intimidation. It constricts foes while they are frozen in fear.'),
(25, NULL, 'Pikachu', '25.png', 'Mouse Pokémon', 13, NULL, 241, NULL, 125, 'When it is angered, it immediately discharges the energy stored in the pouches in its cheeks.'),
(26, NULL, 'Raichu', '26.png', 'Mouse Pokémon', 13, NULL, 241, NULL, 125, 'Its tail discharges electricity into the ground, protecting it from getting shocked.'),
(26, 1, 'Raichu', '26-alola.png', 'Mouse Pokémon', 13, 14, 255, NULL, NULL, 'This Pokémon rides on its tail while it uses its psychic powers to levitate. It attacks with star-shaped thunderbolts.'),
(27, NULL, 'Sandshrew', '27.png', 'Mouse Pokémon', 5, NULL, 209, NULL, 206, 'To protect itself from attackers, it curls up into a ball. It lives in arid regions with minimal rainfall.'),
(27, 1, 'Sandshrew', '27-alola.png', 'Mouse Pokémon', 15, 9, 229, NULL, 227, 'It lives in snowy mountains on southern islands. When a blizzard rolls in, this Pokémon hunkers down in the snow to avoid getting blown away.'),
(28, NULL, 'Sandslash', '28.png', 'Mouse Pokémon', 5, NULL, 209, NULL, 206, 'It curls up, then rolls into foes with its back. Its sharp spines inflict severe damage.'),
(28, 1, 'Sandslash', '28-alola.png', 'Mouse Pokémon', 15, 9, 229, NULL, 227, 'Many people climb snowy mountains, hoping to see the icy spikes of these Pokémon glistening in the light of dawn.'),
(29, NULL, 'Nidoran (female)', '29.png', 'Poison Pin Pokémon', 4, NULL, 171, 199, 100, 'While this Pokémon does not prefer to fight, even one drop of the venom it secretes from its barbs can be fatal.'),
(30, NULL, 'Nidorina', '30.png', 'Poison Pin Pokémon', 4, NULL, 171, 199, 100, 'When it senses danger, it raises all the barbs on its body. These barbs grow more slowly than Nidorino''s.'),
(31, NULL, 'Nidoqueen', '31.png', 'Drill Pokémon', 4, 5, 171, 199, 100, 'Its entire body is armored with hard scales. It will protect the young in its burrow with its life.'),
(32, NULL, 'Nidoran (male)', '32.png', 'Poison Pin Pokémon', 4, NULL, 171, 199, 100, 'It scans its surroundings by raising its ears out of the grass. Its toxic horn is for protection.'),
(33, NULL, 'Nidorino', '33.png', 'Poison Pin Pokémon', 4, NULL, 171, 199, 100, 'It has a violent disposition and stabs foes with its horn, which oozes venom upon impact.'),
(34, NULL, 'Nidoking', '34.png', 'Drill Pokémon', 4, 5, 171, 199, 100, 'One swing of its mighty tail can snap a telephone pole as if it were a matchstick.'),
(35, NULL, 'Clefairy', '35.png', 'Fairy Pokémon', 18, NULL, 42, 132, 75, 'It can be found in quiet mountain areas on a full moon''s night. Its dancing and its tiny, faintly glowing wings confer upon it a lovely fairylike quality.'),
(36, NULL, 'Clefable', '36.png', 'Fairy Pokémon', 18, NULL, 42, 132, 75, 'Legend says that on clear, quiet nights, it listens for the voices of its kin living on the moon. I, too, often think of my homeland, so far away.'),
(37, NULL, 'Vulpix', '37.png', 'Fox Pokémon', 10, NULL, 69, NULL, 56, 'In its belly burns a fire, which Vulpix spits out in the form of fireballs. When young, this Pokémon has but one white tail. As the Pokémon matures, this single tail splits into six.'),
(37, 1, 'Vulpix', '37-alola.png', 'Fox Pokémon', 15, NULL, 229, NULL, 230, 'These Pokémon live in packs in the snowy mountains and defend themselves with icy breath. I suspect this species changed its form to adapt to the frigid climate.'),
(38, NULL, 'Ninetales', '38.png', 'Fox Pokémon', 10, NULL, 69, NULL, 56, 'The coat of gleaming golden fur is quite magnificent. This species is said to store sacred power in its nine long tails and to live for a millennium.'),
(38, 1, 'Ninetales', '38-alola.png', 'Fox Pokémon', 15, NULL, 229, NULL, 230, 'Dwells on sacred peaks perpetually covered in snow. Said to appear to virtuous people who have lost their way on mountain paths—it then guides them back down to the mountain''s base.'),
(39, NULL, 'Jigglypuff', '39.png', 'Balloon Pokémon', 1, 18, 42, 33, 75, 'When its huge eyes waver, it sings a mysteriously soothing melody that lulls its enemies to sleep.'),
(40, NULL, 'Wigglytuff', '40.png', 'Balloon Pokémon', 1, 18, 42, 33, 75, 'The rich, fluffy fur that covers its body feels so good that anyone who feels it can''t stop touching it.'),
(41, NULL, 'Zubat', '41.png', 'Bat Pokémon', 4, 3, 112, NULL, 110, 'Makes its home in gloomy caves. Atrophied eyes have left this Pokémon blind, so it scans its surroundings via sound waves that it emits from its mouth as it flies.'),
(42, NULL, 'Golbat', '42.png', 'Bat Pokémon', 4, 3, 112, NULL, 110, 'It sinks its sharp fangs into other creatures and slurps up their blood. A closer look at the fangs reveals that they are hollow and akin to straws.'),
(43, NULL, 'Oddish', '43.png', 'Weed Pokémon', 12, 4, 27, NULL, 204, 'It often plants its root feet in the ground during the day and sows seeds as it walks about at night.'),
(44, NULL, 'Gloom', '44.png', 'Weed Pokémon', 12, 4, 27, NULL, 246, 'The nectar it drools from its mouth smells so atrocious that it can make noses curl from more than a mile away.'),
(45, NULL, 'Vileplume', '45.png', 'Flower Pokémon', 12, 4, 27, NULL, 60, 'Its petals are the largest in the world. As it walks, it scatters extremely allergenic pollen.'),
(46, NULL, 'Paras', '46.png', 'Mushroom Pokémon', 7, 12, 60, 57, 43, 'Sometimes seen at the foot of trees in humid forests. The mushrooms on its back—called tochukaso—are not present on infant specimens and instead emerge as Paras matures.'),
(47, NULL, 'Parasect', '47.png', 'Mushroom Pokémon', 7, 12, 60, 57, 43, 'Mushroom-lacking specimens of this Pokémon lie unmoving in the forest, lending credence to the hypothesis that the large mushroom is in control of Parasect''s actions.'),
(48, NULL, 'Venonat', '48.png', 'Insect Pokémon', 7, 4, 34, 273, 204, 'Its eyes act as radar, enabling it to be active in darkness. The eyes can also shoot powerful beams.'),
(49, NULL, 'Venomoth', '49.png', 'Poison Moth Pokémon', 7, 4, 222, 273, 304, 'The wings are covered with dustlike scales. Every time it flaps its wings, it looses highly toxic dust.'),
(50, NULL, 'Diglett', '50.png', 'Mole Pokémon', 5, NULL, 209, 9, 205, 'It lives about one yard underground, where it feeds on plant roots. It sometimes appears aboveground.'),
(50, 1, 'Diglett', '50-alola.png', 'Mole Pokémon', 5, 9, 209, 264, 205, 'Its three hairs change shape depending on Diglett''s mood. They''re a useful communication tool among these Pokémon.'),
(51, NULL, 'Dugtrio', '51.png', 'Mole Pokémon', 5, NULL, 209, 9, 205, 'Its three heads bob separately up and down to loosen the soil nearby, making it easier for it to burrow.'),
(51, 1, 'Dugtrio', '51-alola.png', 'Mole Pokémon', 5, 9, 209, 264, 205, 'Their beautiful, metallic whiskers create a sort of protective helmet on their heads, and they also function as highly precise sensors.'),
(52, NULL, 'Meowth', '52.png', 'Scratch Cat Pokémon', 1, NULL, 167, 265, 286, 'It loves things that sparkle. When it sees a shiny object, the gold coin on its head shines, too.'),
(52, 1, 'Meowth', '52-alola.png', 'Scratch Cat Pokémon', 17, NULL, 167, 265, 193, 'Deeply proud and keenly smart, this Pokémon moves with cunning during battle and relentlessly attacks enemies'' weak points.'),
(52, 2, 'Meowth', '52-galar.png', 'Scratch Cat Pokémon', 9, NULL, 167, 275, 286, 'These daring Pokémon have coins on their foreheads. Darker coins are harder, and harder coins garner more respect among Meowth.'),
(53, NULL, 'Persian', '53.png', 'Classy Cat Pokémon', 1, NULL, 126, 265, 286, 'It has a vicious temperament. Beware if it raises its tail straight up. This is a signal that it is about to pounce and bite.'),
(53, 1, 'Persian', '53-alola.png', 'Classy Cat Pokémon', 17, NULL, 78, 265, 193, 'This Pokémon is one tough opponent. Not only does it have formidable physical abilities, but it''s also not above fighting dirty.'),
(54, NULL, 'Psyduck', '54.png', 'Duck Pokémon', 11, NULL, 43, 29, 258, 'It is constantly wracked by a headache. When the headache turns intense, it begins using mysterious powers.'),
(55, NULL, 'Golduck', '55.png', 'Duck Pokémon', 11, NULL, 43, 29, 258, 'When it swims at full speed using its long, webbed limbs, its forehead somehow begins to glow.'),
(56, NULL, 'Mankey', '56.png', 'Pig Monkey Pokémon', 2, NULL, 290, 6, 49, 'It is extremely quick to anger. It could be docile one moment, then thrashing away the next instant.'),
(57, NULL, 'Primeape', '57.png', 'Pig Monkey Pokémon', 2, NULL, 290, 6, 49, 'It becomes wildly furious if it even senses someone looking at it. It chases anyone that meets its glare.'),
(58, NULL, 'Growlithe', '58.png', 'Puppy Pokémon', 10, NULL, 114, 69, 118, 'It has a brave and trustworthy nature. It fearlessly stands up to bigger and stronger foes.'),
(58, 3, 'Growlithe', '58-hisui.png', 'Scout Pokémon', 10, 6, 114, 69, 201, 'They patrol their territory in pairs. I believe the igneous rock components in the fur of this species are the result of volcanic activity in its habitat.'),
(59, NULL, 'Arcanine', '59.png', ' Pokémon', 10, NULL, 114, 69, 118, 'Its magnificent bark conveys a sense of majesty. Anyone hearing it can''t help but grovel before it.'),
(59, 3, 'Arcanine', '59-hisui.png', ' Pokémon', 10, 6, 114, 69, 201, 'Snaps at its foes with fangs cloaked in blazing flame. Despite its bulk, it deftly feints every which way, leading opponents on a deceptively merry chase as it all but dances around them.'),
(60, NULL, 'Poliwag', '60.png', 'Tadpole Pokémon', 11, NULL, 293, 43, 258, 'Its skin is so thin, its internal organs are visible. It has trouble walking on its newly grown feet.'),
(61, NULL, 'Poliwhirl', '61.png', 'Tadpole Pokémon', 11, NULL, 293, 43, 258, 'The spiral pattern on its belly subtly undulates. Staring at it gradually causes drowsiness.'),
(62, NULL, 'Poliwrath', '62.png', 'Tadpole Pokémon', 11, 2, 293, 43, 258, 'With its extremely tough muscles, it could keep swimming in the Pacific Ocean without resting.'),
(63, NULL, 'Abra', '63.png', 'Psi Pokémon', 14, NULL, 261, 112, 132, 'Spends 18 hours of the day sleeping. Even while asleep, Abra can control its psychic powers—should danger approach, the Pokémon will simply teleport away.'),
(64, NULL, 'Kadabra', '64.png', 'Psi Pokémon', 14, NULL, 261, 112, 132, 'There are rumors that a child with mystical powers became a Kadabra; however, this remains unverified. I suspect that the spoon Kadabra holds enhances its brain waves.'),
(65, NULL, 'Alakazam', '65.png', 'Psi Pokémon', 14, NULL, 261, 112, 132, 'The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.'),
(66, NULL, 'Machop', '66.png', 'Superpower Pokémon', 2, NULL, 90, 155, 242, 'Though as small as a child, it has strength enough to easily throw a well-built adult. Striving to become ever stronger, Machop trains by carrying a Graveler on its shoulders.'),
(67, NULL, 'Machoke', '67.png', 'Superpower Pokémon', 2, NULL, 90, 155, 242, 'A sturdy creature boasting a robust physique and boundless stamina. Loves training above all else and voluntarily assists with tasks such as construction and clearing land.'),
(68, NULL, 'Machamp', '68.png', 'Superpower Pokémon', 2, NULL, 90, 155, 242, 'In close combat, its four arms afford it offensive and defensive supremacy. In but a blink, this valiant Pokémon can overwhelm its foes with more than 1,000 blows from its fists.'),
(69, NULL, 'Bellsprout', '69.png', 'Flower Pokémon', 12, 4, 27, NULL, 81, 'It prefers hot and humid environments. It is quick at capturing prey with its vines.'),
(70, NULL, 'Weepinbell', '70.png', 'Flycatcher Pokémon', 12, 4, 27, NULL, 81, 'This Pokémon has the appearance of a plant. It captures unwary prey by dousing them with a toxic powder.'),
(71, NULL, 'Victreebel', '71.png', 'Flycatcher Pokémon', 12, 4, 27, NULL, 81, 'In its mouth, it pools a fragrant nectar-like fluid. The fluid is really an acid that dissolves anything.'),
(72, NULL, 'Tentacool', '72.png', 'Jellyfish Pokémon', 11, 4, 28, 128, 192, 'They fire beams from the glassy, magenta orbs that resemble eyes atop their heads, and they drift in shallow seas. During low tide, they can sometimes be found on beaches, desiccated.'),
(73, NULL, 'Tentacruel', '73.png', 'Jellyfish Pokémon', 11, 4, 28, 128, 192, 'It has 80 tentacles, each with a venomous tip. These tentacles are also extendible, lengthening when Tentacruel attempts to catch prey. Use caution.'),
(74, NULL, 'Geodude', '74.png', 'Rock Pokémon', 6, 5, 201, 250, 209, 'Makes its home in mountainous regions, using its arms to climb along harsh mountain roads. Can be troublesome—carelessly kicking one will cause it to fly into a rage and chase after you.'),
(74, 1, 'Geodude', '74-alola.png', 'Rock Pokémon', 6, 13, 135, 250, 80, 'Its stone head is imbued with electricity and magnetism. If you carelessly step on one, you''ll be in for a painful shock.'),
(75, NULL, 'Graveler', '75.png', 'Rock Pokémon', 6, 5, 201, 250, 209, 'Dwells in holes dug into sheer walls of stone. It enjoys rolling down slopes as though it were a boulder during a rockfall, so keep an eye upward while traversing mountain roads.'),
(75, 1, 'Graveler', '75-alola.png', 'Rock Pokémon', 6, 13, 135, 250, 80, 'When it comes rolling down a mountain path, anything in its way gets zapped by electricity and sent flying.'),
(76, NULL, 'Golem', '76.png', 'Rock Pokémon', 6, 5, 201, 250, 209, 'The rocklike shell is shed each year. The cast-off shell then crumbles, reverting to a mass of soil, which can be spread across fields to promote crop growth.'),
(76, 1, 'Golem', '76-alola.png', 'Rock Pokémon', 6, 13, 135, 250, 80, 'It uses magnetism to accelerate and fire off rocks tinged with electricity. Even if it doesn''t score a direct hit, the jolt of electricity will do the job.'),
(77, NULL, 'Ponyta', '77.png', 'Fire Horse Pokémon', 10, NULL, 204, 69, 67, 'These Pokémon live in herds out in the grassland. Newborn foals lack their fiery manes, which will develop about an hour after birth.'),
(77, 2, 'Ponyta', '77-galar.png', 'Unique Horn Pokémon', 14, NULL, 204, 164, 8, 'This Pokémon will look into your eyes and read the contents of your heart. If it finds evil there, it promptly hides away.'),
(78, NULL, 'Rapidash', '78.png', 'Fire Horse Pokémon', 10, NULL, 204, 69, 67, 'Fiery mane aglow, Rapidash darts like an arrow across the land. This prodigiously swift creature can traverse the vast region of Hisui in a day and a half.'),
(78, 2, 'Rapidash', '78-galar.png', 'Unique Horn Pokémon', 14, 18, 204, 164, 8, 'Brave and prideful, this Pokémon dashes airily through the forest, its steps aided by the psychic power stored in the fur on its fetlocks.'),
(79, NULL, 'Slowpoke', '79.png', 'Dopey Pokémon', 11, 14, 157, 162, 197, 'It is always vacantly lost in thought, but no one knows what it is thinking about. It is good at fishing with its tail.'),
(79, 2, 'Slowpoke', '79-galar.png', 'Dopey Pokémon', 14, NULL, 81, 162, 197, 'Because Galarian Slowpoke eat the seeds of a plant that grows only in Galar, their tails have developed a spicy flavor.'),
(80, NULL, 'Slowbro', '80.png', 'Hermit Crab Pokémon', 11, 14, 157, 162, 197, 'If the tail-biting Shellder is thrown off in a harsh battle, this Pokémon reverts to being an ordinary Slowpoke.'),
(80, 2, 'Slowbro', '80-galar.png', 'Hermit Crab Pokémon', 4, 14, 190, 162, 197, 'If this Pokémon squeezes the tongue of the Shellder biting it, the Shellder will launch a toxic liquid from the tip of its shell.'),
(81, NULL, 'Magnemite', '81.png', 'Magnet Pokémon', 13, 9, 135, 250, 5, 'It moves while constantly hovering. It discharges electromagnetic waves and so on from the units at its sides.'),
(28, NULL, 'Magneton', '82.png', 'Magnet Pokémon', 13, 9, 135, 250, 5, 'Three Magnemite are linked by a strong magnetic force. Earaches will occur if you get too close.'),
(83, NULL, 'Farfetch''d', '83.png', 'Wild Duck Pokémon', 1, 3, 119, 112, 49, 'It can''t live without the stalk it holds. That''s why it defends the stalk from attackers with its life.'),
(83, 2, 'Farfetch''d', '83-galar.png', 'Wild Duck Pokémon', 2, NULL, 242, NULL, 212, 'The Farfetch''d of the Galar region are brave warriors, and they wield thick, tough leeks in battle.'),
(84, NULL, 'Doduo', '84.png', 'Twin Bird Pokémon', 1, 3, 204, 58, 263, 'The brains in its two heads appear to communicate emotions to each other with a telepathic power.'),
(85, NULL, 'Dodrio', '85.png', 'Triple Bird Pokémon', 1, 3, 204, 58, 263, 'When Doduo evolves into this odd breed, one of its heads splits into two. This Pokémon runs at nearly 40 mph.'),
(86, NULL, 'Seel', '86.png', 'Sea Lion Pokémon', 11, NULL, 272, 101, 103, 'This Pokémon lives on icebergs. It uses the sharp point on its head to break up ice as it swims in the sea.'),
(87, NULL, 'Dewgong', '87.png', 'Sea Lion Pokémon', 11, 15, 272, 101, 103, 'In snow, the pure white coat covering its body obscures it from predators.'),
(88, NULL, 'Grimer', '88.png', 'Sludge Pokémon', 4, NULL, 246, 247, 173, 'Born from sludge, these Pokémon now gather in polluted places and increase the bacteria in their bodies.'),
(88, 1, 'Grimer', '88-alola.png', 'Sludge Pokémon', 4, 17, 173, 81, 175, 'It has a passion for trash above all else, speedily digesting it and creating brilliant crystals of sparkling poison.'),
(89, NULL, 'Muk', '89.png', 'Sludge Pokémon', 4, NULL, 246, 247, 173, 'It''s thickly covered with a filthy, vile sludge. It is so toxic, even its footprints contain poison.'),
(89, 1, 'Muk', '89-alola.png', 'Sludge Pokémon', 4, 17, 173, 81, 175, 'What look like fangs and claws are actually crystallized poison that will afflict you at a mere touch, so don''t get too close.'),
(90, NULL, 'Shellder', '90.png', 'Bivalve Pokémon', 11, NULL, 221, 225, 160, 'Clamping on to an opponent reveals its vulnerable parts, so it uses this move only as a last resort.'),
(91, NULL, 'Cloyster', '91.png', 'Bivalve Pokémon', 11, 15, 221, 225, 160, 'When attacked, it launches its spikes in quick volleys. Its innards have never been seen.'),
(92, NULL, 'Gastly', '92.png', 'Gas Pokémon', 8, 4, 122, NULL, NULL, 'Its body is made of gas. Despite lacking substance, it can envelop an opponent of any size and cause suffocation.'),
(93, NULL, 'Haunter', '93.png', 'Gas Pokémon', 8, 4, 122, NULL, NULL, 'It likes to lurk in the dark and tap shoulders with a gaseous hand. Its touch causes endless shuddering.'),
(94, NULL, 'Gengar', '94.png', 'Shadow Pokémon', 8, 4, 41, NULL, NULL, 'To steal the life of its target, it slips into the prey''s shadow and silently waits for an opportunity.'),
(95, NULL, 'Onix', '95.png', 'Rock Snake Pokémon', 6, 5, 201, 250, 297, 'This chain of immense stones resembles a giant serpent. Tremors shake the earth above as it burrows deep beneath the ground, feeding on boulders as it goes.'),
(96, NULL, 'Drowzee', '96.png', 'Hypnosis Pokémon', 14, NULL, 113, 74, 112, 'It remembers every dream it eats. It rarely eats the dreams of adults because children''s are much tastier.'),
(97, NULL, 'Hypno', '97.png', 'Hypnosis Pokémon', 14, NULL, 113, 74, 112, 'Always holding a pendulum that it swings at a steady rhythm, it causes drowsiness in anyone nearby.'),
(98, NULL, 'Krabby', '98.png', 'River Crab Pokémon', 11, NULL, 102, 221, 220, 'It lives in burrows dug on sandy beaches. Its pincers fully grow back if they are lost in battle.'),
(99, NULL, 'Kingler', '99.png', 'Pincer Pokémon', 11, NULL, 102, 221, 220, 'The larger pincer has 10,000-horsepower strength. However, it is so heavy, it is difficult to aim.'),
(100, NULL, 'Voltorb', '100.png', 'Ball Pokémon', 13, NULL, 234, 241, 3, 'It rolls to move. If the ground is uneven, a sudden jolt from hitting a bump can cause it to explode.'),
(100, 3, 'Voltorb', '100-hisui.png', 'Sphere Pokémon', 13, 12, 234, 241, 3, 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.'),
(101, NULL, 'Electrode', '101.png', 'Ball Pokémon', 13, NULL, 234, 241, 3, 'It explodes in response to even minor stimuli. It is feared, with the nickname of the Bomb Ball.'),
(101, 3, 'Electrode', '101-hisui.png', 'Sphere Pokémon', 13, 12, 234, 241, 3, 'The tissue on the surface of its body is curiously similar in composition to an Apricorn. When irritated, this Pokémon lets loose an electric current equal to 20 lightning bolts.'),
(102, NULL, 'Exeggcute', '102.png', 'Egg Pokémon', 12, 14, 27, NULL, 92, 'Its six eggs converse using telepathy. They can quickly gather if they become separated.'),
(103, NULL, 'Exeggutor', '103.png', 'Coconut Pokémon', 12, 14, 27, NULL, 92, 'It is called the Walking Jungle. If a head grows too big, it falls off and becomes an Exeggcute.'),
(103, 1, 'Exeggutor', '103-alola.png', 'Coconut Pokémon', 12, 16, 76, NULL, 92, 'This Pokémon''s psychic powers aren''t as strong as they once were. The head on this Exeggutor''s tail scans surrounding areas with weak telepathy.'),
(104, NULL, 'Cubone', '104.png', 'Lonely Pokémon', 5, NULL, 201, 125, 17, 'This Pokémon wears the skull of its deceased mother. Sometimes Cubone''s dreams make it cry, but each tear Cubone sheds makes it stronger.'),
(105, NULL, 'Marowak', '105.png', 'Bone Keeper Pokémon', 5, NULL, 201, 125, 17, 'The bones it uses have been in its possession since it was born. It has a ferocious nature.'),
(105, 1, 'Marowak', '105-alola.png', 'Bone Keeper Pokémon', 10, 8, 41, 125, 201, 'The cursed flames that light up the bone carried by this Pokémon are said to cause both mental and physical pain that will never fade.'),
(106, NULL, 'Hitmonlee', '106.png', 'Kicking Pokémon', 2, NULL, 126, 195, 285, 'Its legs can stretch to double their length. First-time foes are startled by Hitmonlee''s extensible reach.'),
(107, NULL, 'Hitmonchan', '107.png', 'Punching Pokémon', 2, NULL, 119, 117, 112, 'When Hitmonchan twists its arm while throwing a punch, the blow will pulverize even concrete. The Pokémon rests after three minutes of fighting.'),
(108, NULL, 'Lickitung', '108.png', 'Licking Pokémon', 1, NULL, 162, 157, 29, 'Wields its long tongue deftly, as though it were an arm. The Pokémon''s viscous saliva, once it has been collected and boiled down, yields a strong and highly useful adhesive.'),
(109, NULL, 'Koffing', '109.png', 'Poison Gas Pokémon', 4, NULL, 122, 154, 246, 'Toxic gas is held within its thin, balloon-shaped body, so it can cause massive explosions.'),
(110, NULL, 'Weezing', '110.png', 'Poison Gas Pokémon', 4, NULL, 122, 154, 246, 'It grows by feeding on gases released by garbage. Though very rare, triplets have been found.'),
(110, 2, 'Weezing', '110-galar.png', 'Poison Gas Pokémon', 4, 18, 122, 154, 143, 'Long ago, during a time when droves of factories fouled the air with pollution, Weezing changed into this form for some reason.'),
(111, NULL, 'Rhyhorn', '111.png', 'Spikes Pokémon', 5, 6, 125, 201, 195, 'Ludicrously strong—when it butts heads with a mountain, it is the mountain that shatters. But its short legs struggle with turns, and it is incapable of stopping unless it collides with something.'),
(112, NULL, 'Rhydon', '112.png', 'Drill Pokémon', 5, 6, 125, 201, 195, 'Rapidly rotates its horn to bore through bedrock. It swaggers around volcanic regions, protected from the lava''s heat by its tough, armorlike hide.'),
(113, NULL, 'Chansey', '113.png', 'Egg Pokémon', 1, NULL, 152, 215, 93, 'This kindly Pokémon lays highly nutritious eggs and shares them with injured Pokémon or people.'),
(114, NULL, 'Tangela', '114.png', 'Vine Pokémon', 12, NULL, 27, 121, 197, 'It is cloaked entirely in blue vines, preventing any glimpse of its true identity. The vines impart a refreshing sensation when chewed—they''re useful as a spice.'),
(115, NULL, 'Kangaskhan', '115.png', 'Parent Pokémon', 1, NULL, 58, 212, 112, 'It raises its offspring in its belly pouch. It lets its baby out to play only when it feels safe to do so.'),
(116, NULL, 'Horsea', '116.png', 'Dragon Pokémon', 11, NULL, 258, 228, 43, 'It makes its nest in the shade of corals. If it senses danger, it spits black ink and flees.'),
(117, NULL, 'Seadra', '117.png', 'Dragon Pokémon', 11, NULL, 258, 228, 43, 'Its spines provide protection. Its fins and bones are prized as traditional medicine ingredients.'),
(118, NULL, 'Goldeen', '118.png', 'Goldfish Pokémon', 11, NULL, 258, 296, 125, 'It swims at a steady five knots. If it senses danger, it will strike back with its sharp horn.'),
(119, NULL, 'Seaking', '119.png', 'Goldfish Pokémon', 11, NULL, 258, 296, 125, 'To protect its family, it will fight with its drill-sharp horn. It lives in hollowed rocks in streams.'),
(120, NULL, 'Staryu', '120.png', 'Star Shape Pokémon', 11, NULL, 106, 152, 5, 'If Staryu''s body is damaged, it will regenerate as long as the red core remains. The core flashes at midnight.'),
(121, NULL, 'Starmie', '121.png', 'Mysterious Pokémon', 11, NULL, 106, 152, 5, 'At the center of its body is a red core that sends mysterious radio signals into the night sky.'),
(122, NULL, 'Mr. Mime', '122.png', 'Barrier Pokémon', 14, 18, 234, 66, 265, 'The behavior of this clown-like Pokémon reminds one of pantomime. It creates invisible walls using a force emitted from its fingertips.'),
(122, 2, 'Mr. Mime', '122-galar.png', 'Dancing Pokémon', 15, 14, 290, 213, 103, 'Its talent is tap-dancing. It can also manipulate temperatures to create a floor of ice, which this Pokémon can kick up to use as a barrier.'),
(123, NULL, 'Scyther', '123.png', 'Mantis Pokémon', 7, 3, 256, 265, 242, 'The sharp scythes on its forearms become increasingly sharp by cutting through hard objects.'),
(124, NULL, 'Jynx', '124.png', 'Human Shape Pokémon', 15, 14, 157, 74, 57, 'Its cries sound like human speech. However, it is impossible to tell what it is trying to say.'),
(125, NULL, 'Electabuzz', '125.png', 'Electric Pokémon', 13, NULL, 241, NULL, 290, 'Feeds on electrical energy. During sudden showers beneath looming thunderclouds, one can observe Electabuzz scaling tall trees, where the Pokémon will then wait for lightning to strike.'),
(126, NULL, 'Magmar', '126.png', 'Spitfire Pokémon', 10, NULL, 67, NULL, 290, 'Legend has it that this Pokémon was born from the crater of a volcano. When wounded, it bathes in lava to heal its body, much as one would soak in a hot spring.'),
(127, NULL, 'Pinsir', '127.png', 'Stag Beetle Pokémon', 7, NULL, 102, 144, 147, 'It grips prey with its pincers until the prey is torn apart. What it can''t tear, it tosses far away.'),
(128, NULL, 'Tauros', '128.png', 'Wild Bull Pokémon', 1, NULL, 114, 6, 220, 'When it targets an enemy, it charges furiously while whipping its body with its long tails.'),
(128, 4, 'Tauros', '128-paldea.png', 'Wild Bull Pokémon', 2, NULL, 114, 6, 39, 'This kind of Tauros, known as the Combat Breed, is distinguished by its thick, powerful muscles and its fierce disposition.'),
(129, NULL, 'Magikarp', '129.png', 'Fish Pokémon', 11, NULL, 258, NULL, 193, 'An underpowered, pathetic Pokémon. It may jump high on rare occasions but never more than seven feet.'),
(130, NULL, 'Gyarados', '130.png', 'Atrocious Pokémon', 11, 3, 114, NULL, 147, 'Once it appears, it goes on a rampage. It remains enraged until it demolishes everything around it.'),
(131, NULL, 'Lapras', '131.png', 'Transport Pokémon', 11, 15, 293, 221, 101, 'It loves crossing the sea with people and Pokémon on its back. It understands human speech.'),
(132, NULL, 'Ditto', '132.png', 'Transform Pokémon', 1, NULL, 126, NULL, 109, 'It can freely recombine its own cellular structure to transform into other life-forms.'),
(133, NULL, 'Eevee', '133.png', 'Evolution Pokémon', 1, NULL, 204, 1, 8, 'Its ability to evolve into many forms allows it to adapt smoothly and perfectly to any environment.'),
(134, NULL, 'Vaporeon', '134.png', 'Bubble Jet Pokémon', 11, NULL, 293, NULL, 101, 'Its cell composition is similar to water molecules. As a result, it can''t be seen when it melts away into water.'),
(135, NULL, 'Jolteon', '135.png', 'Lightning Pokémon', 13, NULL, 291, NULL, 191, 'If agitated, it uses electricity to straighten out its fur and launch it in small bunches.'),
(136, NULL, 'Flareon', '136.png', 'Flame Pokémon', 10, NULL, 69, NULL, 90, 'Inhaled air is carried to its flame sac, heated, and exhaled as fire that reaches over 3,000 degrees Fahrenheit.'),
(137, NULL, 'Porygon', '137.png', 'Virtual Pokémon', 1, NULL, 279, 53, 5, 'The world''s first artificially created Pokémon. It can travel through electronic space.'),
(138, NULL, 'Omanyte', '138.png', 'Spiral Pokémon', 6, 11, 258, 221, 297, 'It''s a Pokémon that was resurrected from a fossil using modern science. It swam in ancient seas.'),
(139, NULL, 'Omastar', '139.png', 'Spiral Pokémon', 6, 11, 258, 221, 297, 'It is thought that this Pokémon became extinct because its spiral shell grew too large.'),
(140, NULL, 'Kabuto', '140.png', 'Shellfish Pokémon', 6, 11, 258, 17, 297, 'It is thought to have inhabited beaches 300 million years ago. It is protected by a sturdy shell.'),
(141, NULL, 'Kabutops', '141.png', 'Shellfish Pokémon', 6, 11, 258, 17, 297, 'It is thought that this Pokémon came onto land because its prey adapted to life on land.'),
(142, NULL, 'Aerodactyl', '142.png', 'Fossil Pokémon', 6, 3, 201, 178, 286, 'It''s a Pokémon that roamed the skies in the dinosaur era. Its teeth are like saw blades.'),
(143, NULL, 'Snorlax', '143.png', 'Sleeping Pokémon', 1, NULL, 108, 272, 81, 'This glutton appears in villages without warning and devours the entirety of their rice granaries—such occurrences have long been counted among the gravest of disasters.'),
(144, NULL, 'Articuno', '144.png', 'Freeze Pokémon', 15, 3, 178, NULL, 229, 'This legendary bird Pokémon can create blizzards by freezing moisture in the air.'),
(144, 2, 'Articuno', '144-galar.png', 'Cruel Pokémon', 14, 3, 33, NULL, NULL, 'Known as Articuno, this Pokémon fires beams that can immobilize opponents as if they had been frozen solid.'),
(145, NULL, 'Zapdos', '145.png', 'Electric Pokémon', 13, 3, 178, NULL, 241, 'This legendary Pokémon is said to live in thunderclouds. It freely controls lightning bolts.'),
(145, 2, 'Zapdos', '145-galar.png', 'Strong Legs Pokémon', 2, 3, 49, NULL, NULL, 'One kick from its powerful legs will pulverize a dump truck. Supposedly, this Pokémon runs through the mountains at over 180 mph.'),
(146, NULL, 'Moltres', '146.png', 'Flame Pokémon', 10, 3, 178, NULL, 67, 'It is one of the legendary bird Pokémon. Its appearance is said to indicate the coming of spring.'),
(146, 2, 'Moltres', '146-galar.png', 'Malevolent Pokémon', 17, 3, 21, NULL, NULL, 'This Pokémon''s sinister, flame-like aura will consume the spirit of any creature it hits. Victims become burned-out shadows of themselves.'),
(147, NULL, 'Dratini', '147.png', 'Dragon Pokémon', 16, NULL, 219, NULL, 136, 'It is born large to start with. It repeatedly sheds its skin as it steadily grows longer.'),
(148, NULL, 'Dragonair', '148.png', 'Dragon Pokémon', 16, NULL, 219, NULL, 136, 'It is called the divine Pokémon. When its entire body brightens slightly, the weather changes.'),
(149, NULL, 'Dragonite', '149.png', 'Dragon Pokémon', 16, 3, 112, NULL, 148, 'It can fly in spite of its big and bulky physique. It circles the globe in just 16 hours.'),
(150, NULL, 'Mewtwo', '150.png', 'Genetic Pokémon', 14, NULL, 178, NULL, 286, 'Mewtwo was created by recombining Mew''s genes. It''s said to have the most savage heart among Pokémon.'),
(151, NULL, 'Mew', '151.png', 'New Species Pokémon', 14, NULL, 261, NULL, NULL, 'Because it can use all kinds of moves, many scientists believe Mew to be the ancestor of Pokémon.'),
(152, NULL, 'Chikorita', '152.png', 'Leaf Pokémon', 12, NULL, 161, NULL, 121, 'It uses the leaf on its head to determine the air''s temperature and humidity. It loves to sunbathe.'),
(153, NULL, 'Bayleef', '153.png', 'Leaf Pokémon', 12, NULL, 161, NULL, 121, 'The buds that ring its neck give off a spicy aroma that perks people up.'),
(154, NULL, 'Meganium', '154.png', 'Herb Pokémon', 12, NULL, 161, NULL, 121, 'Its breath has the fantastic ability to revive dead plants and flowers.'),
(155, NULL, 'Cyndaquil', '155.png', 'Fire Mouse Pokémon', 10, NULL, 23, NULL, 69, 'It has a timid nature. If it is startled, the flames on its back burn more vigorously.'),
(156, NULL, 'Quilava', '156.png', 'Volcano Pokémon', 10, NULL, 23, NULL, 69, 'It intimidates foes with the heat of its flames. The fire burns stronger as it prepares to fight.'),
(157, NULL, 'Typhlosion', '157.png', 'Volcano Pokémon', 10, NULL, 23, NULL, 69, 'It attacks using blasts of fire. It creates heat shimmers with intense fire to hide itself.'),
(157, 3, 'Typhlosion', '157-hisui.png', 'Ghost Flame Pokémon', 10, 8, 23, NULL, 76, 'Said to purify lost, forsaken souls with its flames and guide them to the afterlife. I believe its form has been influenced by the energy of the sacred mountain towering at Hisui''s center.'),
(158, NULL, 'Totodile', '158.png', 'Big Jaw Pokémon', 11, NULL, 274, NULL, 220, 'It has a habit of biting everything with its well-developed jaws. Even its Trainer needs to be careful.'),
(159, NULL, 'Croconaw', '159.png', 'Big Jaw Pokémon', 11, NULL, 274, NULL, 220, 'Once it bites down, it won''t let go until it loses its fangs. New fangs quickly grow into place.'),
(160, NULL, 'Feraligatr', '160.png', 'Big Jaw Pokémon', 11, NULL, 274, NULL, 220, 'It usually moves slowly, but it goes at blinding speed when it attacks and bites prey.'),
(161, NULL, 'Sentret', '161.png', 'Scout Pokémon', 1, NULL, 204, 119, 76, 'It has a very nervous nature. It stands up high on its tail so it can scan wide areas.'),
(162, NULL, 'Furret', '162.png', 'Long Body Pokémon', 1, NULL, 204, 119, 76, 'The mother puts its offspring to sleep by curling up around them. It corners foes with speed.'),
(163, NULL, 'Hoothoot', '163.png', 'Owl Pokémon', 1, 3, 113, 119, 273, 'It switches its standing foot so quickly that the switch can''t be seen. It cries at the same time every day.'),
(164, NULL, 'Noctowl', '164.png', 'Owl Pokémon', 1, 3, 113, 119, 273, 'If it flips its head upside down, it''s a sign that it is engaged in very complex thinking.'),
(165, NULL, 'Ledyba', '165.png', 'Five Star Pokémon', 7, 3, 256, 58, 193, 'It''s so timid that it can''t move unless it''s with a swarm. It conveys its feelings through scent.'),
(166, NULL, 'Ledian', '166.png', 'Five Star Pokémon', 7, 3, 256, 58, 117, 'It uses starlight as energy. When more stars appear at night, the patterns on its back grow larger.'),
(167, NULL, 'Spinarak', '167.png', 'String Spit Pokémon', 7, 4, 256, 113, 228, 'It sets a trap by spinning a web with thin but strong thread. It waits motionlessly for prey to arrive.'),
(168, NULL, 'Ariados', '168.png', 'Long Leg Pokémon', 7, 4, 256, 113, 228, 'It attaches silk to its prey and sets it free. Later, it tracks the silk to the prey and its friends.'),
(169, NULL, 'Crobat', '169.png', 'Bat Pokémon', 4, 3, 112, NULL, 110, 'Its hind limbs have become another set of wings. Crobat expertly maneuvers its four wings to dart in exquisite fashion through even the most confined caves without losing any speed.'),
(170, NULL, 'Chinchou', '170.png', 'Angler Pokémon', 11, 13, 291, 106, 293, 'It discharges positive and negative electricity from the tips of its antennae to shock its foes.'),
(171, NULL, 'Lanturn', '171.png', 'Light Pokémon', 11, 13, 291, 106, 293, 'Lanturn''s light can shine up from great depths. It is nicknamed the Deep-Sea Star.'),
(172, NULL, 'Pichu', '172.png', 'Tiny Mouse Pokémon', 13, NULL, 241, NULL, 125, 'Despite this Pokémon''s cute appearance, those who want to live with one should prepare to be on the receiving end of its electric jolts.'),
(173, NULL, 'Cleffa', '173.png', 'Star Shape Pokémon', 18, NULL, 42, 132, 75, 'In silhouette, they resemble twinkling starlight. When shooting stars rain from the night sky, Cleffa gather in numbers and dance as though they are indeed incarnations of the stars.'),
(174, NULL, 'Igglybuff', '174.png', 'Balloon Pokémon', 1, 18, 42, 33, 75, 'It likes to sing but is not yet good at it. With praise and encouragement, it will get better little by little.'),
(175, NULL, 'Togepi', '175.png', 'Spike Ball Pokémon', 18, NULL, 100, 215, 252, 'This ovate creature is frequently mistaken for a moving egg when encountered out in the fields or in the mountains. Its guileless smile soothes the soul.'),
(176, NULL, 'Togetic', '176.png', 'Happiness Pokémon', 18, 3, 100, 215, 252, 'No records exist of Togetic being seen in the wilds. Rumors abound that it evolves under the loving care of a trusted human companion, upon whom the Pokémon then bestows great joy.'),
(177, NULL, 'Natu', '177.png', 'Tiny Bird Pokémon', 14, 3, 261, 58, 131, 'It picks food from cactus plants, deftly avoiding buds and spines. It seems to skip about to move.'),
(178, NULL, 'Xatu', '178.png', 'Mystic Pokémon', 14, 3, 261, 58, 131, 'This odd Pokémon can see both the past and the future. It eyes the sun''s movement all day.'),
(179, NULL, 'Mareep', '179.png', 'Wool Pokémon', 13, NULL, 241, NULL, 169, 'If static electricity builds in its body, its fleece doubles in volume. Touching it will shock you.'),
(180, NULL, 'Flaaffy', '180.png', 'Wool Pokémon', 13, NULL, 241, NULL, 169, 'As a result of storing too much electricity, it developed patches where even downy wool won''t grow.'),
(181, NULL, 'Ampharos', '181.png', 'Light Pokémon', 13, NULL, 241, NULL, 169, 'When it gets dark, the light from its bright, shiny tail can be seen from far away on the ocean''s surface.'),
(182, NULL, 'Bellossom', '182.png', 'Flower Pokémon', 12, NULL, 27, NULL, 93, 'When the heavy rainfall season ends, it is drawn out by warm sunlight to dance in the open.'),
(183, NULL, 'Marill', '183.png', 'Aqua Mouse Pokémon', 11, 18, 272, 98, 210, 'The fur on its body naturally repels water. It can stay dry even when it plays in the water.'),
(184, NULL, 'Azumarill', '184.png', 'Aqua Rabbit Pokémon', 11, 18, 272, 98, 210, 'Its long ears are superb sensors. It can distinguish the movements of things in water and tell what they are.'),
(185, NULL, 'Sudowoodo', '185.png', 'Imitation Pokémon', 6, NULL, 250, 201, 193, 'To avoid being attacked, it does nothing but mimic a tree. It hates water and flees from rain.'),
(186, NULL, 'Politoed', '186.png', 'Frog Pokémon', 11, NULL, 293, 43, 55, 'A group of Poliwag and Poliwhirl will form with a Politoed as the leader. Politoed''s cries make the Pokémon of the group obey.'),
(187, NULL, 'Hoppip', '187.png', 'Cottonweed Pokémon', 12, 3, 27, 121, 110, 'Outside of cold regions, Hoppip can be found practically everywhere. This is because the wind carries this species all over the world.'),
(188, NULL, 'Skiploom', '188.png', 'Cottonweed Pokémon', 12, 3, 27, 121, 110, 'When the weather grows cold, Skiploom''s flower closes and the Pokémon cannot photosynthesize, so it flies away to warmer regions.'),
(189, NULL, 'Jumpluff', '189.png', 'Cottonweed Pokémon', 12, 3, 27, 121, 110, 'Beware its cotton spores. If you accidentally breathe them in, you''ll be racked with coughs and itchiness.'),
(190, NULL, 'Aipom', '190.png', 'Long Tail Pokémon', 1, NULL, 204, 167, 225, 'This treetop dweller possesses a tail as dexterous as a hand. Ancient writings describe this Pokémon as a one-armed oddity.'),
(191, NULL, 'Sunkern', '191.png', 'Seed Pokémon', 12, NULL, 27, 231, 58, 'It is very weak. Its only means of defense is to shake its leaves desperately at its attacker.'),
(192, NULL, 'Sunflora', '192.png', 'Sun Pokémon', 12, NULL, 27, 231, 58, 'Since it converts sunlight into energy, it is always looking in the direction of the sun.'),
(193, NULL, 'Yanma', '193.png', 'Clear Wing Pokémon', 7, 3, 235, 34, 76, 'Its frail wings are so thin that one can see clear through them. However, during flight these wings exhibit the power to churn air with force enough to launch a house skyward.'),
(194, NULL, 'Wooper', '194.png', 'Water Fish Pokémon', 11, 5, 43, 293, 284, 'When the temperature cools in the evening, they emerge from water to seek food along the shore.'),
(194, 4, 'Wooper', '194-paldea.png', 'Poison Fish Pokémon', 4, 5, 171, 293, 284, 'After losing a territorial struggle, Wooper began living on land. The Pokémon changed over time, developing a poisonous film to protect its body.'),
(195, NULL, 'Quagsire', '195.png', 'Water Fish Pokémon', 11, 5, 43, 293, 284, 'A dim-witted Pokémon. It doesn''t care if it bumps its head into boats or rocks while swimming.'),
(196, NULL, 'Espeon', '196.png', 'Sun Pokémon', 14, NULL, 261, NULL, 131, 'The tip of its forked tail quivers when it is predicting its opponent''s next move.'),
(197, NULL, 'Umbreon', '197.png', 'Moon Pokémon', 17, NULL, 261, NULL, 112, 'When exposed to the moon''s aura, the rings on its body glow faintly and it gains a mysterious power.'),
(198, NULL, 'Murkrow', '198.png', 'Darkness Pokémon', 17, 3, 113, 252, 177, 'If spotted, it will lure an unwary person into chasing it, then lose the pursuer on mountain trails.'),
(199, NULL, 'Slowking', '199.png', 'Royal Pokémon', 11, 14, 157, 162, 197, 'Being bitten by Shellder gave it intelligence comparable to that of internationally recognized scientists.'),
(199, 2, 'Slowking', '199-galar.png', 'Hexpert Pokémon', 4, 14, 40, 162, 197, 'A combination of toxins and the shock of evolving has increased Shellder''s intelligence to the point that Shellder now controls Slowking.'),
(200, NULL, 'Misdreavus', '200.png', 'Screech Pokémon', 8, NULL, 122, NULL, NULL, 'It loves to bite and yank people''s hair from behind without warning, just to see their shocked reactions.'),
(201, NULL, 'Unown', '201.png', 'Symbol Pokémon', 14, NULL, 122, NULL, NULL, 'Because the Pokémon is shaped like ancient writing, it is a huge mystery whether written language or Unown came first.'),
(202, NULL, 'Wobbuffet', '202.png', 'Patient Pokémon', 14, NULL, 217, NULL, 266, 'It desperately tries to keep its black tail hidden. This behavior is said to be proof that its tail hides a secret.'),
(203, NULL, 'Girafarig', '203.png', 'Long Neck Pokémon', 1, 14, 112, 58, 210, 'Girafarig''s tail has a small head. It instinctively bites at any foe that approaches the Pokémon from behind.'),
(204, NULL, 'Pineco', '204.png', 'Bagworm Pokémon', 7, NULL, 250, NULL, 160, 'It spits out a fluid that it uses to glue tree bark to its body. The fluid hardens when it touches air.'),
(205, NULL, 'Forretress', '205.png', 'Bagworm Pokémon', 7, 9, 250, NULL, 160, 'Its entire body is shielded by a steel-hard shell. What lurks inside this shell is a total mystery.'),
(206, NULL, 'Dunsparce', '206.png', 'Land Snake Pokémon', 1, NULL, 215, 204, 193, 'If spotted, it escapes by burrowing with its tail. It can float just slightly using its wings.'),
(207, NULL, 'Gligar', '207.png', 'Fly Scorpion Pokémon', 5, 3, 102, 209, 108, 'Its tail is tipped by a thick, horrible stinger. To bring down prey, it will first obscure their vision by covering their faces with its body, and then it will use the stinger to inject them with venom.'),
(208, NULL, 'Steelix', '208.png', 'Iron Snake Pokémon', 9, 5, 201, 250, 220, 'This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.'),
(209, NULL, 'Snubbull', '209.png', 'Fairy Pokémon', 18, NULL, 114, 204, 193, 'Small Pokémon flee from its scary face. It is, however, considered by many people to be cute.'),
(210, NULL, 'Granbull', '210.png', 'Fairy Pokémon', 18, NULL, 114, 191, 193, 'It is timid in spite of its looks. If it becomes enraged, however, it will strike with its huge fangs.'),
(211, NULL, 'Qwilfish', '211.png', 'Balloon Pokémon', 11, 4, 171, 258, 114, 'Be cautious if this Pokémon starts sucking in water—it will soon attack by scattering the toxic spikes that grow all over its body.'),
(211, 3, 'Qwilfish', '211-hisui.png', 'Balloon Pokémon', 17, 4, 171, 258, 114, 'Fishers detest this troublesome Pokémon because it sprays poison from its spines, getting it everywhere. A different form of Qwilfish lives in other regions.'),
(212, NULL, 'Scizor', '212.png', 'Pincer Pokémon', 7, 9, 256, 265, 124, 'This Pokémon''s pincers, which contain steel, can crush any hard object they get ahold of into bits.'),
(213, NULL, 'Shuckle', '213.png', 'Mold Pokémon', 7, 6, 250, 81, 35, 'It stores berries in its shell. The berries mix with its body fluids to become delicious juices.'),
(214, NULL, 'Heracross', '214.png', 'Single Horn Pokémon', 7, 2, 256, 90, 147, 'With its herculean powers, it can easily throw around an object that is 100 times its own weight.'),
(215, NULL, 'Sneasel', '215.png', 'Sharp Claw Pokémon', 17, 15, 112, 119, 166, 'This is a smart and sneaky Pokémon. A pair may work together to steal eggs by having one lure the parents away.'),
(215, 3, 'Sneasel', '215-hisui.png', 'Sharp Claw Pokémon', 2, 4, 112, 119, 166, 'Its sturdy, curved claws are ideal for traversing precipitous cliffs. From the tips of these claws drips a venom that infiltrates the nerves of any prey caught in Sneasel''s grasp.'),
(216, NULL, 'Teddiursa', '216.png', 'Little Bear Pokémon', 1, NULL, 167, 191, 96, 'Its paws are soaked in oodles of honey. When nervous, Teddiursa will lick its paws and soon have a smile back on its face.'),
(217, NULL, 'Ursaring', '217.png', 'Hibernator Pokémon', 1, NULL, 90, 191, 286, 'It usually wears a hardened expression, but when it''s licking up honey—which it loves—the joy it feels will cause it to break into a wide grin.'),
(218, NULL, 'Slugma', '218.png', 'Lava Pokémon', 10, NULL, 134, 67, 297, 'Its body is made of magma. If it doesn''t keep moving, its body will cool and harden.'),
(219, NULL, 'Magcargo', '219.png', 'Lava Pokémon', 10, 6, 134, 67, 297, 'Its body temperature is roughly 18,000 degrees Fahrenheit. Flames burst from gaps in its shell made of hardened magma.'),
(220, NULL, 'Swinub', '220.png', 'Pig Pokémon', 15, 5, 157, 229, 272, 'It loves eating mushrooms that grow under dead grass. It also finds hot springs while foraging.'),
(221, NULL, 'Piloswine', '221.png', 'Swine Pokémon', 15, 5, 157, 229, 272, 'The long fur of this Pokémon covers its eyes, ears, and even limbs, allowing Piloswine to resist harshly frigid conditions. The Pokémon''s white tusks can be used to defeat its enemies.'),
(222, NULL, 'Corsola', '222.png', 'Coral Pokémon', 11, 6, 100, 152, 197, 'Many live in the clean seas of the south. They apparently can''t live in polluted waters.'),
(222, 2, 'Corsola', '222-galar.png', 'Coral Pokémon', 8, NULL, 297, NULL, 41, 'Watch your step when wandering areas oceans once covered. What looks like a stone could be this Pokémon, and it will curse you if you kick it.'),
(223, NULL, 'Remoraid', '223.png', 'Jet Pokémon', 11, NULL, 100, 228, 145, 'Spits water from its mouth with incredible accuracy. It captures Burmy by shooting them down off the branches from which they dangle.'),
(224, NULL, 'Octillery', '224.png', 'Jet Pokémon', 11, NULL, 251, 228, 145, 'While Octillery still shoots water from its mouth, the drastic anatomical difference between it and Remoraid meant that for a long time, no one believed the former evolved from the latter.'),
(225, NULL, 'Delibird', '225.png', 'Delivery Pokémon', 15, 3, 290, 100, 113, 'It always carries its food with it, wherever it goes. If attacked, it throws its food at the opponent.'),
(226, NULL, 'Mantine', '226.png', 'Kite Pokémon', 11, 3, 258, 293, 296, 'This calm and gentle Pokémon swims gracefully through the sea. After building speed, it can leap out of the water. It is often misidentified as a bird Pokémon due to this behavior.'),
(227, NULL, 'Skarmory', '227.png', 'Armor Bird Pokémon', 9, 3, 119, 250, 297, 'Skarmory is clad entirely in ironhard armor. It flies at speeds over 180 mph.'),
(228, NULL, 'Houndour', '228.png', 'Dark Pokémon', 17, 10, 58, 69, 286, 'It uses different kinds of cries for communicating with others of its kind and for pursuing its prey.'),
(229, NULL, 'Houndoom', '229.png', 'Dark Pokémon', 17, 10, 58, 69, 286, 'If you are burned by the flames it shoots from its mouth, the pain will never go away.'),
(230, NULL, 'Kingdra', '230.png', 'Dragon Pokémon', 11, 16, 258, 228, 43, 'It lives in caves on the seafloor and creates giant whirlpools every time it moves.'),
(231, NULL, 'Phanpy', '231.png', 'Long Nose Pokémon', 5, NULL, 167, NULL, 209, 'It is far stronger than it appears. If a Phanpy is swinging its trunk around and your arm gets hit by it, your arm bone will shatter.'),
(232, NULL, 'Donphan', '232.png', 'Armor Pokémon', 5, NULL, 250, NULL, 209, 'Donphan is normally a calm Pokémon, but once it is enraged, it will curl its body into a ball and charge at you while rolling.'),
(233, NULL, 'Porygon2', '233.png', 'Virtual Pokémon', 1, NULL, 279, 53, 5, 'After artificial intelligence was implemented in Porygon2, the Pokémon began using a strange language that only other Porygon2 understand.'),
(234, NULL, 'Stantler', '234.png', 'Big Horn Pokémon', 1, NULL, 114, 76, 210, 'It''s said that this Pokémon used to be stronger long ago when it had many enemies, and that it was even able to evolve under its own power.'),
(235, NULL, 'Smeargle', '235.png', 'Painter Pokémon', 1, NULL, 162, 265, 145, 'It marks its territory by using its tail like a paintbrush. There are more than 5,000 different marks.'),
(236, NULL, 'Tyrogue', '236.png', 'Scuffle Pokémon', 2, NULL, 90, 242, 290, 'It is famous for its eagerness to fight and always nurses injuries from challenging larger foes.'),
(237, NULL, 'Hitmontop', '237.png', 'Handstand Pokémon', 2, NULL, 114, 265, 242, 'It fights while spinning like a top. The centrifugal force boosts its destructive power by a factor of 10.'),
(238, NULL, 'Smoochum', '238.png', 'Kiss Pokémon', 15, 14, 157, 74, 101, 'It tests everything by touching with its lips, which remember what it likes and dislikes.'),
(239, NULL, 'Elekid', '239.png', 'Electric Pokémon', 13, NULL, 241, NULL, 290, 'They generate electricity by spinning their arms. During a thunderstorm, if one hears the lively voices of children out in the wilderness, what one is actually hearing are the voices of Elekid.'),
(240, NULL, 'Magby', '240.png', 'Live Coal Pokémon', 10, NULL, 67, NULL, 290, 'This Pokémon lives in volcanic areas. With each breath, sparks spurt from its mouth and nose. When Magby is in good health, its flames gain a yellow tint.'),
(241, NULL, 'Miltank', '241.png', 'Milk Cow Pokémon', 1, NULL, 272, 212, 210, 'It is said that kids who drink Miltank''s milk grow up to become hearty, healthy adults.'),
(242, NULL, 'Blissey', '242.png', 'Happiness Pokémon', 1, NULL, 152, 215, 93, 'Anyone who takes even one taste of Blissey''s egg becomes unfailingly caring and pleasant to everyone.'),
(243, NULL, 'Raikou', '243.png', 'Thunder Pokémon', 13, NULL, 178, NULL, 112, 'It is said to have fallen with lightning. It can fire thunderbolts from the rain clouds on its back.'),
(244, NULL, 'Entei', '244.png', 'Volcano Pokémon', 10, NULL, 178, NULL, 112, 'It is said that when it roars, a volcano erupts somewhere around the globe.'),
(245, NULL, 'Suicune', '245.png', 'Aurora Pokémon', 11, NULL, 178, NULL, 112, 'It races around the world to purify fouled water. It dashes away with the north wind.'),
(246, NULL, 'Larvitar', '246.png', 'Rock Skin Pokémon', 6, 5, 90, NULL, 209, 'It is born deep underground. It can''t emerge until it has entirely consumed the soil around it.'),
(247, NULL, 'Pupitar', '247.png', 'Hard Shell Pokémon', 6, 5, 219, NULL, NULL, 'Its shell is as hard as bedrock, and it is also very strong. Its thrashing can topple a mountain.'),
(248, NULL, 'Tyranitar', '248.png', 'Armor Pokémon', 6, 17, 208, NULL, 286, 'Extremely strong, it can change the landscape. It is so insolent that it doesn''t care about others.'),
(249, NULL, 'Lugia', '249.png', 'Diving Pokémon', 14, 3, 178, NULL, 148, 'It sleeps in a deep-sea trench. If it flaps its wings, it is said to cause a 40-day storm.'),
(250, NULL, 'Ho-oh', '250.png', 'Rainbow Pokémon', 10, 3, 178, NULL, 197, 'Its feathers are in seven colors. It is said that anyone seeing it is promised eternal happiness.'),
(251, NULL, 'Celebi', '251.png', 'Time Travel Pokémon', 14, 12, 152, NULL, NULL, 'It has the power to travel across time, but it is said to appear only in peaceful times.'),
(252, NULL, 'Treecko', '252.png', 'Wood Gecko Pokémon', 12, NULL, 161, NULL, 285, 'The soles of its feet are covered by countless tiny hooks, enabling it to walk on walls and ceilings.'),
(253, NULL, 'Grovyle', '253.png', 'Wood Gecko Pokémon', 12, NULL, 161, NULL, 285, 'It lives in dense jungles. While closing in on its prey, it leaps from branch to branch.'),
(254, NULL, 'Sceptile', '254.png', 'Forest Pokémon', 12, NULL, 161, NULL, 285, 'The leaves that grow on its arms can slice down thick trees. It is without peer in jungle combat.'),
(255, NULL, 'Torchic', '255.png', 'Chick Pokémon', 10, NULL, 23, NULL, 235, 'A fire burns inside it, so it feels very warm to hug. It launches fireballs of 1,800 degrees Fahrenheit.'),
(256, NULL, 'Combusken', '256.png', 'Young Fowl Pokémon', 10, 2, 23, NULL, 235, 'Its kicking mastery lets it loose 10 kicks per second. It emits sharp cries to intimidate foes.'),
(257, NULL, 'Blaziken', '257.png', 'Blaze Pokémon', 10, 2, 23, NULL, 235, 'Flames spout from its wrists, enveloping its knuckles. Its punches scorch its foes.'),
(258, NULL, 'Mudkip', '258.png', 'Mud Fish Pokémon', 11, NULL, 274, NULL, 43, 'Using the fin on its head, Mudkip senses the flow of water to keep track of what''s going on around it. Mudkip has the strength to heft boulders.'),
(259, NULL, 'Marshtomp', '259.png', 'Mud Fish Pokémon', 11, 5, 274, NULL, 43, 'Its sturdy legs give it sure footing, even in mud. It burrows into dirt to sleep.'),
(260, NULL, 'Swampert', '260.png', 'Mud Fish Pokémon', 11, 5, 274, NULL, 43, 'It can swim while towing a large ship. It bashes down foes with a swing of its thick arms.'),
(261, NULL, 'Poochyena', '261.png', 'Bite Pokémon', 17, NULL, 204, 191, 193, 'A Pokémon with a persistent nature, it chases its chosen prey until the prey becomes exhausted.'),
(262, NULL, 'Mightyena', '262.png', 'Bite Pokémon', 17, NULL, 114, 191, 147, 'It chases down prey in a pack. It will never disobey the commands of a skilled Trainer.'),
(263, NULL, 'Zigzagoon', '263.png', 'Tiny Raccoon Pokémon', 1, NULL, 167, 81, 191, 'It walks in zigzag fashion. It''s good at finding items in the grass and even in the ground.'),
(263, 2, 'Zigzagoon', '263-galar.png', 'Tiny Raccoon Pokémon', 17, 1, 167, 81, 191, 'Thought to be the oldest form of Zigzagoon, it moves in zigzags and wreaks havoc upon its surroundings.'),
(264, NULL, 'Linoone', '264.png', 'Rushing Pokémon', 1, NULL, 167, 81, 191, 'It charges prey at speeds over 60 mph. However, because it can only run straight, it often fails.'),
(264, 2, 'Linoone', '264-galar.png', 'Rushing Pokémon', 17, 1, 167, 81, 191, 'It uses its long tongue to taunt opponents. Once the opposition is enraged, this Pokémon hurls itself at the opponent, tackling them forcefully.'),
(265, NULL, 'Wurmple', '265.png', 'Worm Pokémon', 7, NULL, 222, NULL, 204, 'Likes sap and is abundant in the wild. Why it evolves into various different forms is unknown. One cannot tell from a Wurmple''s appearance which form it will take when it evolves.'),
(266, NULL, 'Silcoon', '266.png', 'Cocoon Pokémon', 7, NULL, 219, NULL, NULL, 'Wraps itself in thin strings of silk while it stores energy for evolution. It can''t extend its limbs and its movement is slow, but its eyes keep a sharp lookout—Silcoon is always on guard.'),
(267, NULL, 'Beautifly', '267.png', 'Butterfly Pokémon', 7, 3, 256, NULL, 199, 'A colorful and incredibly beautiful but also greedy Pokémon. In an effort to keep its favorite food all to itself, it will chase away Combee as they try to gather nectar.'),
(268, NULL, 'Cascoon', '268.png', 'Cocoon Pokémon', 7, NULL, 219, NULL, NULL, 'The silk coating its body is thin but sufficiently strong. Cascoon''s silk has a luster and texture superior to that of Silcoon''s, and clothes made using Cascoon silk are regarded as top-notch.'),
(269, NULL, 'Dustox', '269.png', 'Poison Moth Pokémon', 7, 4, 222, NULL, 34, 'It violently flutters its wings to scatter toxic dust when attacked. It becomes active after sunset.'),
(270, NULL, 'Lotad', '270.png', 'Water Weed Pokémon', 11, 12, 258, 192, 162, 'It looks like an aquatic plant and serves as a ferry for Pokémon that can''t swim.'),
(271, NULL, 'Lombre', '271.png', 'Jolly Pokémon', 11, 12, 258, 192, 162, 'It has a mischievous spirit. If it spots an angler, it will tug on the fishing line to interfere.'),
(272, NULL, 'Ludicolo', '272.png', 'Carefree Pokémon', 11, 12, 258, 192, 162, 'If it hears festive music, all its muscles fill with energy. It can''t help breaking out into a dance.'),
(273, NULL, 'Seedot', '273.png', 'Acorn Pokémon', 12, NULL, 27, 58, 166, 'When it dangles from a tree branch, it looks just like an acorn. It enjoys scaring other Pokémon that try to peck at it.'),
(274, NULL, 'Nuzleaf', '274.png', 'Wily Pokémon', 12, 17, 27, 58, 166, 'The sound of its grass flute makes its listeners uneasy. It lives deep in the forest.'),
(275, NULL, 'Shiftry', '275.png', 'Wicked Pokémon', 12, 17, 27, 58, 166, 'By flapping its leafy fans, it can whip up gusts of 100 feet per second that can level houses.'),
(276, NULL, 'Taillow', '276.png', 'Tiny Swallow Pokémon', 1, 3, 90, NULL, 212, 'It has a gutsy spirit that makes it bravely take on tough foes. It flies in search of warm climates.'),
(277, NULL, 'Swellow', '277.png', 'Swallow Pokémon', 1, 3, 90, NULL, 212, 'It circles the sky in search of prey and dives sharply to catch its target.'),
(278, NULL, 'Wingull', '278.png', 'Seagull Pokémon', 11, 3, 119, 101, 192, 'It soars high in the sky, riding on updrafts like a glider. It carries food tucked in its bill.'),
(279, NULL, 'Pelipper', '279.png', 'Water Bird Pokémon', 11, 3, 119, 55, 192, 'It protects its young in its beak. It bobs on waves, resting on them on days when the waters are calm.'),
(280, NULL, 'Ralts', '280.png', 'Feeling Pokémon', 14, 18, 261, 279, 266, 'The horns on its head provide a strong power that enables it to sense people''s emotions.'),
(281, NULL, 'Kirlia', '281.png', 'Emotion Pokémon', 14, 18, 261, 279, 266, 'It has a psychic power that enables it to distort the space around it and see into the future.'),
(282, NULL, 'Gardevoir', '282.png', 'Embrace Pokémon', 14, 18, 261, 279, 266, 'To protect its Trainer, it will expend all its psychic power to create a small black hole.'),
(283, NULL, 'Surskit', '283.png', 'Pond Skater Pokémon', 7, 11, 258, NULL, 192, 'It secretes a thick, sweet-scented syrup from the tip of its head. It lives on weed-choked ponds.'),
(284, NULL, 'Masquerain', '284.png', 'Eyeball Pokémon', 7, 3, 114, NULL, 286, 'The antennae have distinctive patterns that look like eyes. When it rains, they grow heavy, making flight impossible.'),
(285, NULL, 'Shroomish', '285.png', 'Mushroom Pokémon', 12, NULL, 60, 170, 191, 'If it senses danger, it scatters spores from the top of its head to protect itself.'),
(286, NULL, 'Breloom', '286.png', 'Mushroom Pokémon', 12, 2, 60, 170, 265, 'It scatters poisonous spores and throws powerful punches while its foe is hampered by inhaled spores.'),
(287, NULL, 'Slakoth', '287.png', 'Slacker Pokémon', 1, NULL, 282, NULL, NULL, 'It sleeps for 20 hours every day. Making drowsy those that see it is one of its abilities.'),
(288, NULL, 'Vigoroth', '288.png', 'Wild Monkey Pokémon', 1, NULL, 290, NULL, NULL, 'It is always hungry because it won''t stop rampaging. Even while it is eating, it can''t keep still.'),
(289, NULL, 'Slaking', '289.png', 'Lazy Pokémon', 1, NULL, 282, NULL, NULL, 'It is the world''s most slothful Pokémon. However, it can exert horrifying power by releasing pent-up energy all at once.'),
(290, NULL, 'Nincada', '290.png', 'Trainee Pokémon', 7, 5, 34, NULL, 204, 'It grows underground, sensing its surroundings using antennae instead of its virtually blind eyes.'),
(291, NULL, 'Ninjask', '291.png', 'Ninja Pokémon', 7, 3, 235, NULL, 110, 'Because they move so quickly, they sometimes become unseeable. They congregate around tree sap.'),
(292, NULL, 'Shedinja', '292.png', 'Shed Pokémon', 7, 8, 303, NULL, NULL, 'It is a discarded bug shell that came to life. Peering into the crack on its back is said to steal one''s spirit.'),
(293, NULL, 'Whismur', '293.png', 'Whisper Pokémon', 1, NULL, 234, NULL, 193, 'Usually, its cries are like quiet murmurs. If frightened, it shrieks at the same volume as a jet plane.'),
(294, NULL, 'Loudred', '294.png', 'Big Voice Pokémon', 1, NULL, 234, NULL, 212, 'The shock waves from its cries can tip over trucks. It stamps its feet to power up.'),
(295, NULL, 'Exploud', '295.png', 'Loud Noise Pokémon', 1, NULL, 234, NULL, 212, 'Its howls can be heard over six miles away. It emits all sorts of noises from the ports on its body.'),
(296, NULL, 'Makuhita', '296.png', 'Guts Pokémon', 2, NULL, 272, 90, 220, 'It toughens up by slamming into thick trees over and over. It gains a sturdy body and dauntless spirit.'),
(297, NULL, 'Hariyama', '297.png', 'Arm Thrust Pokémon', 2, NULL, 272, 90, 220, 'It stomps on the ground to build power. It can send a 10-ton truck flying with a straight-arm punch.'),
(298, NULL, 'Azurill', '298.png', 'Polka Dot Pokémon', 1, 18, 272, 98, 210, 'Its tail bounces like a rubber ball. It flings that tail around to fight opponents bigger than itself.'),
(299, NULL, 'Nosepass', '299.png', 'Compass Pokémon', 6, NULL, 250, 135, 205, 'Its nose is a magnet. As a result, this Pokémon always keeps its face pointing north.'),
(300, NULL, 'Skitty', '300.png', 'Kitten Pokémon', 1, NULL, 42, 156, 304, 'It can''t stop itself from chasing moving things, and it runs in circles, chasing its own tail.'),
(301, NULL, 'Delcatty', '301.png', 'Prim Pokémon', 1, NULL, 42, 156, 304, 'It is highly popular among Trainers for its sublime fur. It does not keep a nest.'),
(302, NULL, 'Sableye', '302.png', 'Darkness Pokémon', 17, 8, 119, 237, 177, 'Materials from gems it has eaten float to the surface of its body and can form an infinite number of patterns among individuals.'),
(303, NULL, 'Mawile', '303.png', 'Deceiver Pokémon', 9, 18, 102, 114, 220, 'Attached to its head is a huge set of jaws formed by horns. It can chew through iron beams.'),
(304, NULL, 'Aron', '304.png', 'Iron Armor Pokémon', 9, 6, 250, 201, 95, 'It usually lives deep in mountains. But when it''s hungry, it shows up at the foot of the mountains and eats railroad tracks and cars.'),
(305, NULL, 'Lairon', '305.png', 'Iron Armor Pokémon', 9, 6, 250, 201, 95, 'For food, it digs up iron ore. It smashes its steely body against others to fight over territory.'),
(306, NULL, 'Aggron', '306.png', 'Iron Armor Pokémon', 9, 6, 250, 201, 95, 'While seeking iron for food, it digs tunnels by breaking through bedrock with its steel horns.'),
(307, NULL, 'Meditite', '307.png', 'Meditate Pokémon', 2, 14, 186, NULL, 266, 'It meditates to heighten its inner energy and to float in the air. It eats one berry a day.'),
(308, NULL, 'Medicham', '308.png', 'Meditate Pokémon', 2, 14, 186, NULL, 266, 'Through yoga training, it gained the psychic power to predict its foe''s next move.'),
(309, NULL, 'Electrike', '309.png', 'Lightning Pokémon', 13, NULL, 241, 125, 141, 'Using electricity stored in its fur, it stimulates its muscles to heighten its reaction speed.'),
(310, NULL, 'Manectric', '310.png', 'Discharge Pokémon', 13, NULL, 241, 125, 141, 'It discharges electricity from its mane. The Pokémon creates a thundercloud overhead from which to drop lightning bolts.'),
(311, NULL, 'Plusle', '311.png', 'Cheering Pokémon', 13, NULL, 169, NULL, 125, 'It cheers on friends with pom-poms made of sparks. It drains power from telephone poles.'),
(312, NULL, 'Minun', '312.png', 'Cheering Pokémon', 13, NULL, 141, NULL, 291, 'It cheers on friends. If its friends are losing, its body lets off more and more sparks.'),
(313, NULL, 'Volbeat', '313.png', 'Firefly Pokémon', 7, NULL, 106, 256, 177, 'It communicates with others by lighting up its rear at night. It loves Illumise''s sweet aroma.'),
(314, NULL, 'Illumise', '314.png', 'Firefly Pokémon', 7, NULL, 157, 273, 177, 'With its sweet aroma, it guides Volbeat to draw signs with light in the night sky.'),
(315, NULL, 'Roselia', '315.png', 'Thorn Pokémon', 12, 4, 152, 171, 121, 'The beautiful flowers on its arms have toxic thorns. Don''t even think about picking those flowers.'),
(316, NULL, 'Gulpin', '316.png', 'Stomach Pokémon', 4, NULL, 128, 247, 81, 'It has a small heart and brain. Its stomach comprises most of its body, with enzymes to dissolve anything.'),
(317, NULL, 'Swalot', '317.png', 'Poison Bag Pokémon', 4, NULL, 128, 247, 81, 'It can swallow a tire whole in one gulp. It secretes a horribly toxic fluid from the pores on its body.'),
(318, NULL, 'Carvanha', '318.png', 'Savage Pokémon', 11, 17, 203, NULL, 235, 'They swarm any foe that invades their territory. Their sharp fangs can tear out boat hulls.'),
(319, NULL, 'Sharpedo', '319.png', 'Brutal Pokémon', 11, 17, 203, NULL, 235, 'Its fangs rip through sheet iron. It swims at 75 mph and is known as the Bully of the Sea.'),
(320, NULL, 'Wailmer', '320.png', 'Ball Whale Pokémon', 11, NULL, 296, 157, 178, 'On sunny days, it lands on beaches to bounce like a ball and play. It spouts water from its nostrils.'),
(321, NULL, 'Wailord', '321.png', 'Float Whale Pokémon', 11, NULL, 296, 157, 178, 'It''s the biggest of all Pokémon. It can dive to a depth of almost 10,000 feet on only one breath.'),
(322, NULL, 'Numel', '322.png', 'Numb Pokémon', 10, 5, 157, 224, 162, 'Magma of almost 2,200 degrees Fahrenheit courses through its body. When it grows cold, the magma hardens and slows it.'),
(323, NULL, 'Camerupt', '323.png', 'Eruption Pokémon', 10, 5, 134, 232, 6, 'It lives in the crater of a volcano. It is well known that the humps on its back erupt every 10 years.'),
(324, NULL, 'Torkoal', '324.png', 'Coal Pokémon', 10, NULL, 299, 56, 221, 'Coal is the source of Torkoal''s energy. Large amounts of coal can be found in the mountains where they live.'),
(325, NULL, 'Spoink', '325.png', 'Bounce Pokémon', 14, NULL, 272, 162, 81, 'Using its tail like a spring, it keeps its heart beating by bouncing constantly. If it stops, it dies.'),
(326, NULL, 'Grumpig', '326.png', 'Manipulate Pokémon', 14, NULL, 272, 162, 81, 'It can perform odd dance steps to influence foes. Its style of dancing became hugely popular overseas.'),
(327, NULL, 'Spinda', '327.png', 'Spot Panda Pokémon', 1, NULL, 162, 263, 35, 'No two Spinda have the same pattern of spots. Their tottering steps hinder the aim of foes.'),
(328, NULL, 'Trapinch', '328.png', 'Ant Pit Pokémon', 5, NULL, 102, 9, 220, 'It makes a conical pit in desert sand and lies in wait at the bottom for prey to come tumbling down.'),
(329, NULL, 'Vibrava', '329.png', 'Vibration Pokémon', 5, 16, 122, NULL, NULL, 'It violently shudders its wings, generating ultrasonic waves to induce headaches in people.'),
(330, NULL, 'Flygon', '330.png', 'Mystic Pokémon', 5, 16, 122, NULL, NULL, 'It whips up sandstorms with powerful flaps of its wings. It is known as the Desert Spirit.'),
(331, NULL, 'Cacnea', '331.png', 'Cactus Pokémon', 12, NULL, 209, NULL, 293, 'It prefers harsh environments, such as deserts. It can survive for 30 days on water stored in its body.'),
(332, NULL, 'Cacturne', '332.png', 'Scarecrow Pokémon', 12, 17, 209, NULL, 293, 'It lives in deserts. It becomes active at night when it hunts for prey exhausted from the desert''s heat.'),
(333, NULL, 'Swablu', '333.png', 'Cotton Bird Pokémon', 1, 3, 152, NULL, 29, 'It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.'),
(334, NULL, 'Altaria', '334.png', 'Humming Pokémon', 16, 3, 152, NULL, 29, 'On sunny days, it flies freely through the sky and blends into the clouds. It sings in a beautiful soprano.'),
(335, NULL, 'Zangoose', '335.png', 'Cat Ferret Pokémon', 1, NULL, 108, NULL, 276, 'If it comes across a Seviper, its fur bristles and it assumes its battle pose. Its sharp claws are its best weapon.'),
(336, NULL, 'Seviper', '336.png', 'Fang Snake Pokémon', 4, NULL, 219, NULL, 110, 'Constant polishing makes the edge of the blade on its tail extremely sharp. It''s Zangoose''s archrival.'),
(337, NULL, 'Lunatone', '337.png', 'Meteorite Pokémon', 6, 14, 122, NULL, NULL, 'It becomes active on nights with a full moon, so it is said to have some link to the lunar phases.'),
(338, NULL, 'Solrock', '338.png', 'Meteorite Pokémon', 6, 14, 122, NULL, NULL, 'This new Pokémon species is rumored to be an avatar of the sun. The Pokémon gives off light while spinning.'),
(339, NULL, 'Barboach', '339.png', 'Whiskers Pokémon', 11, 5, 157, 8, 101, 'It probes muddy riverbeds with its two long whiskers. A slimy film protects its body.'),
(340, NULL, 'Whiscash', '340.png', 'Whiskers Pokémon', 11, 5, 157, 8, 101, 'Sighting Whiscash leaping from the water is believed to herald an earthquake.'),
(341, NULL, 'Corphish', '341.png', 'Ruffian Pokémon', 11, NULL, 102, 221, 1, 'Its hardy vitality enables it to adapt to any environment. Its pincers will never release prey.'),
(342, NULL, 'Crawdaunt', '342.png', 'Rogue Pokémon', 11, 17, 102, 221, 1, 'It is a ruffian that uses its pincers to pick up and toss out other Pokémon from its pond.'),
(343, NULL, 'Baltoy', '343.png', 'Clay Doll Pokémon', 5, 14, 122, NULL, NULL, 'It moves by spinning on its foot. It is a rare Pokémon that was discovered in ancient ruins.'),
(344, NULL, 'Claydol', '344.png', 'Clay Doll Pokémon', 5, 14, 122, NULL, NULL, 'An ancient clay figurine was exposed to a mysterious ray of light, and it came to life as a Pokémon.'),
(345, NULL, 'Lileep', '345.png', 'Sea Lily Pokémon', 6, 12, 251, NULL, 248, 'It lived on the seafloor 100 million years ago and was reanimated scientifically.'),
(346, NULL, 'Cradily', '346.png', 'Barnacle Pokémon', 6, 12, 251, NULL, 248, 'It lives in the shallows of warm seas. When the tide goes out, it digs up prey from beaches.'),
(347, NULL, 'Anorith', '347.png', 'Old Shrimp Pokémon', 6, 7, 17, NULL, 258, 'This Pokémon ancestor was reanimated from a fossil. It lived in the sea and hunted with its claws.'),
(348, NULL, 'Armaldo', '348.png', 'Plate Pokémon', 6, 7, 17, NULL, 258, 'It went ashore after evolving. Its entire body is clad in a sturdy armor.'),
(349, NULL, 'Feebas', '349.png', 'Fish Pokémon', 11, NULL, 258, 157, 1, 'They are famous for their shabby appearance. Although populous, they tend to cluster in set locations.'),
(350, NULL, 'Milotic', '350.png', 'Tender Pokémon', 11, NULL, 258, 157, 1, 'It is the world''s most beautiful Pokémon. There are many works of art featuring Milotic.'),
(351, NULL, 'Castform', '351.png', 'Weather Pokémon', 1, NULL, 73, NULL, NULL, 'Its appearance changes with the weather. Recently, its molecules were found to be just like water.'),
(352, NULL, 'Kecleon', '352.png', 'Color Swap Pokémon', 1, NULL, 30, NULL, 182, 'It can freely change its body''s color. The zigzag pattern on its belly doesn''t change, however.'),
(353, NULL, 'Shuppet', '353.png', 'Puppet Pokémon', 8, NULL, 113, 76, 41, 'It feeds on the dark emotions of sadness and hatred, which make it grow steadily stronger.'),
(354, NULL, 'Banette', '354.png', 'Marionette Pokémon', 8, NULL, 113, 76, 41, 'Strong feelings of hatred turned a puppet into a Pokémon. If it opens its mouth, its cursed energy escapes.'),
(355, NULL, 'Duskull', '355.png', 'Requiem Pokémon', 8, NULL, 122, NULL, 76, 'It doggedly pursues its prey wherever the prey goes. However, the chase is abandoned at sunrise.'),
(356, NULL, 'Dusclops', '356.png', 'Beckon Pokémon', 8, NULL, 178, NULL, 76, 'Its body is hollow. It is said that those who look into its body are sucked into the void.'),
(357, NULL, 'Tropius', '357.png', 'Fruit Pokémon', 12, 3, 27, 231, 92, 'Delicious fruits grew out from around its neck because it always ate the same kind of fruit.'),
(358, NULL, 'Chimecho', '358.png', 'Wind Chime Pokémon', 14, NULL, 122, NULL, NULL, 'Can emit waves of air powerful enough to knock out prey taller than itself. I hypothesize that it amplifies the faint sound of wind within its body.'),
(359, NULL, 'Absol', '359.png', 'Disaster Pokémon', 17, NULL, 178, 252, 118, 'It senses coming disasters and appears before people only to warn them of impending danger.'),
(360, NULL, 'Wynaut', '360.png', 'Bright Pokémon', 14, NULL, 217, NULL, 266, 'They grow strong by pushing up against one another en masse. They love eating sweet fruit.'),
(361, NULL, 'Snorunt', '361.png', 'Snow Hat Pokémon', 15, NULL, 112, 103, 145, 'It is said that a home visited by a Snorunt will prosper. It can withstand cold of -150 degrees Fahrenheit.'),
(362, NULL, 'Glalie', '362.png', 'Face Pokémon', 15, NULL, 112, 103, 145, 'Its prey is instantaneously frozen stiff by the cold air it exhales from its huge mouth. While they''re in that frozen state, it gobbles them up.'),
(363, NULL, 'Spheal', '363.png', 'Clap Pokémon', 15, 11, 272, 103, 157, 'During the season when drift ice approaches the shore, Spheal prefers living on the ice—where fewer predators lurk—rather than the land. Its fur retains heat superbly and resists harsh cold.'),
(364, NULL, 'Sealeo', '364.png', 'Ball Roll Pokémon', 15, 11, 272, 103, 157, 'Its white whiskers are very sensitive. Sealeo will balance Spheal on the tip of its nose, checking its scent and its feel to be sure the Spheal is healthy.'),
(365, NULL, 'Walrein', '365.png', 'Ice Break Pokémon', 15, 11, 272, 103, 157, 'It shatters ice with its big tusks. Its thick blubber repels not only the cold but also enemy attacks.'),
(366, NULL, 'Clamperl', '366.png', 'Bivalve Pokémon', 11, NULL, 221, NULL, 193, 'It makes a single pearl during its lifetime. The pearl is said to amplify psychic power.'),
(367, NULL, 'Huntail', '367.png', 'Deep Sea Pokémon', 11, NULL, 258, NULL, 296, 'It lives deep in the sea. With a tail shaped like a small fish, it attracts unsuspecting prey.'),
(368, NULL, 'Gorebyss', '368.png', 'South Sea Pokémon', 11, NULL, 258, NULL, 101, 'It lives at the bottom of the sea. In the springtime, its pink body turns more vivid for some reason.'),
(369, NULL, 'Relicanth', '369.png', 'Longevity Pokémon', 11, 6, 258, 201, 250, 'This rare Pokémon was discovered during a deep-sea exploration. It has not changed in over 100 million years.'),
(370, NULL, 'Luvdisc', '370.png', 'Rendezvous Pokémon', 11, NULL, 258, NULL, 101, 'During the spawning season, countless Luvdisc congregate at coral reefs, turning the waters pink.'),
(371, NULL, 'Bagon', '371.png', 'Rock Head Pokémon', 16, NULL, 201, NULL, 220, 'Its belief that it will be able to fly one day is apparently the influence of information carried in its genes.'),
(372, NULL, 'Shelgon', '372.png', 'Endurance Pokémon', 16, NULL, 201, NULL, 160, 'Its armored body makes all attacks bounce off. The armor is too tough, however, making it heavy and somewhat sluggish.'),
(373, NULL, 'Salamence', '373.png', 'Dragon Pokémon', 16, 3, 114, NULL, 147, 'It flies around on its wings, which have grown in at last. In its happiness, it gushes hot flames, burning up everything it passes over.'),
(374, NULL, 'Beldum', '374.png', 'Iron Ball Pokémon', 9, 14, 28, NULL, 124, 'They converse with one another by using magnetic pulses. In a swarm, they move in perfect unison.'),
(375, NULL, 'Metang', '375.png', 'Iron Claw Pokémon', 9, 14, 28, NULL, 124, 'It is formed by two Beldum joining together. Its steel body won''t be scratched if it collides with a jet.'),
(376, NULL, 'Metagross', '376.png', 'Iron Leg Pokémon', 9, 14, 28, NULL, 124, 'Metang combined to form it. With four brains, it has the intelligence of a supercomputer.'),
(377, NULL, 'Regirock', '377.png', 'Rock Peak Pokémon', 6, NULL, 28, NULL, 250, 'Its entire body is made of rock. If any part chips off in battle, Regirock attaches rocks to repair itself.'),
(378, NULL, 'Regice', '378.png', 'Iceberg Pokémon', 15, NULL, 28, NULL, 103, 'Its body is made of ice from the ice age. It controls frigid air of -328 degrees Fahrenheit.'),
(379, NULL, 'Registeel', '379.png', 'Iron Pokémon', 9, NULL, 28, NULL, 124, 'Tempered by pressure underground over tens of thousands of years, its body cannot be scratched.'),
(380, NULL, 'Latias', '380.png', 'Eon Pokémon', 16, 14, 122, NULL, NULL, 'Its body is covered with a down that can refract light in such a way that it becomes invisible.'),
(381, NULL, 'Latios', '381.png', 'Eon Pokémon', 16, 14, 122, NULL, NULL, 'It is a highly intelligent Pokémon. By folding back its forelegs in flight, it can overtake jet planes.'),
(382, NULL, 'Kyogre', '382.png', 'Sea Basin Pokémon', 11, NULL, 55, NULL, NULL, 'It is said to have widened the seas by causing downpours. It had been asleep in a marine trench.'),
(383, NULL, 'Groudon', '383.png', 'Continent Pokémon', 5, NULL, 56, NULL, NULL, 'It had been asleep in underground magma ever since it fiercely fought Kyogre long ago.'),
(384, NULL, 'Rayquaza', '384.png', 'Sky High Pokémon', 16, 3, 4, NULL, NULL, 'It lives in the ozone layer far above the clouds and cannot be seen from the ground.'),
(385, NULL, 'Jirachi', '385.png', 'Wish Pokémon', 9, 14, 215, NULL, NULL, 'It is said to wake up for just seven days every 1,000 years and use its power to grant any wish.'),
(386, NULL, 'Deoxys', '386.png', 'DNA Pokémon', 14, NULL, 178, NULL, NULL, 'An alien virus that fell to earth on a meteorite underwent a DNA mutation to become this Pokémon.'),
(387, NULL, 'Turtwig', '387.png', 'Tiny Leaf Pokémon', 12, NULL, 161, NULL, 221, 'This Pokémon becomes more energetic the more sunlight there is. The part resembling a shell is similar to silt and is slightly damp and warm to the touch.'),
(388, NULL, 'Grotle', '388.png', 'Grove Pokémon', 12, NULL, 161, NULL, 221, 'Appears where there is clean spring water. The fruit that grows on the shrubs on its shell is sweet, nutritious, and truly delicious.'),
(389, NULL, 'Torterra', '389.png', 'Continent Pokémon', 12, 5, 161, NULL, 221, 'This remarkable, large-bodied Pokémon would serve beautifully as borrowed scenery for a garden, and its strength is peerless. Torterra roams the wilderness in search of clean water.'),
(390, NULL, 'Chimchar', '390.png', 'Chimp Pokémon', 10, NULL, 23, NULL, 117, 'It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps.'),
(391, NULL, 'Monferno', '391.png', 'Playful Pokémon', 10, 2, 23, NULL, 117, 'The deeper the blue on its face, the more powerful it will grow to become. It leaps about every which way and lands powerful blows against its opponents with the flame on its tail.'),
(392, NULL, 'Infernape', '392.png', 'Flame Pokémon', 10, 2, 23, NULL, 117, 'A tall, hardy Pokémon with a dazzling appearance. It shrouds itself in flame and battles as if engaged in dance—truly a sight to behold.'),
(393, NULL, 'Piplup', '393.png', 'Penguin Pokémon', 11, NULL, 274, NULL, 49, 'Prefers cold climes and appears along coasts. It''s an adorable little thing—as cute as any child—but it''s also prideful, unwilling to accept handouts from people.'),
(394, NULL, 'Prinplup', '394.png', 'Penguin Pokémon', 11, NULL, 274, NULL, 49, 'It swims gracefully through the frigid sea and sings with a voice like the roaring tide. It has powerful, sturdy wings and dignity to match.'),
(395, NULL, 'Empoleon', '395.png', 'Emperor Pokémon', 11, 9, 274, NULL, 49, 'It swims as fast as a jet boat. The edges of its wings are sharp and can slice apart drifting ice.'),
(396, NULL, 'Starly', '396.png', 'Starling Pokémon', 1, 3, 119, NULL, 195, 'Because they are weak individually, they form groups. However, they bicker if the group grows too big.'),
(397, NULL, 'Staravia', '397.png', 'Starling Pokémon', 1, 3, 114, NULL, 195, 'Recognizing their own weakness, they always live in a group. When alone, a Staravia cries noisily.'),
(398, NULL, 'Staraptor', '398.png', 'Predator Pokémon', 1, 3, 114, NULL, 195, 'When Staravia evolve into Staraptor, they leave the flock to live alone. They have sturdy wings.'),
(399, NULL, 'Bidoof', '399.png', 'Plump Mouse Pokémon', 1, NULL, 224, 284, 145, 'Bidoof has an unsophisticated face and is rarely flustered by anything. There have been incidents involving Bidoof sauntering into villages and gnawing on the houses without a single care.'),
(400, NULL, 'Bibarel', '400.png', 'Beaver Pokémon', 1, 11, 224, 284, 145, 'Bibarel fur repels water and is also a fantastic material for heat retention. These Pokémon create dams on rivers to live in.'),
(401, NULL, 'Kricketot', '401.png', 'Cricket Pokémon', 7, NULL, 219, NULL, 204, 'Its legs are short. Whenever it stumbles, its stiff antennae clack with a xylophone-like sound.'),
(402, NULL, 'Kricketune', '402.png', 'Cricket Pokémon', 7, NULL, 256, NULL, 265, 'By allowing its cry to resonate in the hollow of its belly, it produces a captivating sound.'),
(403, NULL, 'Shinx', '403.png', 'Flash Pokémon', 13, NULL, 199, 114, 90, 'The extension and contraction of its muscles generates electricity. It glows when in trouble.'),
(404, NULL, 'Luxio', '404.png', 'Spark Pokémon', 13, NULL, 199, 114, 90, 'Strong electricity courses through the tips of its sharp claws. A light scratch causes fainting in foes.'),
(405, NULL, 'Luxray', '405.png', 'Gleam Eyes Pokémon', 13, NULL, 199, 114, 90, 'It can see clearly through walls to track down its prey and seek its lost young.'),
(406, NULL, 'Budew', '406.png', 'Bud Pokémon', 12, 4, 152, 171, 121, 'When the sun''s light strengthens, the bud atop this Pokémon''s head opens. This is a sign to the people that the harsh winter is over, and the season of budding has begun.'),
(407, NULL, 'Roserade', '407.png', 'Bouquet Pokémon', 12, 4, 152, 171, 121, 'Hidden within the bouquet on each hand are thorned whips loaded with virulent poison. Roserade moves gracefully as it corners its prey and mercilessly lashes them with its whips.'),
(408, NULL, 'Cranidos', '408.png', 'Head Butt Pokémon', 6, NULL, 144, NULL, 220, 'An incredibly rare sight. They duel each other by ramming their heads together, and the resulting sound echoes throughout the area like the pealing of a bell.'),
(409, NULL, 'Rampardos', '409.png', 'Head Butt Pokémon', 6, NULL, 144, NULL, 220, 'Very little is known about its biology. Can knock down massive trees by smashing its beautiful, pearl-like crown against them.'),
(410, NULL, 'Shieldon', '410.png', 'Shield Pokémon', 6, 9, 250, NULL, 234, 'Much remains unknown about this Pokémon, as few have ever seen it. However, we know that it is calm and dislikes conflict, and it enjoys polishing its face against trees and rocks.'),
(411, NULL, 'Bastiodon', '411.png', 'Shield Pokémon', 6, 9, 250, NULL, 234, 'Its face is sturdy—as strong as diamond—and this hardness offers a very stable defense. Much about this species is still unknown, such as its natural habitat.'),
(412, NULL, 'Burmy', '412.png', 'Bagworm Pokémon', 7, NULL, 219, NULL, 160, 'If its cloak is even slightly damaged, Burmy will immediately repair it with whatever is close at hand. The Pokémon within the cloak is scrawny and vulnerable to the cold.'),
(413, NULL, 'Wormadam', '413.png', 'Bagworm Pokémon', 7, 12, 8, NULL, 160, 'The cloak—fashioned from plant matter—has merged with the Pokémon and is now part of the body, like fur or skin. I suspect this fusion is an effect of the energy involved in evolution.'),
(414, NULL, 'Mothim', '414.png', 'Moth Pokémon', 7, 3, 256, NULL, 273, 'Scatters steel-colored scales as it flaps its wings. Despite being observed feeding primarily on the nectar of flowers, Mothim is not often seen around flower gardens.'),
(415, NULL, 'Combee', '415.png', 'Tiny Bee Pokémon', 7, 3, 96, NULL, 100, 'The trio is together from birth. It constantly gathers nectar from flowers to please Vespiquen.'),
(416, NULL, 'Vespiquen', '416.png', 'Beehive Pokémon', 7, 3, 178, NULL, 286, 'It houses its colony in cells in its body and releases various pheromones to make those grubs do its bidding.'),
(417, NULL, 'Pachirisu', '417.png', 'EleSquirrel Pokémon', 13, NULL, 204, 167, 291, 'A pair may be seen rubbing their cheek pouches together in an effort to share stored electricity.'),
(418, NULL, 'Buizel', '418.png', 'Sea Weasel Pokémon', 11, NULL, 258, NULL, 296, 'It spins its two tails like a screw to propel itself through water. The tails also slice clinging seaweed.'),
(419, NULL, 'Floatzel', '419.png', 'Sea Weasel Pokémon', 11, NULL, 258, NULL, 296, 'With its flotation sac inflated, it can carry people on its back. It deflates the sac before it dives.'),
(420, NULL, 'Cherubi', '420.png', 'Cherry Pokémon', 12, NULL, 27, NULL, NULL, 'Once the fruit growing alongside the main body is large and plump, Cherubi will use the nutrients within to evolve. The fruit then detaches, becoming nourishment for other creatures.'),
(421, NULL, 'Cherrim', '421.png', 'Blossom Pokémon', 12, NULL, 70, NULL, NULL, 'It is docile as a bud and turns cheerful when it blooms. It folds back into a bud if sunlight wanes.'),
(422, NULL, 'Shellos', '422.png', 'Sea Slug Pokémon', 11, NULL, 247, 248, 205, 'Found in abundance on seashores bordering warm waters. Shellos are unexpectedly friendly and will crawl toward any person they see. Take care not to get coated in mucus!'),
(423, NULL, 'Gastrodon', '423.png', 'Sea Slug Pokémon', 11, 5, 247, 248, 205, 'Eats beach sand for nourishment. Should one Gastrodon encounter another of a different color, a fierce battle will inevitably ensue.'),
(424, NULL, 'Ambipom', '424.png', 'Long Tail Pokémon', 1, NULL, 265, 167, 225, 'To affirm their kinship, members of this species will form a ring by linking their newly doubled tails together. On rare occasions, humans have been accepted into such rings.'),
(425, NULL, 'Drifloon', '425.png', 'Balloon Pokémon', 8, 3, 3, 285, 68, 'Said to lure away young children and carry them off to the afterlife. Some whisper that Drifloon are formed of reincarnated human souls, but these rumors are as yet unconfirmed.'),
(426, NULL, 'Drifblim', '426.png', 'Blimp Pokémon', 8, 3, 3, 285, 68, 'It can generate and release gas within its body. That''s how it can control the altitude of its drift.'),
(427, NULL, 'Buneary', '427.png', 'Rabbit Pokémon', 1, NULL, 204, 120, 126, 'When it senses danger, it perks up its ears. On cold nights, it sleeps with its head tucked into its fur.'),
(428, NULL, 'Lopunny', '428.png', 'Rabbit Pokémon', 1, NULL, 42, 120, 126, 'Its fur is warm and yet remarkably light. This Pokémon kicks as though it were a master of karate, driving back its opponents with ease.'),
(429, NULL, 'Mismagius', '429.png', 'Magical Pokémon', 8, NULL, 122, NULL, NULL, 'Its cry sounds like an incantation. It is said the cry may rarely be imbued with happiness-giving power.'),
(430, NULL, 'Honchkrow', '430.png', 'Big Boss Pokémon', 17, 3, 113, 252, 147, 'It is merciless by nature. It is said that it never forgives the mistakes of its Murkrow followers.'),
(431, NULL, 'Glameow', '431.png', 'Catty Pokémon', 1, NULL, 126, 162, 119, 'Bewitches humans with its helical tail and piercing gaze. Its hidden claws are quite sharp as well, making this Pokémon an exceedingly tricky opponent if antagonized.'),
(432, NULL, 'Purugly', '432.png', 'Tiger Cat Pokémon', 1, NULL, 272, 162, 49, 'To make itself appear intimidatingly beefy, it tightly cinches its waist with its twin tails.'),
(433, NULL, 'Chingling', '433.png', 'Bell Pokémon', 14, NULL, 122, NULL, NULL, 'This Pokémon gave me an excruciating headache when it seemingly cried out without making a sound. Perhaps there are some sounds that the human ear is simply incapable of hearing.'),
(434, NULL, 'Stunky', '434.png', 'Skunk Pokémon', 4, 17, 246, 3, 119, 'It sprays a foul fluid from its rear. Its stench spreads over a mile radius, driving Pokémon away.'),
(435, NULL, 'Skuntank', '435.png', 'Skunk Pokémon', 4, 17, 246, 3, 119, 'It attacks by spraying a repugnant fluid from its tail, but the stench dulls after a few squirts.'),
(436, NULL, 'Bronzor', '436.png', 'Bronze Pokémon', 9, 14, 122, 94, 95, 'They are found in ancient tombs. The patterns on their backs are said to be imbued with mysterious power.'),
(437, NULL, 'Bronzong', '437.png', 'Bronze Bell Pokémon', 9, 14, 122, 94, 95, 'It brought rains by opening portals to another world. It was revered as a bringer of plentiful harvests.'),
(438, NULL, 'Bonsly', '438.png', 'Bonsai Pokémon', 6, NULL, 250, 201, 193, 'From its eyes, it can expel excess moisture from its body. This liquid is similar in composition to human sweat.'),
(439, NULL, 'Mime Jr.', '439.png', 'Mime Pokémon', 14, 18, 234, 66, 265, 'It likes places where people gather. It mimics foes to confuse them, then makes its getaway.'),
(440, NULL, 'Happiny', '440.png', 'Playhouse Pokémon', 1, NULL, 152, 215, 75, 'It carefully carries a round, white rock that it thinks is an egg. It''s bothered by how curly its hair looks.'),
(441, NULL, 'Chatot', '441.png', 'Music Note Pokémon', 1, 3, 119, 263, 22, 'A versatile performer skilled in the imitation of human speech. It is said that older, more experienced Chatot can even understand the meaning of the words they mimic.'),
(442, NULL, 'Spiritomb', '442.png', 'Forbidden Pokémon', 8, 17, 178, NULL, 110, 'It was formed by uniting 108 spirits. It has been bound to the Odd Keystone to keep it from doing any mischief.'),
(443, NULL, 'Gible', '443.png', 'Land Shark Pokémon', 16, 5, 209, NULL, 203, 'It skulks in caves, and when prey or an enemy passes by, it leaps out and chomps them. The force of its attack sometimes chips its teeth.'),
(444, NULL, 'Gabite', '444.png', 'Cave Pokémon', 16, 5, 209, NULL, 203, 'In rare cases, it molts and sheds its scales. Medicine containing its scales as an ingredient will make a weary body feel invigorated.'),
(445, NULL, 'Garchomp', '445.png', 'Mach Pokémon', 16, 5, 209, NULL, 203, 'It is said that when one runs at high speed, its wings create blades of wind that can fell nearby trees.'),
(446, NULL, 'Munchlax', '446.png', 'Big Eater Pokémon', 1, NULL, 167, 272, 81, 'It wolfs down its weight in food once a day, swallowing it whole with almost no chewing.'),
(447, NULL, 'Riolu', '447.png', 'Emanation Pokémon', 2, NULL, 242, 112, 177, 'They communicate with one another using their auras. They are able to run all through the night.'),
(448, NULL, 'Lucario', '448.png', 'Aura Pokémon', 2, 9, 242, 112, 177, 'It''s said that no foe can remain invisible to Lucario, since it can detect auras—even those of foes it could not otherwise see.'),
(449, NULL, 'Hippopotas', '449.png', 'Hippo Pokémon', 5, NULL, 208, NULL, 205, 'It shuts its nostrils tight, then travels through sand as if walking. They form colonies of around 10.'),
(450, NULL, 'Hippowdon', '450.png', 'Heavyweight Pokémon', 5, NULL, 208, NULL, 205, 'It is surprisingly quick to anger. It holds its mouth agape as a display of its strength.'),
(451, NULL, 'Skorupi', '451.png', 'Scorpion Pokémon', 4, 7, 17, 228, 119, 'Its claws are not only razor-sharp but poisonous, making Skorupi a highly dangerous Pokémon. It seems to be weakened by cold temperatures, however.'),
(452, NULL, 'Drapion', '452.png', 'Ogre Scorp Pokémon', 4, 17, 17, 228, 119, 'Has a brutish, ferocious temperament. With immense strength and a sturdy shell off which swords will bounce, it rampages about and wreaks havoc.'),
(453, NULL, 'Croagunk', '453.png', 'Toxic Mouth Pokémon', 4, 2, 8, 57, 173, 'Inflating its poison sacs, it fills the area with an odd sound and hits flinching opponents with a poison jab.'),
(454, NULL, 'Toxicroak', '454.png', 'Toxic Mouth Pokémon', 4, 2, 8, 57, 173, 'Swaying and dodging the attacks of its foes, it weaves its flexible body in close, then lunges out with its poisonous claws.'),
(455, NULL, 'Carnivine', '455.png', 'Bug Catcher Pokémon', 12, NULL, 122, NULL, NULL, 'Though this is a plant Pokémon, it has a gluttonous and unruly temperament. Carnivine attacks its prey with its cavernous maw wide open.'),
(456, NULL, 'Finneon', '456.png', 'Wing Fish Pokémon', 11, NULL, 258, 248, 296, 'The line running down its side can store sunlight. It shines vividly at night.'),
(457, NULL, 'Lumineon', '457.png', 'Neon Pokémon', 11, NULL, 258, 248, 296, 'With its shining light, it lures its prey close. However, the light also happens to attract ferocious fish Pokémon—its natural predators.'),
(458, NULL, 'Mantyke', '458.png', 'Kite Pokémon', 11, 3, 258, 293, 296, 'Though ball-like in shape, this Pokémon is a proficient swimmer. I have discovered that if a Mantyke spends much time with schools of Remoraid, it will eventually achieve evolution.'),
(459, NULL, 'Snover', '459.png', 'Frost Tree Pokémon', 12, 15, 230, NULL, 234, 'During cold seasons, it migrates to the mountain''s lower reaches. It returns to the snow-covered summit in the spring.'),
(460, NULL, 'Abomasnow', '460.png', 'Frost Tree Pokémon', 12, 15, 230, NULL, 234, 'It lives a quiet life on mountains that are perpetually covered in snow. It hides itself by whipping up blizzards.'),
(461, NULL, 'Weavile', '461.png', 'Sharp Claw Pokémon', 17, 15, 178, NULL, 166, 'They travel in groups of four or five, leaving signs for one another on trees and rocks. They bring down their prey with coordinated attacks.'),
(462, NULL, 'Magnezone', '462.png', 'Magnet Area Pokémon', 13, 9, 135, 250, 5, 'Exposure to a special magnetic field changed Magneton''s molecular structure, turning it into Magnezone.'),
(463, NULL, 'Lickilicky', '463.png', 'Licking Pokémon', 1, NULL, 162, 157, 29, 'Its tongue can extend and contract freely, and it is capable of reaching lengths over 10 times Lickilicky''s height. Beware of the saliva, as it contains corrosive elements.'),
(464, NULL, 'Rhyperior', '464.png', 'Drill Pokémon', 5, 6, 125, 232, 195, 'It puts rocks in holes in its palms and uses its muscles to shoot them. On rare occasions, the Pokémon even shoots out Geodude.'),
(465, NULL, 'Tangrowth', '465.png', 'Vine Pokémon', 12, NULL, 27, 121, 197, 'Draped with long vines, it resembles a shrub in appearance. It swings bundles of vines as though they were arms, wrapping them around prey to ensnare them.'),
(466, NULL, 'Electivire', '466.png', 'Thunderbolt Pokémon', 13, NULL, 146, NULL, 290, 'Its evolution was induced by an unusual item, and its electrical output rises along with its heart rate. From its tails, it can unleash an electric current measuring 20,000 volts.'),
(467, NULL, 'Magmortar', '467.png', 'Blast Pokémon', 10, NULL, 67, NULL, 290, 'Use of a strange item caused this Pokémon to evolve. Fireballs launched from the ends of its tubelike arms are hot enough to melt an iron pot in an instant.'),
(468, NULL, 'Togekiss', '468.png', 'Jubilee Pokémon', 18, 3, 100, 215, 252, 'It will never appear where there is strife. Sightings of this Pokémon have recently become rare.'),
(469, NULL, 'Yanmega', '469.png', 'Ogre Darner Pokémon', 7, 3, 235, 273, 76, 'It prefers to battle by biting apart foes'' heads instantly while flying by at high speed.'),
(470, NULL, 'Leafeon', '470.png', 'Verdant Pokémon', 12, NULL, 121, NULL, 27, 'The younger they are, the more they smell like fresh grass. With age, their fragrance takes on the odor of fallen leaves.'),
(471, NULL, 'Glaceon', '471.png', 'Fresh Snow Pokémon', 15, NULL, 229, NULL, 103, 'It can control its body temperature at will. This enables it to freeze the moisture in the atmosphere, creating flurries of diamond dust.'),
(472, NULL, 'Gliscor', '472.png', 'Fang Scorp Pokémon', 5, 3, 102, 209, 170, 'It glides soundlessly on pitch-black wings and sinks sharp fangs into the throat of its prey. It takes on a look of satisfaction once it has entirely drained its prey of blood.'),
(473, NULL, 'Mamoswine', '473.png', 'Twin Tusk Pokémon', 15, 5, 157, 229, 272, 'Its impressive tusks are made of ice. The ice age is over and the climate has warmed, so this Pokémon''s population has thinned.'),
(474, NULL, 'Porygon-Z', '474.png', 'Virtual Pokémon', 1, NULL, 1, 53, 5, 'Additional software was installed to make it an even better Pokémon. It began acting oddly, however.'),
(475, NULL, 'Gallade', '475.png', 'Blade Pokémon', 14, 2, 242, 218, 118, 'When trying to protect someone, it extends its elbows as if they were swords and fights savagely.'),
(476, NULL, 'Probopass', '476.png', 'Compass Pokémon', 6, 9, 250, 135, 205, 'It is able to emit powerful magnetism, allowing it control over the iron sand that forms its luscious mustache. Using this iron sand, Probopass forms hard stones with which it smites its prey.'),
(477, NULL, 'Dusknoir', '477.png', 'Gripper Pokémon', 8, NULL, 178, NULL, 76, 'Comes to those whose lives have come to an end and escorts their souls to the afterlife. Known to mistakenly take the souls of those who yet have life left in them, albeit rarely.'),
(478, NULL, 'Froslass', '478.png', 'Snow Land Pokémon', 15, 8, 229, NULL, 41, 'It spits out cold air of nearly -60 degrees Fahrenheit to freeze its quarry. It brings frozen prey back to its lair and neatly lines them up.'),
(479, NULL, 'Rotom', '479.png', 'Plasma Pokémon', 13, 8, 122, NULL, NULL, 'Its electricity-like body can enter some kinds of machines and take control in order to make mischief.'),
(480, NULL, 'Uxie', '480.png', 'Knowledge Pokémon', 14, NULL, 122, NULL, NULL, 'A Pokémon feared but also respected for stealing away the memories of evildoers. I have found records that suggest Uxie holds dominion over knowledge.'),
(481, NULL, 'Mesprit', '481.png', 'Emotion Pokémon', 14, NULL, 122, NULL, NULL, 'Known as the Being of Emotion. In legend, this Pokémon was feared, as any who showed disrespect would have their emotions thrown into disarray.'),
(482, NULL, 'Azelf', '482.png', 'Willpower Pokémon', 14, NULL, 122, NULL, NULL, 'The dreaded Being of Willpower. Legends tell of this Pokémon manipulating the will of its adversaries and turning them into puppets of its own.'),
(483, NULL, 'Dialga', '483.png', 'Temporal Pokémon', 9, 16, 178, NULL, 266, 'This Pokémon is spoken of in legend. It is said that time began moving when Dialga was born.'),
(484, NULL, 'Palkia', '484.png', 'Spatial Pokémon', 11, 16, 178, NULL, 266, 'It is said to live in a gap in the spatial dimension parallel to ours. Palkia appears in mythology.'),
(485, NULL, 'Heatran', '485.png', 'Lava Dome Pokémon', 10, 9, 69, NULL, 67, 'It dwells in volcanic caves. It digs in with its cross-shaped feet to crawl on ceilings and walls.'),
(486, NULL, 'Regigigas', '486.png', 'Colossal Pokémon', 1, NULL, 226, NULL, NULL, 'It''s said that Regigigas created other Pokémon from many different materials before it moved the continents to where they are today.'),
(487, NULL, 'Giratina', '487.png', 'Renegade Pokémon', 8, 16, 178, NULL, 266, 'A Pokémon that is said to live in a world on the reverse side of ours. It appears in an ancient cemetery.'),
(488, NULL, 'Cresselia', '488.png', 'Lunar Pokémon', 14, NULL, 122, NULL, NULL, 'When it flies, it releases shiny particles from its veil-like wings. It is said to represent the crescent moon.'),
(489, NULL, 'Phione', '489.png', 'Sea Drifter Pokémon', 11, NULL, 101, NULL, NULL, 'A Pokémon that lives in warm seas. It inflates the flotation sac on its head to drift and search for food.'),
(490, NULL, 'Manaphy', '490.png', 'Seafaring Pokémon', 11, NULL, 101, NULL, NULL, 'Water makes up 80 percent of its body. This Pokémon is easily affected by its environment.'),
(491, NULL, 'Darkrai', '491.png', 'Pitch-Black Pokémon', 17, NULL, 14, NULL, NULL, 'Folklore has it that on moonless nights, this Pokémon will make people see horrific nightmares.'),
(492, NULL, 'Shaymin', '492.png', 'Gratitude Pokémon', 12, NULL, 152, NULL, 215, 'It can dissolve toxins in the air to instantly transform ruined land into a lush field of flowers.'),
(493, NULL, 'Arceus', '493.png', 'Alpha Pokémon', 1, NULL, 149, NULL, NULL, 'It is told in mythology that this Pokémon was the first Pokémon born before the universe even existed.'),
(494, NULL, 'Victini', '494.png', 'Victory Pokémon', 14, 10, 289, NULL, NULL, 'This Pokémon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.'),
(495, NULL, 'Snivy', '495.png', 'Grass Snake Pokémon', 12, NULL, 161, NULL, 35, 'They photosynthesize by bathing their tails in sunlight. When they are not feeling well, their tails droop.'),
(496, NULL, 'Servine', '496.png', 'Grass Snake Pokémon', 12, NULL, 161, NULL, 35, 'It moves along the ground as if sliding. Its swift movements befuddle its foes, and it then attacks with a vine whip.'),
(497, NULL, 'Serperior', '497.png', 'Regal Pokémon', 12, NULL, 161, NULL, 35, 'It can stop its opponents'' movements with just a glare. It takes in solar energy and boosts it internally.'),
(498, NULL, 'Tepig', '498.png', 'Fire Pig Pokémon', 10, NULL, 23, NULL, 272, 'It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.'),
(499, NULL, 'Pignite', '499.png', 'Fire Pig Pokémon', 10, 2, 23, NULL, 272, 'When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.'),
(500, NULL, 'Emboar', '500.png', 'Mega Fire Pig Pokémon', 10, 2, 23, NULL, 195, 'It has mastered fast and powerful fighting moves. It grows a beard of fire.'),
(501, NULL, 'Oshawott', '501.png', 'Sea Otter Pokémon', 11, NULL, 274, NULL, 221, 'It fights using the scalchop on its stomach. In response to an attack, it retaliates immediately by slashing.'),
(502, NULL, 'Dewott', '502.png', 'Discipline Pokémon', 11, NULL, 274, NULL, 221, 'As a result of strict training, each Dewott learns different forms for using the scalchops.'),
(503, NULL, 'Samurott', '503.png', 'Formidable Pokémon', 11, NULL, 274, NULL, 221, 'One swing of the sword incorporated in its armor can fell an opponent. A simple glare from one of them quiets everybody.'),
(503, 3, 'Samurott', '503-hisui.png', 'Formidable Pokémon', 11, 17, 274, NULL, 218, 'Hard of heart and deft of blade, this rare form of Samurott is a product of the Pokémon''s evolution in the region of Hisui. Its turbulent blows crash into foes like ceaseless pounding waves.'),
(504, NULL, 'Patrat', '504.png', 'Scout Pokémon', 1, NULL, 204, 119, 5, 'Extremely cautious, one of them will always be on the lookout, but it won''t notice a foe coming from behind.'),
(505, NULL, 'Watchog', '505.png', 'Lookout Pokémon', 1, NULL, 106, 119, 5, 'When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.'),
(506, NULL, 'Lillipup', '506.png', 'Puppy Pokémon', 1, NULL, 290, 167, 204, 'This Pokémon is far brighter than the average child, and Lillipup won''t forget the love it receives or any abuse it suffers.'),
(507, NULL, 'Herdier', '507.png', 'Loyal Dog Pokémon', 1, NULL, 114, 206, 212, 'The black fur that covers this Pokémon''s body is dense and springy. Even sharp fangs bounce right off.'),
(508, NULL, 'Stoutland', '508.png', 'Big-Hearted Pokémon', 1, NULL, 114, 206, 212, 'Stoutland is immensely proud of its impressive moustache. It''s said that moustache length is what determines social standing among this species.'),
(509, NULL, 'Purrloin', '509.png', 'Devious Pokémon', 17, NULL, 126, 285, 177, 'Opponents that get drawn in by its adorable behavior come away with stinging scratches from its claws and stinging pride from its laughter.'),
(510, NULL, 'Liepard', '510.png', 'Cruel Pokémon', 17, NULL, 126, 285, 177, 'Don''t be fooled by its gorgeous fur and elegant figure. This is a moody and vicious Pokémon.'),
(511, NULL, 'Pansage', '511.png', 'Grass Monkey Pokémon', 12, NULL, 81, NULL, 161, 'It''s good at finding berries and gathers them from all over. It''s kind enough to share them with friends.'),
(512, NULL, 'Simisage', '512.png', 'Thorn Monkey Pokémon', 12, NULL, 81, NULL, 161, 'Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.'),
(513, NULL, 'Pansear', '513.png', 'High Temp Pokémon', 10, NULL, 81, NULL, 23, 'This Pokémon lives in caves in volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.'),
(514, NULL, 'Simisear', '514.png', 'Ember Pokémon', 10, NULL, 81, NULL, 23, 'When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.'),
(515, NULL, 'Panpour', '515.png', 'Spray Pokémon', 11, NULL, 81, NULL, 274, 'The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large'),
(516, NULL, 'Simipour', '516.png', 'Geyser Pokémon', 11, NULL, 81, NULL, 274, 'It prefers places with clean water. When its tuft runs low, it replenishes it by siphoning up water with its tail.'),
(517, NULL, 'Munna', '517.png', 'Dream Eater Pokémon', 14, NULL, 74, 261, 266, 'It eats dreams and releases mist. The mist is pink when it''s eating a good dream, and black when it''s eating a nightmare.'),
(518, NULL, 'Musharna', '518.png', 'Drowsing Pokémon', 14, NULL, 74, 261, 266, 'It drowses and dreams all the time. It''s best to leave it be if it''s just woken up, as it''s a terrible grump when freshly roused from sleep.'),
(519, NULL, 'Pidove', '519.png', 'Tiny Pigeon Pokémon', 1, 3, 22, 252, 199, 'Where people go, these Pokémon follow. If you''re scattering food for them, be careful— several hundred of them can gather at once.'),
(520, NULL, 'Tranquill', '520.png', 'Wild Pigeon Pokémon', 1, 3, 22, 252, 199, 'These bright Pokémon have acute memories. Apparently delivery workers often choose them as their partners.'),
(521, NULL, 'Unfezant', '521.png', 'Proud Pokémon', 1, 3, 22, 252, 199, 'Males swing their head plumage to threaten opponents. The females'' flying abilities surpass those of the males.'),
(522, NULL, 'Blitzle', '522.png', 'Electrified Pokémon', 13, NULL, 125, 146, 210, 'Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.'),
(523, NULL, 'Zebstrika', '523.png', 'Thunderbolt Pokémon', 13, NULL, 125, 146, 210, 'They have lightning-like movements. When Zebstrika run at full speed, the sound of thunder reverberates.'),
(524, NULL, 'Roggenrola', '524.png', 'Mantle Pokémon', 6, NULL, 250, 297, 205, 'When it detects a noise, it starts to move. The energy core inside it makes this Pokémon slightly warm to the touch.'),
(525, NULL, 'Boldore', '525.png', 'Ore Pokémon', 6, NULL, 250, 297, 205, 'It relies on sound in order to monitor what''s in its vicinity. When angered, it will attack without ever changing the direction it''s facing.'),
(526, NULL, 'Gigalith', '526.png', 'Compressed Pokémon', 6, NULL, 250, 297, 205, 'Although its energy blasts can blow away a dump truck, they have a limitation— they can only be fired when the sun is out.'),
(527, NULL, 'Woobat', '527.png', 'Bat Pokémon', 14, 3, 284, 120, 224, 'While inside a cave, if you look up and see lots of heart-shaped marks lining the walls, it''s evidence that Woobat live there.'),
(528, NULL, 'Swoobat', '528.png', 'Courting Pokémon', 14, 3, 284, 120, 224, 'The auspicious shape of this Pokémon''s nose apparently led some regions to consider Swoobat a symbol of good luck.'),
(529, NULL, 'Drilbur', '529.png', 'Mole Pokémon', 5, NULL, 206, 205, 144, 'It''s a digger, using its claws to burrow through the ground. It causes damage to vegetable crops, so many farmers have little love for it.'),
(530, NULL, 'Excadrill', '530.png', 'Subterrene Pokémon', 5, 9, 206, 205, 144, 'Known as the Drill King, this Pokémon can tunnel through the terrain at speeds of over 90 mph.'),
(531, NULL, 'Audino', '531.png', 'Hearing Pokémon', 1, NULL, 93, 197, 120, 'This Pokémon has a kind heart. By touching with its feelers, Audino can gauge other creatures'' feelings and physical conditions.'),
(532, NULL, 'Timburr', '532.png', 'Muscular Pokémon', 2, NULL, 90, 220, 117, 'Timburr that have started carrying logs that are about three times their size are nearly ready to evolve.'),
(533, NULL, 'Gurdurr', '533.png', 'Muscular Pokémon', 2, NULL, 90, 220, 117, 'Gurdurr excels at demolition—construction is not its forte. In any case, there''s skill in the way this Pokémon wields its metal beam.'),
(534, NULL, 'Conkeldurr', '534.png', 'Muscular Pokémon', 2, NULL, 90, 220, 117, 'When going all out, this Pokémon throws aside its concrete pillars and leaps at opponents to pummel them with its fists.'),
(535, NULL, 'Tympole', '535.png', 'Tadpole Pokémon', 11, NULL, 258, 101, 293, 'It uses sound waves to communicate with others of its kind. People and other Pokémon species can''t hear its cries of warning.'),
(536, NULL, 'Palpitoad', '536.png', 'Vibration Pokémon', 11, 5, 258, 101, 293, 'On occasion, their cries are sublimely pleasing to the ear. Palpitoad with larger lumps on their bodies can sing with a wider range of sounds.'),
(537, NULL, 'Seismitoad', '537.png', 'Vibration Pokémon', 11, 5, 258, 173, 293, 'The vibrating of the bumps all over its body causes earthquake-like tremors. Seismitoad and Croagunk are similar species.'),
(538, NULL, 'Throh', '538.png', 'Judo Pokémon', 2, NULL, 90, 112, 144, 'It performs throwing moves with first-rate skill. Over the course of many battles, Throh''s belt grows darker as it absorbs its wearer''s sweat.'),
(539, NULL, 'Sawk', '539.png', 'Karate Pokémon', 2, NULL, 250, 112, 144, 'If you see a Sawk training in the mountains in its single-minded pursuit of strength, it''s best to quietly pass by.'),
(540, NULL, 'Sewaddle', '540.png', 'Sewing Pokémon', 7, 12, 256, 27, 160, 'Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.'),
(541, NULL, 'Swadloon', '541.png', 'Leaf-Wrapped Pokémon', 7, 12, 256, 27, 160, 'It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.'),
(542, NULL, 'Leavanny', '542.png', 'Nurturing Pokémon', 7, 12, 256, 27, 160, 'It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.'),
(543, NULL, 'Venipede', '543.png', 'Centipede Pokémon', 7, 4, 171, 256, 235, 'Its fangs are highly venomous. If this Pokémon finds prey it thinks it can eat, it leaps for them without any thought of how things might turn out.'),
(544, NULL, 'Whirlipede', '544.png', 'Curlipede Pokémon', 7, 4, 171, 256, 235, 'Whirlipede protects itself with a sturdy shell and poisonous spikes while it stores up the energy it''ll need for evolution.'),
(545, NULL, 'Scolipede', '545.png', 'Megapede Pokémon', 7, 4, 171, 256, 235, 'Scolipede latches on to its prey with the claws on its neck before slamming them into the ground and jabbing them with its claws'' toxic spikes.'),
(546, NULL, 'Cottonee', '546.png', 'Cotton Puff Pokémon', 12, 18, 177, 110, 27, 'It shoots cotton from its body to protect itself. If it gets caught up in hurricane-strength winds, it can get sent to the other side of the Earth.'),
(547, NULL, 'Whimsicott', '547.png', 'Windveiled Pokémon', 12, 18, 177, 110, 27, 'As long as this Pokémon bathes in sunlight, its cotton keeps growing. If too much cotton fluff builds up, Whimsicott tears it off and scatters it.'),
(548, NULL, 'Petilil', '548.png', 'Bulb Pokémon', 12, NULL, 27, 162, 121, 'If the leaves on its head are pruned with regularity, this Pokémon can be grown into a fine plump shape.'),
(549, NULL, 'Lilligant', '549.png', 'Flowering Pokémon', 12, NULL, 27, 162, 121, 'No matter how much time and money is spent raising it, its flowers are the most beautiful when they bloom in the wild.'),
(549, 3, 'Lilligant', '549-hisui.png', 'Spinning Pokémon', 12, 2, 27, 100, 121, 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.'),
(550, NULL, 'Basculin', '550.png', 'Hostile Pokémon', 11, NULL, 195, 1, 144, 'Red and blue Basculin get along so poorly, they''ll start fighting instantly. These Pokémon are very hostile.'),
(551, NULL, 'Sandile', '551.png', 'Desert Croc Pokémon', 5, 17, 114, 147, 6, 'They live hidden under hot desert sands in order to keep their body temperature from dropping.'),
(552, NULL, 'Krokorok', '552.png', 'Desert Croc Pokémon', 5, 17, 114, 147, 6, 'Thanks to the special membrane covering its eyes, it can see its surroundings clearly, even in the middle of the night.'),
(553, NULL, 'Krookodile', '553.png', 'Intimidation Pokémon', 5, 17, 114, 147, 6, 'Its unique faculty of sight can detect small prey more than 30 miles away, even in the midst of a sandstorm.'),
(554, NULL, 'Darumaka', '554.png', 'Zen Charm Pokémon', 10, NULL, 100, NULL, 112, 'This popular symbol of good fortune will never fall over in its sleep, no matter how it''s pushed or pulled.'),
(554, 2, 'Darumaka', '554-galar.png', 'Zen Charm Pokémon', 15, NULL, 100, NULL, 112, 'It lived in snowy areas for so long that its fire sac cooled off and atrophied. It now has an organ that generates cold instead.'),
(555, NULL, 'Darmanitan', '555.png', 'Blazing Pokémon', 10, NULL, 220, NULL, 305, 'Its internal fire burns at 2,500 degrees Fahrenheit, making enough power that it can destroy a dump truck with one punch.'),
(555, 2, 'Darmanitan', '555-galar.png', 'Zen Charm Pokémon', 15, NULL, 84, NULL, 305, 'On days when blizzards blow through, it comes down to where people live. It stashes food in the snowball on its head, taking it home for later.'),
(556, NULL, 'Maractus', '556.png', 'Cactus Pokémon', 12, NULL, 293, 27, 248, 'With noises that could be mistaken for the rattles of maracas, it creates an upbeat rhythm, startling bird Pokémon and making them fly off in a hurry.'),
(557, NULL, 'Dwebble', '557.png', 'Rock Inn Pokémon', 7, 6, 250, 221, 297, 'It first tries to find a rock to live in, but if there are no suitable rocks to be found, Dwebble may move in to the ports of a Hippowdon.'),
(558, NULL, 'Crustle', '558.png', 'Stone Home Pokémon', 7, 6, 250, 221, 297, 'Its thick claws are its greatest weapons. They''re mighty enough to crack Rhyperior''s carapace.'),
(559, NULL, 'Scraggy', '559.png', 'Shedding Pokémon', 17, 2, 219, 147, 114, 'It protects itself with its durable skin. It''s thought that this Pokémon will evolve once its skin has completely stretched out.'),
(560, NULL, 'Scrafty', '560.png', 'Hoodlum Pokémon', 17, 2, 219, 147, 114, 'While mostly known for having the temperament of an aggressive ruffian, this Pokémon takes very good care of its family, friends, and territory.'),
(561, NULL, 'Sigilyph', '561.png', 'Avianoid Pokémon', 14, 3, 304, 132, 273, 'A discovery was made in the desert where Sigilyph fly. The ruins of what may have been an ancient city were found beneath the sands.'),
(562, NULL, 'Yamask', '562.png', 'Spirit Pokémon', 8, NULL, 150, NULL, NULL, 'The spirit of a person from a bygone age became this Pokémon. It rambles through ruins, searching for someone who knows its face.'),
(562, 2, 'Yamask', '562-galar.png', 'Spirit Pokémon', 5, 8, 292, NULL, NULL, 'A clay slab with cursed engravings took possession of a Yamask. The slab is said to be absorbing the Yamask''s dark power.'),
(563, NULL, 'Cofagrigus', '563.png', 'Coffin Pokémon', 8, NULL, 150, NULL, NULL, 'There are many depictions of Cofagrigus decorating ancient tombs. They''re symbols of the wealth that kings of bygone eras had.'),
(564, NULL, 'Tirtouga', '564.png', 'Prototurtle Pokémon', 11, 6, 232, 250, 258, 'Tirtouga is considered to be the ancestor of many turtle Pokémon. It was restored to life from a fossil.'),
(565, NULL, 'Carracosta', '565.png', 'Prototurtle Pokémon', 11, 6, 232, 250, 258, 'This Pokémon emerges from the water in search of prey despite the fact that it moves more slowly on land.'),
(566, NULL, 'Archen', '566.png', 'First Bird Pokémon', 6, 3, 48, NULL, NULL, 'Archen is said to be the ancestor of bird Pokémon. It lived in treetops, eating berries and bug Pokémon.'),
(567, NULL, 'Archeops', '567.png', 'First Bird Pokémon', 6, 3, 48, NULL, NULL, 'Though capable of flight, Archeops was apparently better at hunting on the ground.'),
(568, NULL, 'Trubbish', '568.png', 'Trash Bag Pokémon', 4, NULL, 246, 247, 3, 'Its favorite places are unsanitary ones. If you leave trash lying around, you could even find one of these Pokémon living in your room.'),
(569, NULL, 'Garbodor', '569.png', 'Trash Heap Pokémon', 4, NULL, 246, 247, 3, 'The toxic liquid it launches from its right arm is so virulent that it can kill a weakened creature instantly.'),
(570, NULL, 'Zorua', '570.png', 'Tricky Fox Pokémon', 17, NULL, 107, NULL, NULL, 'To protect themselves from danger, they hide their true identities by transforming into people and Pokémon.'),
(570, 3, 'Zorua', '570-hisui.png', 'Spiteful Fox Pokémon', 1, 8, 107, NULL, NULL, 'A once-departed soul, returned to life in Hisui. Derives power from resentment, which rises as energy atop its head and takes on the forms of foes. In this way, Zorua vents lingering malice.'),
(571, NULL, 'Zoroark', '571.png', 'Illusion Fox Pokémon', 17, NULL, 107, NULL, NULL, 'Each has the ability to fool a large group of people simultaneously. They protect their lair with illusory scenery.'),
(571, 3, 'Zoroark', '571-hisui.png', 'Baneful Fox Pokémon', 1, 8, 107, NULL, NULL, 'With its disheveled white fur, it looks like an embodiment of death. Heedless of its own safety, Zoroark attacks its nemeses with a bitter energy so intense, it lacerates Zoroark''s own body.'),
(572, NULL, 'Minccino', '572.png', 'Chinchilla Pokémon', 1, NULL, 42, 265, 225, 'They pet each other with their tails as a form of greeting. Of the two, the one whose tail is fluffier is a bit more boastful.'),
(573, NULL, 'Cinccino', '573.png', 'Scarf Pokémon', 1, NULL, 42, 265, 225, 'A special oil that seeps through their fur helps them avoid attacks. The oil fetches a high price at market.'),
(574, NULL, 'Gothita', '574.png', 'Fixation Pokémon', 14, NULL, 76, 33, 217, 'Beware of touching the ribbon-shaped feelers that control its psychic power. Gothita will begin bawling if you do.'),
(575, NULL, 'Gothorita', '575.png', 'Manipulate Pokémon', 14, NULL, 76, 33, 217, 'Using its psychic power, it arranges pebbles to form the shapes of constellations. Some people believe this Pokémon came from outer space.'),
(576, NULL, 'Gothitelle', '576.png', 'Astral Body Pokémon', 14, NULL, 76, 33, 217, 'It gazes at the stars to predict the future. It acts somewhat detached because it has seen the end of all existence.'),
(577, NULL, 'Solosis', '577.png', 'Cell Pokémon', 14, NULL, 160, 132, 197, 'Many say that the special liquid covering this Pokémon''s body would allow it to survive in the vacuum of space.'),
(578, NULL, 'Duosion', '578.png', 'Mitosis Pokémon', 14, NULL, 160, 132, 197, 'Its brain has split into two, and the two halves rarely think alike. Its actions are utterly unpredictable.'),
(579, NULL, 'Reuniclus', '579.png', 'Multiplying Pokémon', 14, NULL, 160, 132, 197, 'It''s said that drinking the liquid surrounding Reuniclus grants wisdom. Problem is, the liquid is highly toxic to anything besides Reuniclus itself.'),
(580, NULL, 'Ducklett', '580.png', 'Water Bird Pokémon', 11, 3, 119, 22, 101, 'They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.'),
(581, NULL, 'Swanna', '581.png', 'White Bird Pokémon', 11, 3, 119, 22, 101, 'Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.'),
(582, NULL, 'Vanillite', '582.png', 'Fresh Snow Pokémon', 15, NULL, 103, 229, 297, 'Supposedly, this Pokémon was born from an icicle. It spews out freezing air at -58 degrees Fahrenheit to make itself more comfortable.'),
(583, NULL, 'Vanillish', '583.png', 'Icy Snow Pokémon', 15, NULL, 103, 229, 297, 'It blasts enemies with cold air reaching -148 degrees Fahrenheit, freezing them solid. But it spares their lives afterward—it''s a kind Pokémon.'),
(584, NULL, 'Vanilluxe', '584.png', 'Snowstorm Pokémon', 15, NULL, 103, 230, 297, 'People believe this Pokémon formed when two Vanillish stuck together. Its body temperature is roughly 21 degrees Fahrenheit.'),
(585, NULL, 'Deerling', '585.png', 'Season Pokémon', 1, 12, 27, 210, 215, 'The turning of the seasons changes the color and scent of this Pokémon''s fur. People use it to mark the seasons.'),
(586, NULL, 'Sawsbuck', '586.png', 'Season Pokémon', 1, 12, 27, 210, 215, 'They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.'),
(587, NULL, 'Emolga', '587.png', 'Sky Squirrel Pokémon', 13, 3, 241, NULL, 146, 'This Pokémon absolutely loves sweet berries. Sometimes it stuffs its cheeks full of so much food that it can''t fly properly.'),
(588, NULL, 'Karrablast', '588.png', 'Clamping Pokémon', 7, NULL, 256, 219, 155, 'It spits a liquid from its mouth to melt through Shelmet''s shell. Karrablast doesn''t eat the shell— it eats only the contents.'),
(589, NULL, 'Escavalier', '589.png', 'Cavalry Pokémon', 7, 9, 256, 221, 160, 'These Pokémon evolve by wearing the shell covering of a Shelmet. The steel armor protects their whole body.'),
(590, NULL, 'Foongus', '590.png', 'Mushroom Pokémon', 12, 4, 60, NULL, 197, 'This Pokémon prefers damp places. It spurts out poison spores to repel approaching enemies.'),
(591, NULL, 'Amoonguss', '591.png', 'Mushroom Pokémon', 12, 4, 60, NULL, 197, 'Amoonguss mimics Poke Balls. It is not yet clear whether this mimicry is effective against other Pokémon.'),
(592, NULL, 'Frillish', '592.png', 'Floating Pokémon', 11, 8, 293, 41, 43, 'Using the invisible poison spikes on its veillike arms and legs, it paralyzes its enemies and causes them to drown.'),
(593, NULL, 'Jellicent', '593.png', 'Floating Pokémon', 11, 8, 293, 41, 43, 'Fishermen are terrified of Jellicent. It''s rumored to drag them into the sea and steal their lives away.'),
(594, NULL, 'Alomomola', '594.png', 'Caring Pokémon', 11, NULL, 93, 101, 197, 'They float upon the open sea. Many water Pokémon gather in the area around Alomomola.'),
(595, NULL, 'Joltik', '595.png', 'Attaching Pokémon', 7, 13, 34, 286, 256, 'Joltik can be found clinging to other Pokémon. It''s soaking up static electricity because it can''t produce a charge on its own.'),
(596, NULL, 'Galvantula', '596.png', 'EleSpider Pokémon', 7, 13, 34, 286, 256, 'It lays traps of electrified threads near the nests of bird Pokémon, aiming to snare chicks that are not yet good at flying.'),
(597, NULL, 'Ferroseed', '597.png', 'Thorn Seed Pokémon', 12, 9, 116, NULL, NULL, 'Mossy caves are their preferred dwellings. Enzymes contained in mosses help Ferroseed''s spikes grow big and strong.'),
(598, NULL, 'Ferrothorn', '598.png', 'Thorn Pod Pokémon', 12, 9, 116, NULL, 8, 'Its spikes are harder than steel. This Pokémon crawls across rock walls by stabbing the spikes on its feelers into the stone.'),
(599, NULL, 'Klink', '599.png', 'Gear Pokémon', 9, NULL, 169, 141, 28, 'It''s suspected that Klink were the inspiration behind ancient people''s invention of the first gears.'),
(600, NULL, 'Klang', '600.png', 'Gear Pokémon', 9, NULL, 169, 141, 28, 'When Klang goes all out, the minigear links up perfectly with the outer part of the big gear, and this Pokémon''s rotation speed increases sharply.'),
(601, NULL, 'Klinklang', '601.png', 'Gear Pokémon', 9, NULL, 169, 141, 28, 'The three gears that compose this Pokémon spin at high speed. Its new spiked gear isn''t a living creature.'),
(602, NULL, 'Tynamo', '602.png', 'EleFish Pokémon', 13, NULL, 122, NULL, NULL, 'These Pokémon move in schools. They have an electricity-generating organ, so they discharge electricity if in danger.'),
(603, NULL, 'Eelektrik', '603.png', 'EleFish Pokémon', 13, NULL, 122, NULL, NULL, 'These Pokémon have a big appetite. When they spot their prey, they attack it and paralyze it with electricity.'),
(604, NULL, 'Eelektross', '604.png', 'EleFish Pokémon', 13, NULL, 122, NULL, NULL, 'It latches on to prey with its sucker mouth, sinking in its fangs and shocking the prey with powerful electricity.'),
(605, NULL, 'Elgyem', '605.png', 'Cerebral Pokémon', 14, NULL, 266, 261, 5, 'This Pokémon was discovered about 50 years ago. Its highly developed brain enables it to exert its psychic powers.'),
(606, NULL, 'Beheeyem', '606.png', 'Cerebral Pokémon', 14, NULL, 266, 261, 5, 'Sometimes found drifting above wheat fields, this Pokémon can control the memories of its opponents.'),
(607, NULL, 'Litwick', '607.png', 'Candle Pokémon', 8, 10, 69, 67, 110, 'The flame on its head keeps its body slightly warm. This Pokémon takes lost children by the hand to guide them to the spirit world.'),
(608, NULL, 'Lampent', '608.png', 'Lamp Pokémon', 8, 10, 69, 67, 110, 'It lurks in cities, pretending to be a lamp. Once it finds someone whose death is near, it will trail quietly after them.'),
(609, NULL, 'Chandelure', '609.png', 'Luring Pokémon', 8, 10, 69, 67, 110, 'In homes illuminated by Chandelure instead of lights, funerals were a constant occurrence- or so it''s said.'),
(610, NULL, 'Axew', '610.png', 'Tusk Pokémon', 16, NULL, 199, 144, 286, 'If you see peculiar teeth marks on boulders or trees, it means an Axew is likely living nearby.'),
(611, NULL, 'Fraxure', '611.png', 'Axe Jaw Pokémon', 16, NULL, 199, 144, 286, 'Fraxure uses its thick tusks to neatly cut prey into two portions—one to eat now and one to save for later.'),
(612, NULL, 'Haxorus', '612.png', 'Axe Jaw Pokémon', 16, NULL, 199, 144, 286, 'It overwhelms enemies with its prized tusks, which are sharp enough to cut through a metal transmission tower in one strike.'),
(613, NULL, 'Cubchoo', '613.png', 'Chill Pokémon', 15, NULL, 229, 227, 193, 'When Cubchoo starts sneezing, watch out! If it spatters you with its frosty snot, you''ll get frostbite.'),
(614, NULL, 'Beartic', '614.png', 'Freezing Pokémon', 15, NULL, 229, 227, 258, 'Feared as the Snow-White Demon in northern lands, Beartic uses its frosty claws and fangs to attack prey.'),
(615, NULL, 'Cryogonal', '615.png', 'Crystallizing Pokémon', 15, NULL, 122, NULL, NULL, 'Cryogonal uses its chains of ice to constrict its opponents and then flash-freezes them where they stand.'),
(616, NULL, 'Shelmet', '616.png', 'Snail Pokémon', 7, NULL, 101, 221, 160, 'It has a strange physiology that responds to electricity. When together with Karrablast, Shelmet evolves for some reason.'),
(617, NULL, 'Accelgor', '617.png', 'Shell Out Pokémon', 7, NULL, 101, 247, 285, 'It moves with blinding speed and lobs poison at foes. Featuring Accelgor as a main character is a surefire way to make a movie or comic popular.'),
(618, NULL, 'Stunfisk', '618.png', 'Trap Pokémon', 5, 13, 241, 126, 209, 'For some reason, this Pokémon smiles slightly when it emits a strong electric current from the yellow markings on its body.'),
(618, 2, 'Stunfisk', '618-galar.png', 'Trap Pokémon', 5, 9, 139, NULL, NULL, 'Its conspicuous lips lure prey in as it lies in wait in the mud. When prey gets close, Stunfisk clamps its jagged steel fins down on them.'),
(619, NULL, 'Mienfoo', '619.png', 'Martial Arts Pokémon', 2, NULL, 112, 197, 195, 'Though small, Mienfoo''s temperament is fierce. Any creature that approaches Mienfoo carelessly will be greeted with a flurry of graceful attacks.'),
(620, NULL, 'Mienshao', '620.png', 'Martial Arts Pokémon', 2, NULL, 112, 197, 195, 'Delivered at blinding speeds, kicks from this Pokémon can shatter massive boulders into tiny pieces.'),
(621, NULL, 'Druddigon', '621.png', 'Cave Pokémon', 16, NULL, 203, 220, 144, 'Druddigon are vicious and cunning. They take up residence in nests dug out by other Pokémon, treating the stolen nests as their own lairs.'),
(622, NULL, 'Golett', '622.png', 'Automaton Pokémon', 5, 8, 117, 120, 155, 'This Pokémon was created from clay. It received orders from its master many thousands of years ago, and it still follows those orders to this day.'),
(623, NULL, 'Golurk', '623.png', 'Automaton Pokémon', 5, 8, 117, 120, 155, 'There''s a theory that inside Golurk is a perpetual motion machine that produces limitless energy, but this belief hasn''t been proven.'),
(624, NULL, 'Pawniard', '624.png', 'Sharp Blade Pokémon', 17, 9, 49, 112, 178, 'Any chips in its blades would prove fatal for it. After each battle, it diligently maintains its blades using its favorite sharpening stone.'),
(625, NULL, 'Bisharp', '625.png', 'Sword Blade Pokémon', 17, 9, 49, 112, 178, 'Bisharp mercilessly cuts its opponents to pieces with the sharp blades covering its body. It will do anything to win.'),
(626, NULL, 'Bouffalant', '626.png', 'Bash Buffalo Pokémon', 1, NULL, 195, 210, 234, 'These Pokémon live in herds of about 20 individuals. Bouffalant that betray the herd will lose the hair on their heads for some reason.'),
(627, NULL, 'Rufflet', '627.png', 'Eaglet Pokémon', 1, 3, 119, 220, 100, 'With its sharp claws, this Pokémon pierces its prey, and then it pecks at them. Although it also consumes berries, it''s a carnivore at heart.'),
(628, NULL, 'Braviary', '628.png', 'Valiant Pokémon', 1, 3, 119, 220, 49, 'For the sake of its friends, this brave warrior of the sky will not stop battling, even if injured.'),
(628, 3, 'Braviary', '628-hisui.png', 'Battle Cry Pokémon', 14, 3, 119, 220, 273, 'Screaming a bloodcurdling battle cry, this huge and ferocious bird Pokémon goes out on the hunt. It blasts lakes with shock waves, then scoops up any prey that float to the water''s surface.'),
(629, NULL, 'Vullaby', '629.png', 'Diapered Pokémon', 17, 3, 22, 160, 297, 'Vullaby grow quickly. Bones that have gotten too small for older Vullaby to wear often get passed down to younger ones in the nest.'),
(630, NULL, 'Mandibuzz', '630.png', 'Bone Vulture Pokémon', 17, 3, 22, 160, 297, 'They adorn themselves with bones. There seem to be fashion trends among them, as different bones come into and fall out of popularity.'),
(631, NULL, 'Heatmor', '631.png', 'Anteater Pokémon', 10, NULL, 81, 69, 299, 'A flame serves as its tongue, melting through the hard shell of Durant so that Heatmor can devour their insides.'),
(632, NULL, 'Durant', '632.png', 'Iron Ant Pokémon', 7, 9, 256, 100, 282, 'They lay their eggs deep inside their nests. When attacked by Heatmor, they retaliate using their massive mandibles.'),
(633, NULL, 'Deino', '633.png', 'Irate Pokémon', 17, 16, 100, NULL, NULL, 'It nests deep inside a cave. Food there is scarce, so Deino will sink its teeth into anything that moves and attempt to eat it.'),
(634, NULL, 'Zweilous', '634.png', 'Hostile Pokémon', 17, 16, 100, NULL, NULL, 'The two heads have different likes and dislikes. Because the heads fight with each other, Zweilous gets stronger without needing to rely on others.'),
(635, NULL, 'Hydreigon', '635.png', 'Brutal Pokémon', 17, 16, 122, NULL, NULL, 'It''s said that Hydreigon grew ferocious because people in times long past loathed it, considering it to be evil incarnate and attacking it relentlessly.'),
(636, NULL, 'Larvesta', '636.png', 'Torch Pokémon', 7, 10, 67, NULL, 256, 'In ancient times, Larvesta was worshiped as the emissary of the sun. However, it was also viewed as a burden since it often caused forest fires.'),
(637, NULL, 'Volcarona', '637.png', 'Sun Pokémon', 7, 10, 67, NULL, 256, 'This Pokémon scatters burning scales. Most of the danger of these scales is not in their heat—it''s in the way they rob the surrounding air of oxygen.'),
(638, NULL, 'Cobalion', '638.png', 'Iron Will Pokémon', 9, 2, 118, NULL, NULL, 'This Pokémon appears in a legend alongside Terrakion and Virizion, fighting against humans in defense of the Unova region''s Pokémon.'),
(639, NULL, 'Terrakion', '639.png', 'Cavern Pokémon', 6, 2, 118, NULL, NULL, 'In Unovan legend, Terrakion battled against humans in an effort to protect other Pokémon.'),
(640, NULL, 'Virizion', '640.png', 'Grassland Pokémon', 12, 2, 118, NULL, NULL, 'A legend tells of this Pokémon working together with Cobalion and Terrakion to protect the Pokémon of the Unova region.'),
(641, NULL, 'Tornadus', '641.png', 'Cyclone Pokémon', 3, NULL, 177, NULL, 49, 'Tornadus expels massive energy from its tail, causing severe storms. Its power is great enough to blow houses away.'),
(642, NULL, 'Thundurus', '642.png', 'Bolt Strike Pokémon', 13, 3, 177, NULL, 49, 'They say this wielder of electricity has waged war with its nemesis, Tornadus, since time immemorial. The lightning bolts it hurls pierce the very earth and enrich the soil.'),
(643, NULL, 'Reshiram', '643.png', 'Vast White Pokémon', 16, 10, 283, NULL, NULL, 'According to myth, if people ignore truth and let themselves become consumed by greed, Reshiram will arrive to burn their kingdoms down.'),
(644, NULL, 'Zekrom', '644.png', 'Deep Black Pokémon', 16, 13, 270, NULL, NULL, 'Mythology tells us that if people lose the righteousness in their hearts, their kingdoms will be razed by Zekrom''s lightning.'),
(645, NULL, 'Landorus', '645.png', 'Abundance Pokémon', 5, 3, 205, NULL, 220, 'From the forces of lightning and wind, it creates energy to give nutrients to the soil and make the land abundant.'),
(646, NULL, 'Kyurem', '646.png', 'Boundary Pokémon', 16, 15, 178, NULL, NULL, 'It appears that this Pokémon uses its powers over ice to freeze its own body in order to stabilize its cellular structure.'),
(647, NULL, 'Keldeo', '647.png', 'Colt Pokémon', 11, 2, 118, NULL, NULL, 'When it is resolute, its body fills with power and it becomes swifter. Its jumps are then too fast to follow.'),
(648, NULL, 'Meloetta', '648.png', 'Melody Pokémon', 1, 14, 215, NULL, NULL, 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.'),
(649, NULL, 'Genesect', '649.png', 'Paleozoic Pokémon', 7, 9, 53, NULL, NULL, 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.'),
(650, NULL, 'Chespin', '650.png', 'Spiny Nut Pokémon', 12, NULL, 161, NULL, 24, 'Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldn''t faze it.'),
(651, NULL, 'Quilladin', '651.png', 'Spiny Armor Pokémon', 12, NULL, 161, NULL, 24, 'They strengthen their lower bodies by running into one another. They are very kind and won''t start fights.'),
(652, NULL, 'Chesnaught', '652.png', 'Spiny Armor Pokémon', 12, 2, 161, NULL, 24, 'When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.'),
(653, NULL, 'Fennekin', '653.png', 'Fox Pokémon', 10, NULL, 23, NULL, 133, 'As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.'),
(654, NULL, 'Braixen', '654.png', 'Fox Pokémon', 10, NULL, 23, NULL, 133, 'When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.'),
(655, NULL, 'Delphox', '655.png', 'Fox Pokémon', 10, 14, 23, NULL, 133, 'Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.'),
(656, NULL, 'Froakie', '656.png', 'Bubble Frog Pokémon', 11, NULL, 274, NULL, 182, 'It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.'),
(657, NULL, 'Frogadier', '657.png', 'Bubble Frog Pokémon', 11, NULL, 274, NULL, 182, 'Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute''s time.'),
(658, NULL, 'Greninja', '658.png', 'Ninja Pokémon', 11, 17, 274, NULL, 182, 'It appears and vanishes with a ninja''s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.'),
(659, NULL, 'Bunnelby', '659.png', 'Digging Pokémon', 1, NULL, 167, 25, 98, 'It excels at digging holes. Using its ears, it can dig a nest 33 feet deep in one night.'),
(660, NULL, 'Diggersby', '660.png', 'Digging Pokémon', 1, 5, 167, 25, 98, 'The fur on its belly retains heat exceptionally well. People used to make heavy winter clothing from fur shed by this Pokémon.'),
(661, NULL, 'Fletchling', '661.png', 'Tiny Robin Pokémon', 1, 3, 22, NULL, 79, 'This Pokémon is normally calm, but once it enters battle, its hormonal balance changes and it becomes aggressive.'),
(662, NULL, 'Fletchinder', '662.png', 'Ember Pokémon', 10, 3, 67, NULL, 79, 'Its territory has a radius of just over a mile. If any bird Pokémon should enter, it will show them no mercy.'),
(663, NULL, 'Talonflame', '663.png', 'Scorching Pokémon', 10, 3, 67, NULL, 79, 'When it gets excited, it vents sparks from the gaps between its feathers. These unburnable feathers are used as a fireproof material.'),
(664, NULL, 'Scatterbug', '664.png', 'Scatterdust Pokémon', 7, NULL, 222, 34, 75, 'This Pokémon scatters poisonous powder to repel enemies. It will eat different plants depending on where it lives.'),
(665, NULL, 'Spewpa', '665.png', 'Scatterdust Pokémon', 7, NULL, 219, NULL, 75, 'Spewpa doesn''t live in a fixed location. It roams where it pleases across the fields and mountains, building up the energy it needs to evolve.'),
(666, NULL, 'Vivillon', '666.png', 'Scale Pokémon', 7, 3, 222, 34, 75, 'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.'),
(667, NULL, 'Litleo', '667.png', 'Lion Cub Pokémon', 10, 1, 199, 286, 147, 'When Litleo are young, female Pyroar will teach them how to hunt. Once the Litleo mature, they will leave the pride and set out on their own.'),
(668, NULL, 'Pyroar', '668.png', 'Royal Pokémon', 10, 1, 199, 286, 147, 'With fiery breath of more than 10,000 degrees Fahrenheit, they viciously threaten any challenger. The females protect the pride''s cubs.'),
(669, NULL, 'Flabébé', '669.png', 'Single Bloom Pokémon', 18, NULL, 71, NULL, 260, 'It''s not safe without the power of a flower, but it will keep traveling around until it finds one with the color and shape it wants.'),
(670, NULL, 'Floette', '670.png', 'Single Bloom Pokémon', 18, NULL, 71, NULL, 260, 'It gives its own power to flowers, pouring its heart into caring for them. Floette never forgives anyone who messes up a flower bed.'),
(671, NULL, 'Florges', '671.png', 'Garden Pokémon', 18, NULL, 71, NULL, 260, 'Its life can span several hundred years. It''s said to devote its entire life to protecting gardens.'),
(672, NULL, 'Skiddo', '672.png', 'Mount Pokémon', 12, NULL, 210, NULL, 85, 'As long as it has sunlight and water, Skiddo can make energy with the leaves on its body, allowing it to live on rocky mountains barren of food.'),
(673, NULL, 'Gogoat', '673.png', 'Mount Pokémon', 12, NULL, 210, NULL, 85, 'It can sense the feelings of others by touching them with its horns. This species has assisted people with their work since 5,000 years ago.'),
(674, NULL, 'Pancham', '674.png', 'Playful Pokémon', 2, NULL, 117, 144, 212, 'Wanting to make sure it''s taken seriously, Pancham''s always giving others a glare. But if it''s not focusing, it ends up smiling.'),
(675, NULL, 'Pangoro', '675.png', 'Daunting Pokémon', 2, 17, 117, 144, 212, 'Using its leaf, Pangoro can predict the moves of its opponents. It strikes with punches that can turn a dump truck into scrap with just one hit.'),
(676, NULL, 'Furfrou', '676.png', 'Poodle Pokémon', 1, NULL, 78, NULL, NULL, 'There was an era when aristocrats would compete to see who could trim their Furfrou''s fur into the most exquisite style.'),
(677, NULL, 'Espurr', '677.png', 'Restraint Pokémon', 14, NULL, 119, 110, 162, 'There''s enough psychic power in Espurr to send a wrestler flying, but because this power can''t be controlled, Espurr finds it troublesome.'),
(678, NULL, 'Meowstic', '678.png', 'Constraint Pokémon', 14, NULL, 119, 110, 177, 'The eyeball patterns on the interior of its ears emit psychic energy. It keeps the patterns tightly covered because that power is too immense.'),
(679, NULL, 'Honedge', '679.png', 'Sword Pokémon', 9, 8, 155, NULL, NULL, 'The blue eye on the sword''s handguard is the true body of Honedge. With its old cloth, it drains people''s lives away.'),
(680, NULL, 'Doublade', '680.png', 'Sword Pokémon', 9, 8, 155, NULL, NULL, 'The two swords employ a strategy of rapidly alternating between offense and defense to bring down their prey.'),
(681, NULL, 'Aegislash', '681.png', 'Royal Sword Pokémon', 9, 8, 240, NULL, NULL, 'Apparently, it can detect the innate qualities of leadership. According to legend, whoever it recognizes is destined to become king.'),
(682, NULL, 'Spritzee', '682.png', 'Perfume Pokémon', 18, NULL, 93, NULL, 11, 'The scent its body gives off enraptures those who smell it. Noble ladies had no shortage of love for Spritzee.'),
(683, NULL, 'Aromatisse', '683.png', 'Fragrance Pokémon', 18, NULL, 93, NULL, 11, 'The scents Aromatisse can produce range from sweet smells that bolster allies to foul smells that sap an opponent''s will to fight.'),
(684, NULL, 'Swirlix', '684.png', 'Cotton Candy Pokémon', 18, NULL, 257, NULL, 285, 'The sweet smell of cotton candy perfumes Swirlix''s fluffy fur. This Pokémon spits out sticky string to tangle up its enemies.'),
(685, NULL, 'Slurpuff', '685.png', 'Meringue Pokémon', 18, NULL, 257, NULL, 285, 'Slurpuff''s fur contains a lot of air, making it soft to the touch and lighter than it looks.'),
(686, NULL, 'Inkay', '686.png', 'Revolving Pokémon', 17, 14, 35, 251, 110, 'By exposing foes to the blinking of its luminescent spots, Inkay demoralizes them, and then it seizes the chance to flee.'),
(687, NULL, 'Malamar', '687.png', 'Overturning Pokémon', 17, 14, 35, 251, 110, 'Gazing at its luminescent spots will quickly induce a hypnotic state, putting the observer under Malamar''s control.'),
(688, NULL, 'Binacle', '688.png', 'Two-Handed Pokémon', 6, 11, 275, 228, 166, 'After two Binacle find a suitably sized rock, they adhere themselves to it and live together. They cooperate to gather food during high tide.'),
(689, NULL, 'Barbaracle', '689.png', 'Collective Pokémon', 6, 11, 275, 228, 166, 'Having an eye on each palm allows it to keep watch in all directions. In a pinch, its limbs start to act on their own to ensure the enemy''s defeat.'),
(690, NULL, 'Skrelp', '690.png', 'Mock Kelp Pokémon', 4, 11, 171, 173, 1, 'This Pokémon is a poor swimmer. If it''s caught in a fierce storm, it will sometimes get washed far away and become unable to return to its home.'),
(691, NULL, 'Dragalge', '691.png', 'Mock Kelp Pokémon', 4, 16, 171, 173, 1, 'Using a liquid poison, Dragalge indiscriminately attacks anything that wanders into its territory. This poison can corrode the undersides of boats.'),
(692, NULL, 'Clauncher', '692.png', 'Water Gun Pokémon', 11, NULL, 137, NULL, NULL, 'Clauncher''s claws will regrow if they fall off. The meat inside the claws is edible, but it has a distinct flavor that doesn''t appeal to all tastes.'),
(693, NULL, 'Clawitzer', '693.png', 'Howitzer Pokémon', 11, NULL, 137, NULL, NULL, 'The cannonballs of seawater that Clawitzer launches from its claw are powerful enough to punch through tanker hulls.'),
(694, NULL, 'Helioptile', '694.png', 'Generator Pokémon', 13, 1, 57, 209, 231, 'When spread, the frills on its head act like solar panels, generating the power behind this Pokémon''s electric moves.'),
(695, NULL, 'Heliolisk', '695.png', 'Generator Pokémon', 13, 1, 57, 209, 231, 'One Heliolisk basking in the sun with its frill outspread is all it would take to produce enough electricity to power a city.'),
(696, NULL, 'Tyrunt', '696.png', 'Royal Heir Pokémon', 6, 16, 249, NULL, 250, 'This Pokémon is selfish and likes to be pampered. It can also inflict grievous wounds on its Trainer just by playing around.'),
(697, NULL, 'Tyrantrum', '697.png', 'Despot Pokémon', 6, 16, 249, NULL, 250, 'A single bite of Tyrantrum''s massive jaws will demolish a car. This Pokémon was the king of the ancient world.'),
(698, NULL, 'Amaura', '698.png', 'Tundra Pokémon', 6, 15, 196, NULL, 230, 'Amaura is an ancient Pokémon that has gone extinct. Specimens of this species can sometimes be found frozen in ice.'),
(699, NULL, 'Aurorus', '699.png', 'Tundra Pokémon', 6, 15, 196, NULL, 230, 'Aurorus was restored from a fossil. It''s said that when this Pokémon howls, auroras appear in the night sky.'),
(700, NULL, 'Sylveon', '700.png', 'Intertwining Pokémon', 18, NULL, 42, NULL, 168, 'Sylveon cuts an elegant figure as it dances lightly around, feelers fluttering, but its piercing moves aim straight for its opponents'' weak spots.'),
(701, NULL, 'Hawlucha', '701.png', 'Wrestling Pokémon', 2, 3, 126, 285, 144, 'Hawlucha live quietly without flocking together. They fight constantly with their natural enemies: noisy groups of Primeape.'),
(702, NULL, 'Dedenne', '702.png', 'Antenna Pokémon', 13, 18, 25, 167, 169, 'Dedenne emit electrical waves from the whiskers on their cheeks to communicate with each other. When low on electricity, they curl up and sleep.'),
(703, NULL, 'Carbink', '703.png', 'Jewel Pokémon', 6, 18, 28, NULL, 250, 'It''s said that somewhere in the world, there''s a mineral vein housing a large pack of slumbering Carbink. It''s also said that this pack has a queen.'),
(704, NULL, 'Goomy', '704.png', 'Soft Tissue Pokémon', 16, NULL, 210, 101, 83, 'Goomy''s horns are excellent sensory organs that cover all five of Goomy''s senses. Goomy picks up on danger from the movement of the air.'),
(705, NULL, 'Sliggoo', '705.png', 'Soft Tissue Pokémon', 16, NULL, 210, 101, 83, 'When Sliggoo senses danger, the mucus coating its entire body becomes more concentrated—it''ll dissolve anything.'),
(705, 3, 'Sliggoo', '705-hisui.png', 'Soft Tissue Pokémon', 9, 16, 210, 221, 83, 'A creature given to melancholy. I suspect its metallic shell developed as a result of the mucus on its skin reacting with the iron in Hisui''s water.'),
(706, NULL, 'Goodra', '706.png', 'Dragon Pokémon', 16, NULL, 210, 101, 83, 'This Pokémon is uncontrollable when enraged. It rampages on and on, lashing its tail with enough power to send a dump truck flying.'),
(706, 3, 'Goodra', '706-hisui.png', 'Shell Bunker Pokémon', 9, 16, 210, 221, 83, 'Able to freely control the hardness of its metallic shell. It loathes solitude and is extremely clingy—it will fume and run riot if those dearest to it ever leave its side.'),
(707, NULL, 'Klefki', '707.png', 'Key Ring Pokémon', 9, 18, 177, NULL, 133, 'In the past, noble families entrusted their vault keys to a Klefki. They passed the Klefki down through the generations, taking good care of it.'),
(708, NULL, 'Phantump', '708.png', 'Stump Pokémon', 8, 12, 152, 76, 92, 'With a voice like a human child''s, it cries out to lure adults deep into the forest, getting them lost among the trees.'),
(709, NULL, 'Trevenant', '709.png', 'Elder Tree Pokémon', 8, 12, 152, 76, 92, 'Small roots that extend from the tips of this Pokémon''s feet can tie into the trees of the forest and give Trevenant control over them.'),
(710, NULL, 'Pumpkaboo', '710.png', 'Pumpkin Pokémon', 8, 12, 167, 76, 113, 'The pumpkin body is inhabited by a spirit trapped in this world. As the sun sets, it becomes restless and active.'),
(711, NULL, 'Gourgeist', '711.png', 'Pumpkin Pokémon', 8, 12, 167, 76, 113, 'Singing in eerie voices, they wander town streets on the night of the new moon. Anyone who hears their song is cursed.'),
(712, NULL, 'Bergmite', '712.png', 'Ice Chunk Pokémon', 15, NULL, 162, 103, 250, 'Bergmite protects itself by coating its body in ice formed by frigid air of -148 degrees Fahrenheit. It fights with Frigibax whenever they meet.'),
(713, NULL, 'Avalugg', '713.png', 'Iceberg Pokémon', 15, NULL, 162, 103, 250, 'This Pokémon uses its massive icy body to flatten anything that gets in its way. When it''s floating out on the ocean, it looks exactly like drift ice.'),
(713, 3, 'Avalugg', '713-hisui.png', 'Iceberg Pokémon', 15, 6, 249, 103, 250, 'The armor of ice covering its lower jaw puts steel to shame and can shatter rocks with ease. This Pokémon barrels along steep mountain paths, cleaving through the deep snow.'),
(714, NULL, 'Noibat', '714.png', 'Sound Wave Pokémon', 3, 16, 76, 110, 266, 'Noibat can change the frequency of its sound waves at will, and it generates ultrasonic waves of up to 200,000 hertz.'),
(715, NULL, 'Noivern', '715.png', 'Sound Wave Pokémon', 3, 16, 76, 110, 266, 'In the dark, even Hydreigon are terrified of this Pokémon. But in the light, Noivern is the one that avoids battle.'),
(716, NULL, 'Xerneas', '716.png', 'Life Pokémon', 18, NULL, 65, NULL, NULL, 'When the horns on its head shine in seven colors, it is said to be sharing everlasting life.'),
(717, NULL, 'Yveltal', '717.png', 'Destruction Pokémon', 17, 3, 45, NULL, NULL, 'When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon once more.'),
(718, NULL, 'Zygarde', '718.png', 'Order Pokémon', 16, 5, 13, NULL, 174, 'This is Zygarde''s form when about half of its pieces have been assembled. It plays the role of monitoring the ecosystem.'),
(719, NULL, 'Diancie', '719.png', 'Jewel Pokémon', 6, 18, 28, NULL, NULL, 'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.'),
(720, NULL, 'Hoopa', '720.png', 'Mischief Pokémon', 14, 8, 133, NULL, NULL, 'It is said to be able to seize anything it desires with its six rings and six huge arms. With its power sealed, it is transformed into a much smaller form.'),
(721, NULL, 'Volcanion', '721.png', 'Steam Pokémon', 10, 11, 293, NULL, NULL, 'It lets out billows of steam and disappears into the dense fog. It''s said to live in mountains where humans do not tread.'),
(722, NULL, 'Rowlet', '722.png', 'Grass Quill Pokémon', 12, 3, 161, NULL, 130, 'During the day, it builds up energy via photosynthesis. At night, it flies silently through the sky, on the prowl for prey.'),
(723, NULL, 'Dartrix', '723.png', 'Blade Quill Pokémon', 12, 3, 161, NULL, 130, 'It never slacks when it comes to the task of cleaning its feathers. Thorough preening keeps it looking spiffy and its blade quills nice and sharp.'),
(724, NULL, 'Decidueye', '724.png', 'Arrow Quill Pokémon', 12, 8, 161, NULL, 130, 'In a tenth of a second, it can nock and fire an arrow quill, piercing an opponent''s weak point before they notice what''s happening.'),
(724, 3, 'Decidueye', '724-hisui.png', 'Arrow Quill Pokémon', 12, 2, 161, NULL, 212, 'The air stored inside the rachises of Decidueye''s feathers insulates the Pokémon against Hisui''s extreme cold. This is firm proof that evolution can be influenced by environment.'),
(725, NULL, 'Litten', '725.png', 'Fire Cat Pokémon', 10, NULL, 23, NULL, 114, 'Trying to pet Litten before it trusts you will result in a nasty scratch from its sharp claws. Be careful.'),
(726, NULL, 'Torracat', '726.png', 'Fire Cat Pokémon', 10, NULL, 23, NULL, 114, 'When facing a powerful enemy, Torracat''s fighting spirit gets pumped up, and its fire bell blazes hotter.'),
(727, NULL, 'Incineroar', '727.png', 'Heel Pokémon', 10, 17, 23, NULL, 114, 'Incineroar''s rough and aggressive behavior is its most notable trait, but the way it helps out small Pokémon shows that it has a kind side as well.'),
(728, NULL, 'Popplio', '728.png', 'Sea Lion Pokémon', 11, NULL, 274, NULL, 129, 'If Popplio want to create big, powerful balloons, they must be persistent. It takes daily practice for these Pokémon to develop their skills.'),
(729, NULL, 'Brionne', '729.png', 'Pop Star Pokémon', 11, NULL, 274, NULL, 129, 'On nights when the sea is calm, Brionne dance with one another to the singing of the Primarina that''s leading them.'),
(730, NULL, 'Primarina', '730.png', 'Soloist Pokémon', 11, 18, 274, NULL, 129, 'For Primarina, every battle''s a stage. Its singing and the dancing of its balloons will mesmerize the audience.'),
(731, NULL, 'Pikipek', '731.png', 'Woodpecker Pokémon', 1, 3, 119, 225, 167, 'It may look spindly, but its neck muscles are heavy-duty. It can peck at a tree 16 times per second!'),
(732, NULL, 'Trumbeak', '732.png', 'Bugle Beak Pokémon', 1, 3, 119, 225, 167, 'From its mouth, it fires the seeds of berries it has eaten. The scattered seeds give rise to new plants.'),
(733, NULL, 'Toucannon', '733.png', 'Cannon Pokémon', 1, 3, 119, 225, 220, 'Known for forming harmonious couples, this Pokémon is brought to wedding ceremonies as a good luck charm.'),
(734, NULL, 'Yungoos', '734.png', 'Loitering Pokémon', 1, NULL, 236, 249, 1, 'It spends its waking hours searching endlessly for food. When Yungoos is hungry, its ferocity gains a certain edge.'),
(735, NULL, 'Gumshoos', '735.png', 'Stakeout Pokémon', 1, NULL, 236, 249, 1, 'Gumshoos specializes in relentlessly tracking down prey. The simple-minded Skwovet doesn''t seem to provide Gumshoos enough challenge.'),
(736, NULL, 'Grubbin', '736.png', 'Larva Pokémon', 7, NULL, 256, NULL, NULL, 'Its natural enemies, like Rookidee, may flee rather than risk getting caught in its large mandibles that can snap thick tree branches.'),
(737, NULL, 'Charjabug', '737.png', 'Battery Pokémon', 7, 13, 16, NULL, NULL, 'Its digestive processes convert the leaves it eats into electricity. An electric sac in its belly stores the electricity for later use.'),
(738, NULL, 'Vikavolt', '738.png', 'Stag Beetle Pokémon', 7, 13, 122, NULL, NULL, 'If it carries a Charjabug to use as a spare battery, a flying Vikavolt can rapidly fire high-powered beams of electricity.'),
(739, NULL, 'Crabrawler', '739.png', 'Boxing Pokémon', 2, NULL, 102, 117, 6, 'If it loses its pincers, they''ll quickly regrow. The pincers are popular ingredients in paella since their shells produce a tasty soup stock.'),
(740, NULL, 'Crabominable', '740.png', 'Woolly Crab Pokémon', 2, 15, 102, 117, 6, 'Though its punches are powerful, this Pokémon''s movements are sluggish. It blows icy bubbles from its mouth to immobilize its opponents.'),
(741, NULL, 'Oricorio', '741.png', 'Dancing Pokémon', 10, 3, 44, NULL, NULL, 'This form of Oricorio has sipped red nectar. It whips up blazing flames as it moves to the steps of its passionate dance.'),
(742, NULL, 'Cutiefly', '742.png', 'Bee Fly Pokémon', 7, 18, 96, 222, 257, 'An opponent''s aura can tell Cutiefly what that opponent''s next move will be. Then Cutiefly can glide around the attack and strike back.'),
(743, NULL, 'Ribombee', '743.png', 'Bee Fly Pokémon', 7, 18, 96, 222, 257, 'Ribombee absolutely hate getting wet or rained on. In the cloudy Galar region, they are very seldom seen.'),
(744, NULL, 'Rockruff', '744.png', 'Puppy Pokémon', 6, NULL, 119, 290, 162, 'This Pokémon travels in a pack with others until it grows up. When its mood turns sour, it starts striking the ground with the rocks on its neck.'),
(745, NULL, 'Lycanroc', '745.png', 'Wolf Pokémon', 6, NULL, 119, 206, 242, 'It has a calm and collected demeanor. It swiftly closes in on its prey, then slices them with the rocks in its mane.'),
(746, NULL, 'Wishiwashi', '746.png', 'Small Fry Pokémon', 11, NULL, 211, NULL, NULL, 'When it senses danger, its eyes tear up. The sparkle of its tears signals other Wishiwashi to gather.'),
(747, NULL, 'Mareanie', '747.png', 'Brutal Star Pokémon', 4, 11, 138, 126, 197, 'It has excellent regenerative capabilities. Legs that a Mareanie has lost have a very bitter, astringent flavor—they''re not suitable as food.'),
(748, NULL, 'Toxapex', '748.png', 'Brutal Star Pokémon', 4, 11, 138, 126, 197, 'This Pokémon lives within a dome made by its own legs. Toxapex monitors its surroundings by sensing the flow of the tide through its spikes.'),
(749, NULL, 'Mudbray', '749.png', 'Donkey Pokémon', 5, NULL, 162, 239, 112, 'Though a slow walker, Mudbray is plenty strong. Its pace doesn''t change even when it''s loaded with 50 times its own body weight.'),
(750, NULL, 'Mudsdale', '750.png', 'Draft Horse Pokémon', 5, NULL, 162, 239, 112, 'This Pokémon has been treasured not just for its physical labor but also because it produces high-quality mud used for making pottery.'),
(751, NULL, 'Dewpider', '751.png', 'Water Bubble Pokémon', 11, 7, 294, NULL, 293, 'Dewpider normally lives underwater. When it comes onto land in search of food, it takes water with it in the form of a bubble on its head.'),
(752, NULL, 'Araquanid', '752.png', 'Water Bubble Pokémon', 11, 7, 294, NULL, 293, 'It launches water bubbles with its legs, drowning prey within the bubbles. This Pokémon can then take its time to savor its meal.'),
(753, NULL, 'Fomantis', '753.png', 'Sickle Grass Pokémon', 12, NULL, 121, NULL, 35, 'Many Trainers give their Fomantis their own flowerpots so they can sunbathe in peace and quiet.'),
(754, NULL, 'Lurantis', '754.png', 'Bloom Sickle Pokémon', 12, NULL, 121, NULL, 35, 'A lot of time and effort is required to maintain the vivid colors of its petals. This Pokémon puts its Trainer''s attentiveness to the test.'),
(755, NULL, 'Morelull', '755.png', 'Illuminating Pokémon', 12, 18, 106, 60, 192, 'Morelull live in forests that stay dark even during the day. They scatter flickering spores that put enemies to sleep.'),
(756, NULL, 'Shiinotic', '756.png', 'Illuminating Pokémon', 12, 18, 106, 60, 192, 'Its flickering spores lure in prey and put them to sleep. Once this Pokémon has its prey snoozing, it drains their vitality with its fingertips.'),
(757, NULL, 'Salandit', '757.png', 'Toxic Lizard Pokémon', 4, 10, 36, NULL, 157, 'Only female Salandit can produce gas laden with pheromones. Males entranced by this gas will do whatever the females tell them.'),
(758, NULL, 'Salazzle', '758.png', 'Toxic Lizard Pokémon', 4, 10, 36, NULL, 157, 'Salazzle makes its opponents light-headed with poisonous gas, then captivates them with alluring movements to turn them into loyal servants.'),
(759, NULL, 'Stufful', '759.png', 'Flailing Pokémon', 1, 2, 72, 120, 42, 'The way it protects itself by flailing its arms may be an adorable sight, but stay well away. This is flailing that can snap thick tree trunks.'),
(760, NULL, 'Bewear', '760.png', 'Strong Arm Pokémon', 1, 2, 72, 120, 42, 'Once it accepts you as a friend, it tries to show its affection with a hug. Letting it do that is dangerous—it could easily shatter your bones.'),
(761, NULL, 'Bounsweet', '761.png', 'Fruit Pokémon', 12, NULL, 121, 157, 257, 'A Greedent drawn in by the sweet scent of these Pokémon will tuck the Bounsweet in among the berries in its tail and carry them all away.'),
(762, NULL, 'Steenee', '762.png', 'Fruit Pokémon', 12, NULL, 121, 157, 257, 'Steenee bounces energetically through forests. If the rind that peels off its body is pulverized, it can be used to treat stomach pains.'),
(763, NULL, 'Tsareena', '763.png', 'Fruit Pokémon', 12, NULL, 121, 189, 257, 'This Pokémon launches fierce yet elegant kicks with its long, slender legs. It views Quaquaval as its rival.'),
(764, NULL, 'Comfey', '764.png', 'Posy Picker Pokémon', 18, NULL, 71, 281, 152, 'These Pokémon smell very nice. All Comfey wear different flowers, so each of these Pokémon has its own individual scent.'),
(765, NULL, 'Oranguru', '765.png', 'Sage Pokémon', 1, 14, 112, 266, 260, 'This Pokémon lives quietly in the depths of the forest. The purple, cape-like fur gets longer and longer as Oranguru ages.'),
(766, NULL, 'Passimian', '766.png', 'Teamwork Pokémon', 2, NULL, 194, NULL, 49, 'The boss chooses 10 members of the group to go out hunting. The hunting party will evenly split the food they find with the rest of the group.'),
(767, NULL, 'Wimpod', '767.png', 'Turn Tail Pokémon', 7, 11, 300, NULL, NULL, 'It''s nature''s cleaner—it eats anything and everything, including garbage and rotten things. The ground near its nest is always clean.'),
(768, NULL, 'Golisopod', '768.png', 'Hard Scale Pokémon', 7, 11, 64, NULL, NULL, 'They live in sunken ships or in holes in the seabed. When Golisopod and Grapploct battle, the loser becomes the winner''s meal.'),
(769, NULL, 'Sandygast', '769.png', 'Sand Heap Pokémon', 8, 5, 295, NULL, 209, 'It flings sand into the eyes of its prey and tries to close in on them while they''re blinded, but since Sandygast is so slow, the prey tends to escape.'),
(770, NULL, 'Palossand', '770.png', 'Sand Castle Pokémon', 8, 5, 295, NULL, 209, 'The terrifying Palossand drags smaller Pokémon into its sandy body. Once its victims are trapped, it drains them of their vitality whenever it pleases.'),
(771, NULL, 'Pyukumuku', '771.png', 'Sea Cucumber Pokémon', 11, NULL, 111, NULL, 284, 'It''s covered in a slime that keeps its skin moist, allowing it to stay on land for days without drying up.'),
(772, NULL, 'Type: Null', '772.png', 'Synthetic Pokémon', 1, NULL, 17, NULL, NULL, 'It was modeled after a mighty Pokémon of myth. The mask placed upon it limits its power in order to keep it under control.'),
(773, NULL, 'Silvally', '773.png', 'Synthetic Pokémon', 1, NULL, 200, NULL, NULL, 'A solid bond of trust between this Pokémon and its Trainer awakened the strength hidden within Silvally. It can change its type at will.'),
(774, NULL, 'Minior', '774.png', 'Meteor Pokémon', 6, 3, 223, NULL, NULL, 'It lives in the ozone layer, where it becomes food for stronger Pokémon. When it tries to run away, it falls to the ground.'),
(775, NULL, 'Komala', '775.png', 'Drowsing Pokémon', 1, NULL, 31, NULL, NULL, 'A potent anesthetic can be made by diluting Komala''s drool. This anesthetic was used for surgeries in the past.'),
(776, NULL, 'Turtonator', '776.png', 'Blast Turtle Pokémon', 10, 16, 221, NULL, NULL, 'Eating sulfur in its volcanic habitat is what causes explosive compounds to develop in its shell. Its droppings are also dangerously explosive.'),
(777, NULL, 'Togedemaru', '777.png', 'Roly-Poly Pokémon', 13, 9, 116, 125, 250, 'When it''s in trouble, it curls up into a ball, makes its fur spikes stand on end, and then discharges electricity indiscriminately.'),
(778, NULL, 'Mimikyu', '778.png', 'Disguise Pokémon', 8, 18, 52, NULL, NULL, 'It has taken damage and can no longer hold the head of its cloth disguise upright. For as long as it lives, Mimikyu will never forget its attacker.'),
(779, NULL, 'Bruxish', '779.png', 'Gnash Teeth Pokémon', 11, 14, 47, 249, 304, 'When sunlight reflects on the ripples created by a Bruxish grinding its teeth, the water all around sparkles brilliantly.'),
(780, NULL, 'Drampa', '780.png', 'Placid Pokémon', 1, 16, 21, 210, 29, 'Drampa is a kind and friendly Pokémon—up until it''s angered. When that happens, it stirs up a gale and flattens everything around.'),
(781, NULL, 'Dhelmise', '781.png', 'Sea Creeper Pokémon', 8, 12, 244, NULL, NULL, 'After a piece of seaweed merged with debris from a sunken ship, it was reborn as this ghost Pokémon.'),
(782, NULL, 'Jangmo-o', '782.png', 'Scaly Pokémon', 16, NULL, 24, 234, 160, 'Jangmo-o strikes its scales to communicate with others of its kind. Its scales are actually fur that''s become as hard as metal.'),
(783, NULL, 'Hakamo-o', '783.png', 'Scaly Pokémon', 16, 2, 24, 234, 160, 'Before attacking its enemies, it clashes its scales together and roars. Its sharp claws shred the opposition.'),
(784, NULL, 'Kommo-o', '784.png', 'Scaly Pokémon', 16, 2, 24, 234, 160, 'It clatters its tail scales to unnerve opponents. This Pokémon will battle only those who stand steadfast in the face of this display.'),
(785, NULL, 'Tapu Koko', '785.png', 'Land Spirit Pokémon', 13, 18, 61, NULL, 266, 'The lightning-wielding guardian deity of Melemele, Tapu Koko is brimming with curiosity and appears before people from time to time.'),
(786, NULL, 'Tapu Lele', '786.png', 'Land Spirit Pokémon', 14, 18, 184, NULL, 266, 'Although called a guardian deity, Tapu Lele is devoid of guilt about its cruel disposition and can be described as nature incarnate.'),
(787, NULL, 'Tapu Bulu', '787.png', 'Land Spirit Pokémon', 12, 18, 86, NULL, 266, 'It makes ringing sounds with its tail to let others know where it is, avoiding unneeded conflicts. This guardian deity of Ula''ula controls plants.'),
(788, NULL, 'Tapu Fini', '788.png', 'Land Spirit Pokémon', 11, 18, 143, NULL, 266, 'Although it''s called a guardian deity, terrible calamities sometimes befall those who recklessly approach Tapu Fini.'),
(789, NULL, 'Cosmog', '789.png', 'Nebula Pokémon', 14, NULL, 284, NULL, NULL, 'Cosmog is very curious but not very cautious, often placing itself in danger. If things start to look dicey, it teleports away.'),
(790, NULL, 'Cosmoem', '790.png', 'Protostar Pokémon', 14, NULL, 250, NULL, NULL, 'It sucks in dust from the air at an astounding rate, frantically building up energy within its core as preparation for evolution.'),
(791, NULL, 'Solgaleo', '791.png', 'Sunne Pokémon', 14, 9, 77, NULL, NULL, 'Solgaleo was once known as the Beast That Devours the Sun. Energy in the form of light radiates boundlessly from it.'),
(792, NULL, 'Lunala', '792.png', 'Moone Pokémon', 14, 8, 216, NULL, NULL, 'Known as the Beast That Calls the Moon, this Pokémon lives by taking in any and all light and converting it into its own energy.'),
(793, NULL, 'Nihilego', '793.png', 'Parasite Pokémon', 6, 4, 20, NULL, NULL, 'It appeared in this world from an Ultra Wormhole. Nihilego appears to be a parasite that lives by feeding on people and Pokémon.'),
(794, NULL, 'Buzzwole', '794.png', 'Swollen Pokémon', 7, 2, 20, NULL, NULL, 'Buzzwole goes around showing off its abnormally swollen muscles. It is one kind of Ultra Beast.'),
(795, NULL, 'Pheromosa', '795.png', 'Lissome Pokémon', 7, 2, 20, NULL, NULL, 'Although it''s alien to this world and a danger here, it''s apparently a common organism in the world where it normally lives.'),
(796, NULL, 'Xurkitree', '796.png', 'Glowing Pokémon', 13, NULL, 20, NULL, NULL, 'They''ve been dubbed Ultra Beasts. Some of them stand unmoving, like trees, with their arms and legs stuck into the ground.'),
(797, NULL, 'Celesteela', '797.png', 'Launch Pokémon', 9, 3, 20, NULL, NULL, 'Although it''s alien to this world and a danger here, it''s apparently a common organism in the world where it normally lives.'),
(798, NULL, 'Kartana', '798.png', 'Drawn Sword Pokémon', 12, 9, 20, NULL, NULL, 'Although it''s alien to this world and a danger here, it''s apparently a common organism in the world where it normally lives.'),
(799, NULL, 'Guzzlord', '799.png', 'Junkivore Pokémon', 17, 16, 20, NULL, NULL, 'An unknown life-form called a UB. It may be constantly hungry—it is certainly always devouring something.'),
(800, NULL, 'Necrozma', '800.png', 'Prism Pokémon', 14, NULL, 180, NULL, NULL, 'It needs light to survive, and it goes on a rampage seeking it out. Its laser beams will cut anything to pieces.'),
(801, NULL, 'Magearna', '801.png', 'Artificial Pokémon', 9, 18, 233, NULL, NULL, 'Built roughly 500 years ago by a scientist, the part called the Soul-Heart is the actual life-form.'),
(802, NULL, 'Marshadow', '802.png', 'Gloomdweller Pokémon', 2, 8, 265, NULL, NULL, 'By slipping into the shadow of a martial arts master and copying their movements, this Pokémon learned the ultimate techniques.'),
(803, NULL, 'Poipole', '803.png', 'Poison Pin Pokémon', 4, NULL, 20, NULL, NULL, 'An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head.'),
(804, NULL, 'Naganadel', '804.png', 'Poison Pin Pokémon', 4, 16, 20, NULL, NULL, 'One kind of Ultra Beast, it fires a glowing, venomous liquid from its needles. This liquid is also immensely adhesive.'),
(805, NULL, 'Stakataka', '805.png', 'Rampart Pokémon', 6, 9, 20, NULL, NULL, 'When stone walls started moving and attacking, the brute''s true identity was this mysterious life-form, which brings to mind an Ultra Beast.'),
(806, NULL, 'Blacephalon', '806.png', 'Fireworks Pokémon', 10, 8, 20, NULL, NULL, 'A UB that appeared from an Ultra Wormhole, it causes explosions, then takes advantage of opponents'' surprise to rob them of their vitality.'),
(807, NULL, 'Zeraora', '807.png', 'Thunderclap Pokémon', 13, NULL, 291, NULL, NULL, 'Electricity sparks from the pads on its limbs. Wherever Zeraora runs, lightning flashes and thunder echoes.'),
(808, NULL, 'Meltan', '808.png', 'Hex Nut Pokémon', 9, NULL, 135, NULL, NULL, 'They live as a group, but when the time comes, one strong Meltan will absorb all the others and evolve.'),
(809, NULL, 'Melmetal', '809.png', 'Hex Nut Pokémon', 9, NULL, 117, NULL, NULL, 'Centrifugal force is behind the punches of Melmetal''s heavy hex-nut arms. Melmetal is said to deliver the strongest punches of all Pokémon.'),
(810, NULL, 'Grookey', '810.png', 'Chimp Pokémon', 12, NULL, 161, NULL, 86, 'When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.'),
(811, NULL, 'Thwackey', '811.png', 'Beat Pokémon', 12, NULL, 161, NULL, 86, 'When it''s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won''t even notice that it''s already knocked out its opponent.'),
(812, NULL, 'Rillaboom', '812.png', 'Drummer Pokémon', 12, NULL, 161, NULL, 86, 'The one with the best drumming techniques becomes the boss of the troop. It has a gentle disposition and values harmony among its group.'),
(813, NULL, 'Scorbunny', '813.png', 'Rabbit Pokémon', 10, NULL, 23, NULL, 123, 'A warm-up of running around gets fire energy coursing through this Pokémon''s body. Once that happens, it''s ready to fight at full power.'),
(814, NULL, 'Raboot', '814.png', 'Rabbit Pokémon', 10, NULL, 23, NULL, 123, 'It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork.'),
(815, NULL, 'Cinderace', '815.png', 'Striker Pokémon', 10, NULL, 23, NULL, 123, 'It''s skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.'),
(816, NULL, 'Sobble', '816.png', 'Water Lizard Pokémon', 11, NULL, 274, NULL, 228, 'When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers won''t be able to resist weeping.'),
(817, NULL, 'Drizzile', '817.png', 'Water Lizard Pokémon', 11, NULL, 274, NULL, 228, 'A clever combatant, this Pokémon battles using water balloons created with moisture secreted from its palms.'),
(818, NULL, 'Inteleon', '818.png', 'Secret Agent Pokémon', 11, NULL, 274, NULL, 228, 'Its nictitating membranes let it pick out foes'' weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3.'),
(819, NULL, 'Skwovet', '819.png', 'Cheeky Pokémon', 1, NULL, 25, NULL, 81, 'No matter how much it stuffs its belly with food, it is always anxious about getting hungry again. So, it stashes berries in its cheeks and tail.'),
(820, NULL, 'Greedent', '820.png', 'Greedy Pokémon', 1, NULL, 25, NULL, 81, 'This Pokémon makes off with heaps of fallen berries by wrapping them in its tail, which is roughly twice the length of its body.'),
(821, NULL, 'Rookidee', '821.png', 'Tiny Bird Pokémon', 3, NULL, 119, 286, 22, 'The females are fussier than the males. If another creature dirties a female Rookidee''s wings, it''ll peck the offender relentlessly in a burning rage.'),
(822, NULL, 'Corvisquire', '822.png', 'Raven Pokémon', 3, NULL, 119, 286, 22, 'It''s said that the reason behind Corvisquire''s high level of intelligence is the large size of its brain relative to those of other bird Pokémon.'),
(823, NULL, 'Corviknight', '823.png', 'Raven Pokémon', 3, 9, 178, 286, 142, 'Although its wings have partly turned to steel and become heavy as a result, this Pokémon flies through the skies with ease.'),
(824, NULL, 'Blipbug', '824.png', 'Larva Pokémon', 7, NULL, 256, 34, 266, 'A constant collector of information, this Pokémon is very smart. Very strong is what it isn''t.'),
(825, NULL, 'Dottler', '825.png', 'Radome Pokémon', 7, 14, 256, 34, 266, 'It barely moves, but it''s still alive. Hiding in its shell without food or water seems to have awakened its psychic powers.'),
(826, NULL, 'Orbeetle', '826.png', 'Seven Spot Pokémon', 7, 14, 256, 76, 266, 'It''s famous for its high level of intelligence, and the large size of its brain is proof that it also possesses immense psychic power.'),
(827, NULL, 'Nickit', '827.png', 'Fox Pokémon', 17, NULL, 204, 285, 236, 'Cunning and cautious, this Pokémon survives by stealing food from others. It erases its tracks with swipes of its tail as it makes off with its plunder.'),
(828, NULL, 'Thievul', '828.png', 'Fox Pokémon', 17, NULL, 204, 285, 236, 'It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.'),
(829, NULL, 'Gossifleur', '829.png', 'Flowering Pokémon', 12, NULL, 38, 197, 60, 'It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.'),
(830, NULL, 'Eldegoss', '830.png', 'Cotton Bloom Pokémon', 12, NULL, 38, 197, 60, 'The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokémon can benefit from them.'),
(831, NULL, 'Wooloo', '831.png', 'Sheep Pokémon', 1, NULL, 72, 204, 24, 'If its fleece grows too long, Wooloo won''t be able to move. Cloth made with the wool of this Pokémon is surprisingly strong.'),
(832, NULL, 'Dubwool', '832.png', 'Sheep Pokémon', 1, NULL, 72, 204, 24, 'Weave a carpet from its springy wool, and you end up with something closer to a trampoline. You''ll start to bounce the moment you set foot on it.'),
(833, NULL, 'Chewtle', '833.png', 'Snapping Pokémon', 11, NULL, 249, 221, 258, 'Its large front tooth is still growing in. When the tooth itches, this Pokémon will bite another Chewtle''s horn, and the two Pokémon will tussle.'),
(834, NULL, 'Drednaw', '834.png', 'Bite Pokémon', 11, 6, 249, 221, 258, 'Drednaw lurks along the shoreline. When prey come to drink water, Drednaw stretches its neck out and chomps down on them.'),
(835, NULL, 'Yamper', '835.png', 'Puppy Pokémon', 13, NULL, 15, NULL, 193, 'This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity.'),
(836, NULL, 'Boltund', '836.png', 'Dog Pokémon', 13, NULL, 249, NULL, 33, 'This Pokémon generates electricity and channels it into its legs to keep them going strong. Boltund can run nonstop for three full days.'),
(837, NULL, 'Rolycoly', '837.png', 'Coal Pokémon', 6, NULL, 243, 67, 69, 'Chunks of the surface of this Pokémon''s body that have grown old and flaked off have long been used for fuel as an alternative to coal.'),
(838, NULL, 'Carkol', '838.png', 'Coal Pokémon', 6, 10, 243, 67, 69, 'Due to the coal tar created inside it, the heap of coal on Carkol''s back never falls apart, even when the Pokémon rolls around at high speeds.'),
(839, NULL, 'Coalossal', '839.png', 'Coal Pokémon', 6, 10, 243, 67, 69, 'To intimidate its opponents, Coalossal will vigorously shake its body, scattering coal from its smoldering back.'),
(840, NULL, 'Applin', '840.png', 'Apple Core Pokémon', 12, 16, 198, 81, 24, 'It grows by eating the flesh of an apple. Applin uses its own body fluid to strengthen the apple''s skin and prevent it from rotting.'),
(841, NULL, 'Flapple', '841.png', 'Apple Wing Pokémon', 12, 16, 198, 81, 100, 'It uses its own body fluid to repair its apple. Strong Flapple that have won many battles have apples that are clay colored all over.'),
(842, NULL, 'Appletun', '842.png', 'Apple Nectar Pokémon', 12, 16, 198, 81, 272, 'When some Lechonk come along to lick the sweet nectar on Appletun''s back, Appletun will spew sticky nectar at them to drive them away.'),
(843, NULL, 'Silicobra', '843.png', 'Sand Snake Pokémon', 5, NULL, 207, 219, 209, 'Silicobra''s large nostrils are specialized for spraying sand, so this Pokémon is not very good at telling apart different smells.'),
(844, NULL, 'Sandaconda', '844.png', 'Sand Snake Pokémon', 5, NULL, 207, 219, 209, 'It will expand its body as much as it can and then contract itself, blasting out sand with enough force to wash away a dump truck.'),
(845, NULL, 'Cramorant', '845.png', 'Gulp Pokémon', 3, 11, 89, NULL, NULL, 'This hungry Pokémon swallows Arrokuda whole. Occasionally, it makes a mistake and tries to swallow a Pokémon other than its preferred prey.'),
(846, NULL, 'Arrokuda', '846.png', 'Rush Pokémon', 11, NULL, 258, NULL, 181, 'Arrokuda can swim quickly only in a straight line. The ones that become sluggish from overeating are the first to be targeted by flocks of Wattrel.'),
(847, NULL, 'Barraskewda', '847.png', 'Skewer Pokémon', 11, NULL, 258, NULL, 181, 'It spins its tail fins to leap from the water, then viciously bites down on Wingull flying close to the water''s surface.'),
(848, NULL, 'Toxel', '848.png', 'Baby Pokémon', 13, 4, 193, 241, 120, 'It has no problem drinking dirty water. An organ inside Toxel''s body filters such water into a poisonous liquid that is harmless to Toxel.'),
(849, NULL, 'Toxtricity', '849.png', 'Punk Pokémon', 13, 4, 185, 169, 265, 'As it scatters toxic sweat and emits electricity, a melody that sounds like it came from a guitar reverberates through the surrounding area.'),
(850, NULL, 'Sizzlipede', '850.png', 'Radiator Pokémon', 10, 7, 69, 299, 67, 'It wraps prey up with its heated body, cooking them in its coils. Once they''re well-done, it will voraciously nibble them down to the last morsel.'),
(851, NULL, 'Centiskorch', '851.png', 'Radiator Pokémon', 10, 7, 69, 299, 67, 'While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs.'),
(852, NULL, 'Clobbopus', '852.png', 'Tantrum Pokémon', 2, NULL, 126, NULL, 265, 'Its tentacles tear off easily, but it isn''t alarmed when that happens—it knows they''ll grow back. It''s about as smart as a three-year-old.'),
(853, NULL, 'Grapploct', '853.png', 'Tantrum Pokémon', 2, NULL, 126, NULL, 265, 'A body made up of nothing but muscle makes the grappling moves this Pokémon performs with its tentacles tremendously powerful.'),
(854, NULL, 'Sinistea', '854.png', 'Black Tea Pokémon', 8, NULL, 297, NULL, 41, 'Some fanatics will go to great pains to prepare the perfect tea and teacup, eagerly waiting for a Sinistea to come and possess their selections.'),
(855, NULL, 'Polteageist', '855.png', 'Black Tea Pokémon', 8, NULL, 297, NULL, 41, 'Apparently a Polteageist''s disposition is affected by the type of tea the Pokémon came from. What teapot it inhabits makes no difference.'),
(856, NULL, 'Hatenna', '856.png', 'Calm Pokémon', 14, NULL, 93, 8, 131, 'Because the emotions of others constantly flow into its head, this Pokémon prefers environments where no other creatures live.'),
(857, NULL, 'Hattrem', '857.png', 'Serene Pokémon', 14, NULL, 93, 8, 131, 'The moment this Pokémon finds someone who''s emitting strong emotions, it will pummel them senseless with its braids to silence them.'),
(858, NULL, 'Hatterene', '858.png', 'Silent Pokémon', 14, 18, 93, 8, 131, 'If you''re too loud around it, you risk being torn apart by the claws on its tentacle. This Pokémon is also known as the Forest Witch.'),
(859, NULL, 'Impidimp', '859.png', 'Wily Pokémon', 17, 18, 177, 76, 166, 'The reason this Pokémon causes trouble for those it feels close to is because Impidimp itself gets irritable if it can''t absorb negative emotions.'),
(860, NULL, 'Morgrem', '860.png', 'Devious Pokémon', 17, 18, 177, 76, 166, 'This Pokémon absorbs negative emotions and turns them into energy. It''s popular with people who tend to think gloomy thoughts.'),
(861, NULL, 'Grimmsnarl', '861.png', 'Bulk Up Pokémon', 17, 18, 177, 76, 166, 'This Pokémon has complete control over its hair. Grimmsnarl normally keeps its hair wrapped around its body to support its muscles.'),
(862, NULL, 'Obstagoon', '862.png', 'Blocking Pokémon', 17, 1, 195, 90, 49, 'Its voice is staggering in volume. Obstagoon has a tendency to take on a threatening posture and shout—this move is known as Obstruct.'),
(863, NULL, 'Perrserker', '863.png', 'Viking Pokémon', 9, NULL, 17, 275, 245, 'What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.'),
(864, NULL, 'Cursola', '864.png', 'Coral Pokémon', 8, NULL, 297, NULL, 165, 'Its shell is overflowing with its heightened otherworldly energy. The ectoplasm serves as protection for this Pokémon''s core spirit.'),
(865, NULL, 'Sirfetch''d', '865.png', 'Wild Duck Pokémon', 2, NULL, 242, NULL, 212, 'After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food.'),
(866, NULL, 'Mr. Rime', '866.png', 'Comedian Pokémon', 15, 14, 263, 213, 103, 'Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly.'),
(867, NULL, 'Runerigus', '867.png', 'Grudge Pokémon', 5, 8, 292, NULL, NULL, 'A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.'),
(868, NULL, 'Milcery', '868.png', 'Cream Pokémon', 18, NULL, 257, NULL, 11, 'This Pokémon was born from sweet-smelling particles in the air. Its body is made of cream.'),
(869, NULL, 'Alcremie', '869.png', 'Cream Pokémon', 18, NULL, 257, NULL, 11, 'The moment it evolved, it took on a bitter flavor. This is because of the way its cells spontaneously shifted during evolution.'),
(870, NULL, 'Falinks', '870.png', 'Formation Pokémon', 2, NULL, 17, NULL, 49, 'The brass, which is the one that stands at the front and issues orders, is the strongest and smartest of the six.'),
(871, NULL, 'Pincurchin', '871.png', 'Sea Urchin Pokémon', 13, NULL, 125, NULL, 61, 'This Pokémon generates electricity when it digests food. It uses its five hard teeth to scrape seaweed off surfaces and eat it.'),
(872, NULL, 'Snom', '872.png', 'Worm Pokémon', 15, 7, 222, NULL, 105, 'It eats snow that has accumulated on the ground. It prefers soft, freshly fallen snow, so it will eat its way up a mountain, aiming for the peak.'),
(873, NULL, 'Frosmoth', '873.png', 'Frost Moth Pokémon', 15, 7, 222, NULL, 105, 'Frosmoth senses air currents with its antennae. It sends its scales drifting on frigid air, making them fall like snow.'),
(874, NULL, 'Stonjourner', '874.png', 'Big Rock Pokémon', 6, NULL, 176, NULL, NULL, 'This Pokémon spends its life gazing at the setting sun. It strides leisurely across grassy plains on legs of rock that weigh over 400 pounds each.'),
(875, NULL, 'Eiscue', '875.png', 'Penguin Pokémon', 15, NULL, 104, NULL, NULL, 'If you lick the ice covering its face, you''ll find it has a faintly salty taste. This species rode here on ocean currents from a cold, faraway land.'),
(876, NULL, 'Indeedee', '876.png', 'Emotion Pokémon', 14, 1, 112, 261, 184, 'This Pokémon picks up on the positive emotions of other creatures via its horns and uses those emotions to fuel itself.'),
(877, NULL, 'Morpeko', '877.png', 'Two-Sided Pokémon', 13, 17, 99, NULL, NULL, 'It carries electrically roasted seeds with it as if they''re precious treasures. No matter how much it eats, it always gets hungry again in short order.'),
(878, NULL, 'Cufant', '878.png', 'Copperderm Pokémon', 9, NULL, 220, NULL, 95, 'Cufant can lift loads weighing five tons. In the mornings, it heads into caves with its herd, in search of the ore on which these Pokémon feed.'),
(879, NULL, 'Copperajah', '879.png', 'Copperderm Pokémon', 9, NULL, 220, NULL, 95, 'Copperajah are prideful, cantankerous Pokémon. Specimens with vibrant green skin command the respect of others of their kind.'),
(880, NULL, 'Dracozolt', '880.png', 'Fossil Pokémon', 13, 16, 291, 100, 206, 'In ancient times, it was unbeatable thanks to its powerful lower body, but it went extinct anyway after it depleted all its plant-based food sources.'),
(881, NULL, 'Arctozolt', '881.png', 'Fossil Pokémon', 13, 15, 291, 241, 227, 'This Pokémon lived on prehistoric seashores and was able to preserve food with the ice on its body. It went extinct because it moved so slowly.'),
(882, NULL, 'Dracovish', '882.png', 'Fossil Pokémon', 11, 16, 293, 249, 206, 'Its mighty legs are capable of running at speeds exceeding 40 mph, but this Pokémon can''t breathe unless it''s underwater.'),
(883, NULL, 'Arctovish', '883.png', 'Fossil Pokémon', 11, 15, 293, 103, 227, 'Though it''s able to capture prey by freezing its surroundings, it has trouble eating the prey afterward because its mouth is on top of its head.'),
(884, NULL, 'Duraludon', '884.png', 'Alloy Pokémon', 9, 16, 124, 95, 238, 'The special metal that composes its body is very light, so this Pokémon has considerable agility. It lives in caves because it dislikes the rain.'),
(885, NULL, 'Dreepy', '885.png', 'Lingering Pokémon', 16, 8, 28, 110, 41, 'If this weak Pokémon is by itself, a mere child could defeat it. But if Dreepy has friends to help it train, it can evolve and become much stronger.'),
(886, NULL, 'Drakloak', '886.png', 'Caretaker Pokémon', 16, 8, 28, 110, 41, 'This Pokémon flies around at over 120 miles per hour. If a Drakloak is defeated in a battle, its Dreepy will wander off without a second thought.'),
(887, NULL, 'Dragapult', '887.png', 'Stealth Pokémon', 16, 8, 28, 110, 41, 'Dragapult can make its whole body transparent by clearing its mind and focusing. Even the Dreepy in Dragapult''s horns become invisible.'),
(888, NULL, 'Zacian', '888.png', 'Warrior Pokémon', 18, NULL, 115, NULL, NULL, 'Known as a legendary hero, this Pokémon absorbs metal particles, transforming them into a weapon it uses to battle.'),
(889, NULL, 'Zamazenta', '889.png', 'Warrior Pokémon', 2, NULL, 46, NULL, NULL, 'Its ability to deflect any attack led to it being known as the Fighting Master''s Shield. It was feared and respected by all.'),
(890, NULL, 'Eternatus', '890.png', 'Gigantic Pokémon', 4, 16, 178, NULL, NULL, 'The core on its chest absorbs energy emanating from the lands of the Galar region. This energy is what allows Eternatus to stay active.'),
(891, NULL, 'Kubfu', '891.png', 'Wushu Pokémon', 2, NULL, 112, NULL, NULL, 'Kubfu trains hard to perfect its moves. The moves it masters will determine which form it takes when it evolves.'),
(892, NULL, 'Urshifu', '892.png', 'Wushu Pokémon', 2, 17, 287, NULL, NULL, 'This form of Urshifu is a strong believer in the one-hit KO. Its strategy is to leap in close to foes and land a devastating blow with a hardened fist.'),
(893, NULL, 'Zarude', '893.png', 'Rogue Monkey Pokémon', 17, 12, 121, NULL, NULL, 'Within dense forests, this Pokémon lives in a pack with others of its kind. It''s incredibly aggressive, and the other Pokémon of the forest fear it.'),
(894, NULL, 'Regieleki', '894.png', 'Electron Pokémon', 13, NULL, 280, NULL, NULL, 'This Pokémon is a cluster of electrical energy. It''s said that removing the rings on Regieleki''s body will unleash the Pokémon''s latent power.'),
(895, NULL, 'Regidrago', '895.png', 'Dragon Orb Pokémon', 16, NULL, 54, NULL, NULL, 'Its body is composed of crystallized dragon energy. Regidrago is said to have the powers of every dragon Pokémon.'),
(896, NULL, 'Glastrier', '896.png', 'Wild Horse Pokémon', 15, NULL, 26, NULL, NULL, 'Glastrier emits intense cold from its hooves. It''s also a belligerent Pokémon—anything it wants, it takes by force.'),
(897, NULL, 'Spectrier', '897.png', 'Swift Horse Pokémon', 8, NULL, 87, NULL, NULL, 'It probes its surroundings with all its senses save one—it doesn''t use its sense of sight. Spectrier''s kicks are said to separate soul from body.'),
(898, NULL, 'Calyrex', '898.png', 'King Pokémon', 14, 12, 286, NULL, NULL, 'Calyrex is a merciful Pokémon, capable of providing healing and blessings. It reigned over the Galar region in times of yore.'),
(899, NULL, 'Wyrdeer', '899.png', 'Big Horn Pokémon', 1, 14, 114, 76, 210, 'The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.'),
(900, NULL, 'Kleavor', '900.png', 'Axe Pokémon', 7, 6, 256, 220, 218, 'A violent creature that fells towering trees with its crude axes and shields itself with hard stone. If one should chance upon this Pokémon in the wilds, one''s only recourse is to flee.'),
(901, NULL, 'Ursaluna', '901.png', 'Peat Pokémon', 5, 1, 90, 24, 286, 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.'),
(902, NULL, 'Basculegion', '902.png', 'Big Fish Pokémon', 11, 8, 258, 1, 144, 'Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.'),
(903, NULL, 'Sneasler', '903.png', 'Free Climb Pokémon', 2, 4, 178, 285, 173, 'Because of Sneasler''s virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.'),
(904, NULL, 'Overqwil', '904.png', 'Pin Cluster Pokémon', 17, 4, 171, 258, 114, 'Its lancelike spikes and savage temperament have earned it the nickname “sea fiend.” It slurps up poison to nourish itself.'),
(905, NULL, 'Enamorus', '905.png', 'Love-Hate Pokémon', 18, 3, 42, NULL, 35, 'When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.'),
(906, NULL, 'Sprigatito', '906.png', 'Grass Cat Pokémon', 12, NULL, 161, NULL, 182, 'The sweet scent its body gives off mesmerizes those around it. The scent grows stronger when this Pokémon is in the sun.'),
(907, NULL, 'Floragato', '907.png', 'Grass Cat Pokémon', 12, NULL, 161, NULL, 182, 'The hardness of Floragato''s fur depends on the Pokémon''s mood. When Floragato is prepared to battle, its fur becomes pointed and needle sharp.'),
(908, NULL, 'Meowscarada', '908.png', 'Magician Pokémon', 12, 17, 161, NULL, 182, 'This Pokémon uses the reflective fur lining its cape to camouflage the stem of its flower, creating the illusion that the flower is floating.'),
(909, NULL, 'Fuecoco', '909.png', 'Fire Croc Pokémon', 10, NULL, 23, NULL, 284, 'Its flame sac is small, so energy is always leaking out. This energy is released from the dent atop Fuecoco''s head and flickers to and fro.'),
(910, NULL, 'Crocalor', '910.png', 'Fire Croc Pokémon', 10, NULL, 23, NULL, 284, 'The combination of Crocalor''s fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon''s head.'),
(911, NULL, 'Skeledirge', '911.png', 'Singer Pokémon', 10, 8, 23, NULL, 284, 'Skeledirge''s gentle singing soothes the souls of all that hear it. It burns its enemies to a crisp with flames of over 5,400 degrees Fahrenheit.'),
(912, NULL, 'Quaxly', '912.png', 'Duckling Pokémon', 11, NULL, 274, NULL, 147, 'Its strong legs let it easily swim around in even fast-flowing rivers. It likes to keep things tidy and is prone to overthinking things.'),
(913, NULL, 'Quaxwell', '913.png', 'Practicing Pokémon', 11, NULL, 274, NULL, 147, 'The hardworking Quaxwell observes people and Pokémon from various regions and incorporates their movements into its own dance routines.'),
(914, NULL, 'Quaquaval', '914.png', 'Dancer Pokémon', 11, 2, 274, NULL, 147, 'Dancing in ways that evoke far-away places, this Pokémon mesmerizes all that see it. Flourishes of its decorative water feathers slice into its foes.'),
(915, NULL, 'Lechonk', '915.png', 'Hog Pokémon', 1, NULL, 11, 81, 272, 'This Pokémon spurns all but the finest of foods. Its body gives off an herblike scent that bug Pokémon detest.'),
(916, NULL, 'Oinkologne', '916.png', 'Hog Pokémon', 1, NULL, 127, 81, 272, 'Oinkologne is proud of its fine, glossy skin. It emits a concentrated scent from the tip of its tail.'),
(917, NULL, 'Tarountula', '917.png', 'String Ball Pokémon', 7, NULL, 113, NULL, 236, 'The thread it secretes from its rear is as strong as wire. The secret behind the thread''s strength is the topic of ongoing research.'),
(918, NULL, 'Spidops', '918.png', 'Trap Pokémon', 7, NULL, 113, NULL, 236, 'It clings to branches and ceilings using its threads and moves without a sound. It takes out its prey before the prey even notices it.'),
(919, NULL, 'Nymble', '919.png', 'Grasshopper Pokémon', 7, NULL, 256, NULL, 273, 'It''s highly skilled at a fighting style in which it uses its jumping capabilities to dodge incoming attacks while also dealing damage to opponents.'),
(920, NULL, 'Lokix', '920.png', 'Grasshopper Pokémon', 7, 17, 256, NULL, 273, 'When it decides to fight all out, it stands on its previously folded legs to enter Showdown Mode. It neutralizes its enemies in short order.'),
(921, NULL, 'Pawmi', '921.png', 'Mouse Pokémon', 13, NULL, 241, 152, 117, 'The pads of its paws are electricity-discharging organs. Pawmi fires electricity from its forepaws while standing unsteadily on its hind legs.'),
(922, NULL, 'Pawmo', '922.png', 'Mouse Pokémon', 13, 2, 291, 152, 117, 'Pawmo uses a unique fighting technique in which it uses its forepaws to strike foes and zap them with electricity from its paw pads simultaneously.'),
(923, NULL, 'Pawmot', '923.png', 'Hands-On Pokémon', 13, 2, 291, 152, 117, 'This Pokémon normally is slow to react, but once it enters battle, it will strike down its enemies with lightning-fast movements.'),
(924, NULL, 'Tandemaus', '924.png', 'Couple Pokémon', 1, NULL, 204, 167, 162, 'Exhibiting great teamwork, they use their incisors to cut pieces out of any material that might be useful for a nest, then make off with them.'),
(925, NULL, 'Maushold', '925.png', 'Family Pokémon', 1, NULL, 75, 25, 265, 'The larger pair protects the little ones during battles. When facing strong opponents, the whole group will join the fight.'),
(926, NULL, 'Fidough', '926.png', 'Puppy Pokémon', 18, NULL, 162, NULL, 120, 'This Pokémon is smooth and moist to the touch. Yeast in Fidough''s breath induces fermentation in the Pokémon''s vicinity.'),
(927, NULL, 'Dachsbun', '927.png', 'Dog Pokémon', 18, NULL, 298, NULL, 11, 'The surface of this Pokémon''s skin hardens when exposed to intense heat, and its body has an appetizing aroma.'),
(928, NULL, 'Smoliv', '928.png', 'Olive Pokémon', 12, 1, 58, NULL, 92, 'This Pokémon converts nutrients into oil, which it stores in the fruit on its head. It can easily go a whole week without eating or drinking.'),
(929, NULL, 'Dolliv', '929.png', 'Olive Pokémon', 12, 1, 58, NULL, 92, 'Dolliv shares its tasty, fresh-scented oil with others. This species has coexisted with humans since times long gone.'),
(930, NULL, 'Arboliva', '930.png', 'Olive Pokémon', 12, 1, 214, NULL, 92, 'This calm Pokémon is very compassionate. It will share its delicious, nutrient-rich oil with weakened Pokémon.'),
(931, NULL, 'Squawkabilly', '931.png', 'Parrot Pokémon', 1, 3, 114, 100, 90, 'These Pokémon prefer to live in cities. They form flocks based on the color of their feathers, and they fight over territory.'),
(932, NULL, 'Nacli', '932.png', 'Rock Salt Pokémon', 6, NULL, 187, 250, 28, 'The ground scrapes its body as it travels, causing it to leave salt behind. Salt is constantly being created and replenished inside Nacli''s body.'),
(933, NULL, 'Naclstack', '933.png', 'Rock Salt Pokémon', 6, NULL, 187, 250, 28, 'It compresses rock salt inside its body and shoots out hardened salt pellets with enough force to perforate an iron sheet.'),
(934, NULL, 'Garganacl', '934.png', 'Rock Salt Pokémon', 6, NULL, 187, 250, 28, 'Garganacl will rub its fingertips together and sprinkle injured Pokémon with salt. Even severe wounds will promptly heal afterward.'),
(935, NULL, 'Charcadet', '935.png', 'Fire Child Pokémon', 10, NULL, 69, NULL, 67, 'Burnt charcoal came to life and became a Pokémon. Possessing a fiery fighting spirit, Charcadet will battle even tough opponents.'),
(936, NULL, 'Armarouge', '936.png', 'Fire Warrior Pokémon', 10, 14, 69, NULL, 297, 'Armarouge evolved through the use of a set of armor that belonged to a distinguished warrior. This Pokémon is incredibly loyal.'),
(937, NULL, 'Ceruledge', '937.png', 'Fire Blades Pokémon', 10, 8, 69, NULL, 297, 'An old set of armor steeped in grudges caused this Pokémon''s evolution. Ceruledge cuts its enemies to pieces without mercy.'),
(938, NULL, 'Tadbulb', '938.png', 'EleTadpole Pokémon', 13, NULL, 162, 241, 43, 'It floats using the electricity stored in its body. When thunderclouds are around, Tadbulb will float higher off the ground.'),
(939, NULL, 'Bellibolt', '939.png', 'EleFrog Pokémon', 13, NULL, 62, 241, 43, 'When this Pokémon expands and contracts its wobbly body, the belly-button dynamo in its stomach produces a huge amount of electricity.'),
(940, NULL, 'Wattrel', '940.png', 'Storm Petrel Pokémon', 13, 3, 301, 291, 33, 'These Pokémon make their nests on coastal cliffs. The nests have a strange, crackling texture, and they''re a popular delicacy.'),
(941, NULL, 'Kilowattrel', '941.png', 'Frigatebird Pokémon', 13, 3, 301, 291, 33, 'Kilowattrel inflates its throat sac to amplify its electricity. By riding the wind, this Pokémon can fly over 430 miles in a day.'),
(942, NULL, 'Maschiff', '942.png', 'Rascal Pokémon', 17, NULL, 114, 204, 236, 'It always scowls in an attempt to make opponents take it seriously, but even crying children will burst into laughter when they see Maschiff''s face.'),
(943, NULL, 'Mabosstiff', '943.png', 'Boss Pokémon', 17, NULL, 114, 88, 236, 'Mabosstiff loves playing with children. Though usually gentle, it takes on an intimidating look when protecting its family.'),
(944, NULL, 'Shroodle', '944.png', 'Toxic Mouse Pokémon', 4, 1, 285, 166, 177, 'To keep enemies away from its territory, it paints markings around its nest using a poisonous liquid that has an acrid odor.'),
(945, NULL, 'Grafaiai', '945.png', 'Toxic Monkey Pokémon', 4, 1, 285, 173, 177, 'The color of the poisonous saliva depends on what the Pokémon eats. Grafaiai covers its fingers in its saliva and draws patterns on trees in forests.'),
(946, NULL, 'Bramblin', '946.png', 'Tumbleweed Pokémon', 12, 8, 302, NULL, 110, 'A soul unable to move on to the afterlife was blown around by the wind until it got tangled up with dried grass and became a Pokémon.'),
(947, NULL, 'Brambleghast', '947.png', 'Tumbleweed Pokémon', 12, 8, 302, NULL, 110, 'Brambleghast wanders around arid regions. On rare occasions, mass outbreaks of these Pokémon will bury an entire town.'),
(948, NULL, 'Toedscool', '948.png', 'Woodear Pokémon', 5, 12, 151, NULL, NULL, 'Though it looks like Tentacool, Toedscool is a completely different species. Its legs may be thin, but it can run at a speed of 30 mph.'),
(949, NULL, 'Toedscruel', '949.png', 'Woodear Pokémon', 5, 12, 151, NULL, NULL, 'It coils its 10 tentacles around prey and sucks out their nutrients, causing the prey pain. The folds along the rim of its head are a popular delicacy.'),
(950, NULL, 'Klawf', '950.png', 'Ambush Pokémon', 6, NULL, 7, 221, 197, 'This Pokémon lives on sheer cliffs. It sidesteps opponents'' attacks, then lunges for their weak spots with its claws.'),
(951, NULL, 'Capsakid', '951.png', 'Spicy Pepper Pokémon', 12, NULL, 27, 113, 120, 'The more sunlight this Pokémon bathes in, the more spicy chemicals are produced by its body, and thus the spicier its moves become.'),
(952, NULL, 'Scovillain', '952.png', 'Spicy Pepper Pokémon', 12, 10, 27, 113, 145, 'The green head has turned vicious due to the spicy chemicals stimulating its brain. Once it goes on a rampage, there is no stopping it.'),
(953, NULL, 'Rellor', '953.png', 'Rolling Pokémon', 7, NULL, 34, NULL, 219, 'It rolls its mud ball around while the energy it needs for evolution matures. Eventually the time comes for it to evolve.'),
(954, NULL, 'Rabsca', '954.png', 'Rolling Pokémon', 7, 14, 261, NULL, 266, 'An infant sleeps inside the ball. Rabsca rolls the ball soothingly with its legs to ensure the infant sleeps comfortably.'),
(955, NULL, 'Flittle', '955.png', 'Frill Pokémon', 14, NULL, 8, 76, 235, 'It spends its time running around wastelands. If anyone steals its beloved berries, it will chase them down and exact its revenge.'),
(956, NULL, 'Espathra', '956.png', 'Ostrich Pokémon', 14, NULL, 158, 76, 235, 'It immobilizes opponents by bathing them in psychic power from its large eyes. Despite its appearance, it has a vicious temperament.'),
(957, NULL, 'Tinkatink', '957.png', 'Metalsmith Pokémon', 18, 9, 144, 162, 166, 'This Pokémon pounds iron scraps together to make a hammer. It will remake the hammer again and again until it''s satisfied with the result.'),
(958, NULL, 'Tinkatuff', '958.png', 'Hammer Pokémon', 18, 9, 144, 162, 166, 'This Pokémon will attack groups of Pawniard and Bisharp, gathering metal from them in order to create a large and sturdy hammer.'),
(959, NULL, 'Tinkaton', '959.png', 'Hammer Pokémon', 18, 9, 144, 162, 166, 'This intelligent Pokémon has a very daring disposition. It knocks rocks into the sky with its hammer, aiming for flying Corviknight.'),
(960, NULL, 'Wiglett', '960.png', 'Garden Eel Pokémon', 11, NULL, 83, 193, 209, 'Though it looks like Diglett, Wiglett is an entirely different species. The resemblance seems to be a coincidental result of environmental adaptation.'),
(961, NULL, 'Wugtrio', '961.png', 'Garden Eel Pokémon', 11, NULL, 83, 193, 209, 'It has a vicious temperament, contrary to what its appearance may suggest. It wraps its long bodies around prey, then drags the prey into its den.'),
(962, NULL, 'Bombirdier', '962.png', 'Item Drop Pokémon', 3, 17, 22, 119, 202, 'Bombirdier uses the apron on its chest to bundle up food, which it carries back to its nest. It enjoys dropping things that make loud noises.'),
(963, NULL, 'Finizen', '963.png', 'Dolphin Pokémon', 11, NULL, 296, NULL, NULL, 'It likes playing with others of its kind using the water ring on its tail. It uses ultrasonic waves to sense the emotions of other living creatures.'),
(964, NULL, 'Palafin', '964.png', 'Dolphin Pokémon', 11, NULL, 306, NULL, NULL, 'Its physical capabilities are no different than a Finizen''s, but when its allies are in danger, it transforms and powers itself up.'),
(965, NULL, 'Varoom', '965.png', 'Single-Cyl Pokémon', 9, 4, 160, NULL, 226, 'The steel section is Varoom''s actual body. This Pokémon clings to rocks and converts the minerals within into energy to fuel its activities.'),
(966, NULL, 'Revavroom', '966.png', 'Multi-Cyl Pokémon', 9, 4, 160, NULL, 66, 'Revavroom viciously threatens others with the sound of its exhaust. It sticks its tongue out from its cylindrical mouth and sprays toxic fluids.'),
(967, NULL, 'Cyclizar', '967.png', 'Mount Pokémon', 16, 1, 219, NULL, 197, 'It can sprint at over 70 mph while carrying a human. The rider''s body heat warms Cyclizar''s back and lifts the Pokémon''s spirit.'),
(968, NULL, 'Orthworm', '968.png', 'Earthworm Pokémon', 9, NULL, 59, NULL, 209, 'When attacked, this Pokémon will wield the tendrils on its body like fists and pelt the opponent with a storm of punches.'),
(969, NULL, 'Glimmet', '969.png', 'Ore Pokémon', 6, 4, 278, NULL, 36, 'Glimmet''s toxic mineral crystals look just like flower petals. This Pokémon scatters poisonous powder like pollen to protect itself.'),
(970, NULL, 'Glimmora', '970.png', 'Ore Pokémon', 6, 4, 278, NULL, 36, 'Glimmora''s petals are made of crystallized poison energy. It has recently become evident that these petals resemble Tera Jewels.'),
(971, NULL, 'Greavard', '971.png', 'Ghost Dog Pokémon', 8, NULL, 167, NULL, 72, 'This friendly Pokémon doesn''t like being alone. Pay it even the slightest bit of attention, and it will follow you forever.'),
(972, NULL, 'Houndstone', '972.png', 'Ghost Dog Pokémon', 8, NULL, 206, NULL, 72, 'Houndstone spends most of its time sleeping in graveyards. Among all the dog Pokémon, this one is most loyal to its master.'),
(973, NULL, 'Flamigo', '973.png', 'Synchronize Pokémon', 3, 2, 212, 263, 37, 'This Pokémon apparently ties the base of its neck into a knot so that energy stored in its belly does not escape from its beak.'),
(974, NULL, 'Cetoddle', '974.png', 'Terra Whale Pokémon', 15, NULL, 272, 229, 220, 'This species left the ocean and began living on land a very long time ago. It seems to be closely related to Wailmer.'),
(975, NULL, 'Cetitan', '975.png', 'Terra Whale Pokémon', 15, NULL, 272, 227, 220, 'Ice energy builds up in the horn on its upper jaw, causing the horn to reach cryogenic temperatures that freeze its surroundings.'),
(976, NULL, 'Veluza', '976.png', 'Jettison Pokémon', 11, 14, 144, NULL, 218, 'Veluza has excellent regenerative capabilities. It sheds spare flesh from its body to boost its agility, then charges at its prey.'),
(977, NULL, 'Dondozo', '977.png', 'Big Catfish Pokémon', 11, NULL, 284, 157, 296, 'This Pokémon is a glutton, but it''s bad at getting food. It teams up with a Tatsugiri to catch prey.'),
(978, NULL, 'Tatsugiri', '978.png', 'Mimicry Pokémon', 16, 11, 32, NULL, 248, 'Tatsugiri is an extremely cunning Pokémon. It feigns weakness to lure in prey, then orders its partner to attack.'),
(979, NULL, 'Annihilape', '979.png', 'Rage Monkey Pokémon', 2, 8, 112, 49, 8, 'It imbues its fists with the power of the rage that it kept hidden in its heart. Opponents struck by these imbued fists will be shattered to their core.'),
(980, NULL, 'Clodsire', '980.png', 'Spiny Fish Pokémon', 4, 5, 171, 293, 284, 'It lives at the bottom of ponds and swamps. It will carry Wooper on its back and ferry them across water from one shore to the other.'),
(981, NULL, 'Farigiraf', '981.png', 'Long Neck Pokémon', 1, 14, 39, 10, 210, 'The hardened head from the tail protects the head of the main body as Farigiraf whips its long neck around to headbutt enemies.'),
(982, NULL, 'Dudunsparce', '982.png', 'Land Snake Pokémon', 1, NULL, 215, 204, 193, 'It drives enemies out of its nest by sucking in enough air to fill its long, narrow lungs, then releasing the air in an intense blast.'),
(983, NULL, 'Kingambit', '983.png', 'Big Blade Pokémon', 17, 9, 49, 254, 178, 'Though it commands a massive army in battle, it''s not skilled at devising complex strategies. It just uses brute strength to keep pushing.'),
(984, NULL, 'Great Tusk', '984.png', 'Paradox Pokémon', 5, 2, 183, NULL, NULL, 'This creature resembles a mysterious Pokémon that, according to a paranormal magazine, has lived since ancient times.'),
(985, NULL, 'Scream Tail', '985.png', 'Paradox Pokémon', 18, 14, 183, NULL, NULL, 'There has been only one reported sighting of this Pokémon. It resembles a mysterious creature depicted in an old expedition journal.'),
(986, NULL, 'Brute Bonnet', '986.png', 'Paradox Pokémon', 12, 17, 183, NULL, NULL, 'It bears a slight resemblance to a Pokémon described in a dubious magazine as a cross between a dinosaur and a mushroom.'),
(987, NULL, 'Flutter Mane', '987.png', 'Paradox Pokémon', 8, 18, 183, NULL, NULL, 'It has similar features to a ghostly pterosaur that was covered in a paranormal magazine, but the two have little else in common.'),
(988, NULL, 'Slither Wing', '988.png', 'Paradox Pokémon', 7, 2, 183, NULL, NULL, 'This Pokémon somewhat resembles an ancient form of Volcarona that was introduced in a dubious magazine.'),
(989, NULL, 'Sandy Shocks', '989.png', 'Paradox Pokémon', 13, 5, 183, NULL, NULL, 'No records exist of this Pokémon being caught. Data is lacking, but the Pokémon''s traits match up with a creature shown in an expedition journal.'),
(990, NULL, 'Iron Treads', '990.png', 'Paradox Pokémon', 5, 9, 188, NULL, NULL, 'This Pokémon closely resembles a scientific weapon that a paranormal magazine claimed was sent to this planet by aliens.'),
(991, NULL, 'Iron Bundle', '991.png', 'Paradox Pokémon', 15, 11, 188, NULL, NULL, 'It resembles a mysterious object mentioned in an old book. There are only two reported sightings of this Pokémon.'),
(992, NULL, 'Iron Hands', '992.png', 'Paradox Pokémon', 2, 13, 188, NULL, NULL, 'It is very similar to a cyborg covered exclusively by a paranormal magazine. The cyborg was said to be the modified form of a certain athlete.'),
(993, NULL, 'Iron Jugulis', '993.png', 'Paradox Pokémon', 17, 3, 188, NULL, NULL, 'It resembles a certain Pokémon introduced in a paranormal magazine, described as the offspring of a Hydreigon that fell in love with a robot.'),
(994, NULL, 'Iron Moth', '994.png', 'Paradox Pokémon', 10, 4, 188, NULL, NULL, 'No records exist of this species being caught. Data is lacking, but the Pokémon''s traits match up with an object described in an old book.'),
(995, NULL, 'Iron Thorns', '995.png', 'Paradox Pokémon', 6, 13, 188, NULL, NULL, 'It has some similarities to a Pokémon introduced in a dubious magazine as a Tyranitar from one billion years into the future.'),
(996, NULL, 'Frigibax', '996.png', 'Ice Fin Pokémon', 16, 15, 271, NULL, 103, 'This Pokémon lives in forests and craggy areas. Using the power of its dorsal fin, it cools the inside of its nest like a refrigerator.'),
(997, NULL, 'Arctibax', '997.png', 'Ice Fin Pokémon', 16, 15, 271, NULL, 103, 'It attacks with the blade of its frozen dorsal fin by doing a front flip in the air. Arctibax''s strong back and legs allow it to pull off this technique.'),
(998, NULL, 'Baxcalibur', '998.png', 'Ice Dragon Pokémon', 16, 15, 271, NULL, 103, 'It launches itself into battle by flipping upside down and spewing frigid air from its mouth. It finishes opponents off with its dorsal blade.'),
(999, NULL, 'Gimmighoul', '999.png', 'Coin Chest Pokémon', 8, NULL, 193, NULL, NULL, 'It lives inside an old treasure chest. Sometimes it gets left in shop corners since no one realizes it''s actually a Pokémon.'),
(1000, NULL, 'Gholdengo', '1000.png', 'Coin Entity Pokémon', 9, 8, 82, NULL, NULL, 'It has a sturdy body made up of stacked coins. Gholdengo overwhelms its enemies by firing coin after coin at them in quick succession.'),
(1001, NULL, 'Wo-Chien', '1001.png', 'Ruinous Pokémon', 17, 12, 262, NULL, NULL, 'The grudge of a person punished for writing the king''s evil deeds upon wooden tablets has clad itself in dead leaves to become a Pokémon.'),
(1002, NULL, 'Chien-Pao', '1002.png', 'Ruinous Pokémon', 17, 15, 259, NULL, NULL, 'This Pokémon can control 100 tons of fallen snow. It plays around innocently by leaping in and out of avalanches it has caused.'),
(1003, NULL, 'Ting-Lu', '1003.png', 'Ruinous Pokémon', 17, 5, 288, NULL, NULL, 'It slowly brings its exceedingly heavy head down upon the ground, splitting the earth open with huge fissures that run over 160 feet deep.'),
(1004, NULL, 'Chi-Yu', '1004.png', 'Ruinous Pokémon', 17, 10, 19, NULL, NULL, 'It controls flames burning at over 5,400 degrees Fahrenheit. It casually swims through the sea of lava it creates by melting rock and sand.'),
(1005, NULL, 'Roaring Moon', '1005.png', 'Paradox Pokémon', 16, 17, 183, NULL, NULL, 'According to an article in a dubious magazine, this Pokémon has some connection to a phenomenon that occurs in a certain region.'),
(1006, NULL, 'Iron Valiant', '1006.png', 'Paradox Pokémon', 18, 2, 188, NULL, NULL, 'It has some similarities to a mad scientist''s invention covered in a paranormal magazine.'),
(1007, NULL, 'Koraidon', '1007.png', 'Paradox Pokémon', 2, 16, 159, NULL, NULL, 'This Pokémon resembles Cyclizar, but it is far burlier and more ferocious. Nothing is known about its ecology or other features.'),
(1008, NULL, 'Miraidon', '1008.png', 'Paradox Pokémon', 13, 16, 91, NULL, NULL, 'This seems to be the Iron Serpent mentioned in an old book. The Iron Serpent is said to have turned the land to ash with its lightning.'),
(1009, NULL, 'Walking Wake', '1009.png', 'Paradox Pokémon', 11, 16, 183, NULL, NULL, 'It resembles an illustration published in a paranormal magazine, said to be a depiction of a super-ancient Suicune.'),
(1010, NULL, 'Iron Leaves', '1010.png', 'Paradox Pokémon', 12, 14, 188, NULL, NULL, 'Many of its physical characteristics match those of a Virizion from the future that was covered in a paranormal magazine.'),
(1011, NULL, 'Dipplin', '1011.png', 'Candy Apple Pokémon', 12, 16, 253, 81, 247, 'The head sticking out belongs to the fore-wyrm, while the tail belongs to the core-wyrm. The two share one apple and help each other out.'),
(1012, NULL, 'Poltchageist', '1012.png', 'Matcha Pokémon', 12, 8, 97, NULL, 94, 'Supposedly, the regrets of a tea ceremony master who died before perfecting his craft lingered in some matcha and became a Pokémon.'),
(1013, NULL, 'Sinistcha', '1013.png', 'Matcha Pokémon', 12, 8, 97, NULL, 94, 'It pretends to be tea, trying to fool people into drinking it so it can drain their life-force. Its ruse is generally unsuccessful.'),
(1014, NULL, 'Okidogi', '1014.png', 'Retainer Pokémon', 4, 2, 277, NULL, 88, 'After all its muscles were stimulated by the toxic chain around its neck, Okidogi transformed and gained a powerful physique.'),
(1015, NULL, 'Munkidori', '1015.png', 'Retainer Pokémon', 4, 14, 277, NULL, 76, 'Munkidori keeps itself somewhere safe while it toys with its foes, using psychokinesis to induce intense dizziness.'),
(1016, NULL, 'Fezandipiti', '1016.png', 'Retainer Pokémon', 4, 18, 277, NULL, 265, 'Fezandipiti owes its beautiful looks and lovely voice to the toxic stimulants emanating from the chain wrapped around its body.'),
(1017, NULL, 'Ogerpon', '1017.png', 'Mask Pokémon', 12, NULL, 49, NULL, 63, 'This Pokémon''s type changes based on which mask it''s wearing. It confounds its enemies with nimble movements and kicks.'),
(1018, NULL, 'Archaludon', '1018.png', 'Alloy Pokémon', 9, 16, 239, 250, 238, 'It gathers static electricity from its surroundings. The beams it launches when down on all fours are tremendously powerful.'),
(1019, NULL, 'Hydrapple', '1019.png', 'Apple Hydra Pokémon', 12, 16, 253, 197, 247, 'Seven syrpents live inside an apple made of syrup. The syrpent in the center is the commander.'),
(1020, NULL, 'Gouging Fire', '1020.png', 'Paradox Pokémon', 10, 16, 183, NULL, NULL, 'It resembles an eerie Pokémon once shown in a paranormal magazine. That Pokémon was said to be an Entei regenerated from a fossil.'),
(1021, NULL, 'Raging Bolt', '1021.png', 'Paradox Pokémon', 13, 16, 183, NULL, NULL, 'It bears resemblance to a Pokémon that became a hot topic for a short while after a paranormal magazine touted it as Raikou''s ancestor.'),
(1022, NULL, 'Iron Boulder', '1022.png', 'Paradox Pokémon', 6, 14, 188, NULL, NULL, 'It resembles a Pokémon described in a dubious magazine as a Terrakion that had been modified by an evil organization.'),
(1023, NULL, 'Iron Crown', '1023.png', 'Paradox Pokémon', 9, 14, 188, NULL, NULL, 'It resembles a mysterious object introduced in a paranormal magazine as a cutting-edge weapon shaped like a Cobalion.'),
(1024, NULL, 'Terapagos', '1024.png', 'Tera Pokémon', 1, NULL, 268, NULL, 267, 'Terapagos protects itself using its power to transform energy into hard crystals. This Pokémon is the source of the Terastal phenomenon.'),
(1025, NULL, 'Pecharunt', '1025.png', 'Subjugation Pokémon', 4, 8, 172, NULL, NULL, 'It feeds others toxic mochi that draw out desires and capabilities. Those who eat the mochi fall under Pecharunt''s control, chained to its will.');
